/* 由 tools/build_lib.js 从 tools/lib_notes/tangjin/*.json 组装，请勿手改。 */
LIT.addLibNotes({"tangjin_lvye":{"intro":"这首五律一般认为作于杜甫离开成都、乘舟东下的途中（多系于永泰元年即765年，也有大历年间之说，存疑）。前四句写江夜之景，后四句自叹身世，最后落在“天地一沙鸥”的自比上。读它要看杜甫怎样把极大的天地和极小的自己放进同一个画面。","focus":["首联“细草微风岸，危樯独夜舟”从近处、小处写起：岸边细草、一根高桅、一只夜舟。“独”字把人藏在舟里，还没有写情，景里已经有了孤单。","颔联“星垂平野阔，月涌大江流”突然放大：星星低垂，是因为原野平阔；月影随波涌动，是因为大江奔流。阔大的天地反衬舟中人的渺小，这一联常被拿来和李白“山随平野尽，江入大荒流”对读。","颈联“名岂文章著，官应老病休”是反话：名声难道要靠文章得来？官职却说是因老病而罢。杜甫离开成都前已辞去幕府之职，偏说老病该休，话里有不平；尾联以“天地一沙鸥”作答，漂泊之感落到一个具体的形象上。"],"notes":[["危樯","高高的桅杆"],["独夜舟","夜里孤零零的一只船"],["星垂","星星低垂，好像挨着地平线"],["平野","平坦辽阔的原野"],["月涌","月影随江波涌动"],["著","显扬、著名"],["官应","官职应当"],["休","罢休，这里指罢官"],["飘飘","飘泊不定的样子"],["沙鸥","栖息在沙洲上的鸥鸟"]],"think":["“名岂文章著”到底是自谦还是自负？","字面是“名声哪里是靠文章得来的”，像自谦；但杜甫一生以“致君尧舜”自期，文章在他心里只是余事，这句反过来透出抱负落空的不甘。结合下句“官应老病休”的反语，可以判断它更偏牢骚而不是谦辞，但要承认这是一种解读，不是定论。"],"quiz":[["“星垂平野阔”中，“垂”和“阔”的关系是？",["星星低垂，显出原野辽阔","星星垂落，象征时间流逝","原野辽阔，使星星显得稀少"],"星星仿佛低垂到地平线，正因为原野平坦辽阔、一望无际。"],["颈联“官应老病休”的语气最接近？",["反语里的牢骚","真心认为该退休","对朝廷的感激"],"表面说官职因老病该罢，实则心有不甘，语带反讽。"],["尾联“天地一沙鸥”在全诗中的作用是？",["自比收束，回答“何所似”","补写夜景中的一只鸟","表达对自由的向往"],"上句自问“飘飘何所似”，下句以天地间一只沙鸥作答，把漂泊身世收进一个形象。"]],"cards":[["星垂平野阔，下句是？","月涌大江流。"],["《旅夜书怀》的结构？","前四句江夜之景，由小到大；后四句自叹身世，以“天地一沙鸥”自比收束。"]],"line":["飘飘何所似，天地一沙鸥","被派到外地独自扛项目的第一个晚上，给老朋友发消息：飘飘何所似，天地一沙鸥——不过这只沙鸥明天还得开会。"],"tags":["五律","羁旅","杜甫"]},"tangjin_wangyue":{"intro":"张九龄是开元年间的名相，被排挤出朝后任荆州长史，这首诗一般认为作于此时（具体年份存疑）。五律的前两句常被当成典范：不写“我思念你”，先写一轮海上明月，再把天涯两端的人拉到同一个时刻。读它要看抒情怎样从大景起步，一步步收到个人身上。","focus":["首联“海上生明月，天涯共此时”是倒着写的：先有明月，再有“共此时”。月亮把两个相隔万里的人放到同一时间里，思念不靠形容，靠一个共享的事实成立。后世“海上升明月”的句式化用无数，根子在这一联。","颔联“情人怨遥夜，竟夕起相思”把“怨”落到长夜上。注意“竟夕”：整夜。月亮越明，夜越长，人越睡不着，前面大景到这里收成了具体的失眠。","颈联“灭烛怜光满，披衣觉露滋”是全诗最细的地方：吹灭蜡烛，才看见满屋月光；披上衣服，才觉得夜露沾身。两个动作只写人，不写情，思念藏在“怜”和“觉”里。尾联“不堪盈手赠”说月光捧不起来，没法送你，只好回去睡，指望梦里相会。"],"notes":[["遥夜","漫长的夜"],["竟夕","整夜，通宵"],["怜","爱惜、喜爱"],["光满","月光洒满屋内"],["滋","沾湿，润泽"],["不堪","经受不住，这里指不能够"],["盈手赠","捧满一手送给对方"],["佳期","美好的相会之期，这里指梦中相会"],["天涯","天边，指极远的地方"],["情人","多情的人，此处指怀念远人的人"]],"think":["“灭烛怜光满”为什么要先灭烛？","灭烛之前，满屋是烛光，月光被压住了；烛灭，月光才显出来。这是一个很小的因果，却说明诗人在深夜里一直醒着、一直在看。这种“动作先于感受”的写法，比直接说“我很想念”更让人信，也不容易写俗。"],"quiz":[["“天涯共此时”的妙处主要在于？",["以共享同一时刻拉近相隔的两地","点明诗人所在的地点","暗示月亮从海上升起的时辰","说明两人同时入睡"],"重点是“共”：人不能相见，但看到的是同一轮月，诗人用这个共同点把距离压缩了。"],["“不堪盈手赠”的意思最接近？",["月光不能捧一手送给你","月光太亮让人无法忍受","手里拿不动赠礼","不愿意接受别人的赠送"],"“盈手”是捧满一手，月光捧不住，无法寄给远人，于是只好“还寝梦佳期”。"]],"cards":[["“海上生明月”的下一句？","天涯共此时。"],["《望月怀远》颈联的两个动作？","灭烛，披衣；先看见月光，再觉出夜露，思念落在动作上。"]],"line":["海上生明月，天涯共此时","跨时区的季度电话会开场，对海外同事说：海上生明月，天涯共此时——虽然你那边是早晨，我这边已是深夜。"],"tags":["五律","怀远","月"]},"tangjin_songdu":{"intro":"王勃送一位姓杜的少府去四川赴任（杜少府其人不详）。初唐的送别诗多半伤感，这首偏偏在中间翻出“海内存知己，天涯若比邻”，反过来安慰离别的人。读它要抓住“起承转合”的节奏：先写地，再写别，再宽慰，最后收住不哭。","focus":["首联“城阙辅三秦，风烟望五津”一边是长安城阙有关中拱卫，一边是远处蜀中的渡口；一个“望”字，把两端的空间连起来。这是一个从送行人所在向被送者去处的视线移动。","颔联“与君离别意，同是宦游人”是转折点：我也是漂泊为官的人，同一个处境，离别就不只是你的事。这句把送别者与被送者放到同一边，是全诗情绪的支点。","颈联“海内存知己，天涯若比邻”以近代口吻读很顺，但在唐代是新气象：天涯不必是隔绝，有知己就等于在隔壁。尾联“无为在歧路，儿女共沾巾”直接劝：不要像小儿女那样在岔路口抹泪。全诗的立场到这里完整。"],"notes":[["城阙","城楼和宫阙，指长安"],["辅","辅卫、拱卫"],["三秦","关中一带，项羽曾把关中分为三个王国"],["风烟","风景烟云，指远景"],["五津","蜀中岷江上的五个渡口"],["宦游","为做官而在外漂泊"],["知己","相知相契的朋友"],["比邻","邻居"],["歧路","岔路，分手的路口"],["沾巾","眼泪沾湿手巾"]],"think":["这首诗说“无为在歧路，儿女共沾巾”，是不是在批评哭的人？","不是批评，而是劝慰。前面两联已经把理由讲完：大家同是漂泊者，知己不会因远而断。所以尾联的口气更像“别让伤心压倒了这份达观”。送别诗可以悲，但王勃选择了把悲放到一边。这个选择与他一贯的少年昂扬有关，但“一贯”只是读诗的判断，不必当史实。"],"quiz":[["“与君离别意，同是宦游人”在全诗中的作用是？",["拉平送别双方的处境，引出后面的宽慰","说明两人都被贬官","点明这次离别发生在秋天","解释为何要去蜀川"],"“同是”二字把送行者与远行者放在同一处境，后面“海内存知己”的达观才有了依据。"],["“儿女共沾巾”中的“儿女”指？",["像小儿女一样多愁善感的人","诗人和朋友的子女","离别时前来送行的亲属","蜀中的少年男女"],"这里不是真指子女，而是说在分别路口像小儿女那样流泪，与“无为”连起来是劝人不要如此。"]],"cards":[["“海内存知己”的下一句？","天涯若比邻。"],["《送杜少府之任蜀川》的情绪转折在哪一联？","颔联“同是宦游人”由伤别转到共情，颈联再翻出达观。"]],"line":["海内存知己，天涯若比邻","老同事被外派到海外分公司，送行聚餐上说：海内存知己，天涯若比邻——有事发消息，别当我换了时区就换了人。"],"tags":["五律","送别","初唐"]},"tangjin_zaiyu":{"intro":"骆宾王因事下狱，在狱中见槐树上的秋蝉，写下这首咏物诗，前面还附一篇骈文序。咏物诗最怕空泛，这首的特点是处处在写蝉也处处在写人：蝉被秋露与风压着，人被冤案与时势压着。序文可以先扫一遍，重点放在诗的八句。","focus":["首联“西陆蝉声唱，南冠客思侵”：西陆指秋天，南冠是楚囚的典故，借指囚徒。时节与身份并排放在一联里，蝉声与客思互相“侵”，听觉一落，愁绪就进来了。","颔联“那堪玄鬓影，来对白头吟”用了一个对比：玄鬓是黑发，蝉的黑翅像年轻的鬓影；白头吟是诗人自己的悲吟。蝉的年轻与人的苍老同时出现，反差越大，越显得人不堪。","颈联“露重飞难进，风多响易沈”是全诗的核心：蝉被露水压得飞不动，声音被风吹散。这是蝉，也是被诬陷的人，想说话说不出来。尾联“无人信高洁，谁为表予心”把咏物彻底落到自己身上。蝉向来被看作高洁的象征，诗人的悲哀就在“无人信”。"],"notes":[["西陆","指秋天，古人以太阳行至西陆为秋"],["南冠","楚囚之冠，代指囚犯"],["客思","身在异乡的愁思"],["玄鬓","黑发，这里也比蝉的黑色翅翼"],["白头吟","乐府曲名，此处指自己悲愁的吟咏"],["露重","露水沉重"],["响易沈","蝉声容易被风声淹没"],["高洁","品格高尚纯洁"],["表予心","表白我的心迹"],["禁垣","囚禁之所的围墙"]],"think":["咏物诗怎样才算“不空”？","一条判断标准是：把诗里的“蝉”换成“人”，句子是否依然成立。“露重飞难进，风多响易沈”换成人，是处境被压、声音被盖；“无人信高洁”换成人，是清白无从自证。这首诗的好处在于蝉与人互通到不必另加说明。"],"quiz":[["“南冠客思侵”中的“南冠”指？",["囚犯","南方的官帽","远行的商人","隐居的高士"],"南冠出自楚国钟仪戴南冠被囚的典故，诗里用来指身在狱中的自己。"],["颈联“露重飞难进，风多响易沈”表面写蝉，实际写？",["诗人遭受压力、无法申诉的处境","诗人对秋景的欣赏","诗人想要逃出监狱","诗人对蝉鸣的赞美"],"蝉被露压住、被风吹散，对应诗人身陷冤狱、声音无人听见的处境。"]],"cards":[["骆宾王《在狱咏蝉》的尾联？","无人信高洁，谁为表予心。"],["咏物诗的最高境界之一？","物与人互通，换个主语读也成立。"]],"line":["无人信高洁，谁为表予心","项目被误判之后，心里有话却没处说，写在日记里：无人信高洁，谁为表予心——然后第二天还是把复盘材料老老实实补齐。"],"tags":["五律","咏物","初唐"]},"tangjin_beigu":{"intro":"王湾是盛唐诗人，诗作传世不多。这首写他舟行江南、泊于北固山下，是“盛唐气象”常被举的小样本：开阔、明朗，最后一笔才轻轻落到乡愁。读它要看三联之间怎样由远到近、由景到情。","focus":["首联“客路青山外，行舟绿水前”以“青山”“绿水”两色起笔，把前行方向讲清：路在山外，船在水前。人是“客”，但这里还没有愁，只是介绍视野。","颔联“潮平两岸阔，风正一帆悬”是全诗最疏朗的一联：潮涨到与岸齐平，岸才显得宽；风顺，帆才悬得稳。两句都是因果，“平”“正”二字写出行舟的顺畅，情绪是向上的。","颈联“海日生残夜，江春入旧年”最有名：太阳从海上升起，夜还没有退尽；春意进入江南，旧年还没过完。时间在这里发生交叠，自然景物像推门入屋。尾联“乡书何处达，归雁洛阳边”才转到乡愁，请归雁带信到洛阳，前面的明亮反衬出这一点思念。"],"notes":[["客路","旅途"],["潮平","江潮涨到与岸齐平"],["风正","风向顺，风势正好"],["悬","挂着，指船帆高挂"],["残夜","将尽的夜"],["旧年","过去的一年"],["乡书","家书"],["归雁","北归的大雁"],["洛阳","诗人故乡一带"],["行舟","行驶的船"]],"think":["颈联“江春入旧年”为什么常被赞为“有理趣”？","因为它写的是时间的重叠：腊月里已经感受到了春意。自然界不管历法的分界，春天在旧年未完时就悄悄进来了。这个观察既真实，又暗含“新旧交替”的人生感，不用说教就带出了一点哲理。"],"quiz":[["“海日生残夜”的写景特点是？",["夜与日同时存在，写时间交接","描写夜晚的黑暗","描写海上的风浪","说明太阳已升到中天"],"“残夜”未尽而“海日”已生，是天将亮未亮的交接时刻。"],["全诗情绪的走向是？",["前面明朗开阔，结尾转入思乡","始终悲伤","由悲转喜","通篇讽刺"],"前三联写景开阔，尾联才点出乡书与归雁，以景衬情。"]],"cards":[["“海日生残夜”的下一句？","江春入旧年。"],["《次北固山下》尾联的情感？","托归雁寄家书，由开阔转入乡愁。"]],"line":["海日生残夜，江春入旧年","年末加班到天亮，看见窗外泛白，在群里发：海日生残夜，江春入旧年——新一年的事情，已经偷偷提前来了。"],"tags":["五律","羁旅","盛唐"]},"tangjin_pospo":{"intro":"常建是盛唐诗人，这首写清晨进入破山寺（在今江苏常熟虞山）后院的所见所感。它是“以静写禅”的名作：没有一个字说“禅”，却处处是禅意。读它要抓住从入寺、深入、凝神到寂静的递进。","focus":["首联“清晨入古寺，初日照高林”：时间是清晨，地点是古寺，光线是初日。三个词一放，一幅干净的画就出来了，也预备了后面的“静”。","颔联“曲径通幽处，禅房花木深”是千古名联：路是曲的，走到的地方是“幽”的，禅房被花木藏起来。“曲”“幽”“深”三个字层层向里推，像把人一步步引进更安静的地方。","颈联“山光悦鸟性，潭影空人心”把外景与心境对接：山光让鸟快乐，潭影让人心空。“空”是佛家的关键词，但诗里它是一种体验：看着潭水映出影子，杂念也跟着没了。尾联“万籁此俱寂，但余钟磬音”以声写静：只剩钟磬，其他声音都停了，这个“余”字最关键。"],"notes":[["古寺","古老的寺庙"],["初日","刚升起的太阳"],["高林","高大的树林"],["曲径","弯曲的小路"],["幽处","幽深僻静的地方"],["禅房","僧人修行的房间"],["悦鸟性","使鸟的本性欢悦"],["潭影","水潭中映出的影子"],["万籁","一切声响"],["钟磬","寺庙的钟与磬，法器"]],"think":["“万籁此俱寂，但余钟磬音”为什么写声音反而更静？","钟磬声是有声音的，但它是诗里唯一剩下的声音，其余全部消失，于是钟磬声反过来成了静的尺度。更妙的是，钟磬声在寂静中回荡，余音越长，静越深。这种以声衬静的写法在古诗里很常见，这一联是最干净的例子。"],"quiz":[["“潭影空人心”中的“空”最接近？",["使人心澄净、杂念消散","使人心感到空虚","说明潭水干涸","表示人心被抽空"],"“空”在这里是使动用法，潭影让人心里的杂念都空掉，带佛家意味。"],["颔联“曲径通幽处”的描写顺序是？",["由路到幽处再到房","由房到路","由花到房","由寺外到寺门"],"“曲径”“幽处”“禅房”“花木深”，是一步步向里推进。"]],"cards":[["“曲径通幽处”的下一句？","禅房花木深。"],["《题破山寺后禅院》写“静”的方式？","以钟磬余音反衬万籁俱寂。"]],"line":["万籁此俱寂，但余钟磬音","开了一天会，晚上关掉所有通知，只留一个闹钟：万籁此俱寂，但余钟磬音。"],"tags":["五律","禅意","盛唐"]},"tangjin_zengmeng":{"intro":"李白写给孟浩然的赠诗。孟浩然年长于李白，终身未仕，隐居襄阳一带。这首诗不用典、不绕弯，开头就直说“吾爱孟夫子”，是李白式的热情。读它要看诗人怎样用八句话为一个人定像：风流、弃官、醉月、迷花，最后落到仰慕。","focus":["首联“吾爱孟夫子，风流天下闻”开口就是表态。“爱”字直白，“风流”二字是对孟浩然人品气度的判断：有名士风度，不拘俗。这种开法在讲究含蓄的五律里很少见，李白敢这么写，因为后面有内容撑着。","颔联“红颜弃轩冕，白首卧松云”把孟浩然的一生压成一对：年轻时弃了官位，白头时仍卧在山林间。“红颜”对“白首”是时间对比，“轩冕”对“松云”是价值对比。这一联用事实而不用形容。","颈联“醉月频中圣，迷花不事君”是全诗最见李白本色的一句：月下饮酒，常常醉到“中圣”（古人以清酒为圣）；迷恋花木，不肯侍奉君王。最后“高山安可仰，徒此挹清芬”把意思收成一句：高山无法仰望，只能在这里领略一点清香。"],"notes":[["孟夫子","对孟浩然的尊称"],["风流","风雅潇洒，有名士气度"],["红颜","年轻时"],["轩冕","官员的车驾和礼帽，代指官位"],["白首","白发，老年"],["松云","松树与云，代指山林隐居"],["中圣","醉酒，古人称清酒为圣人"],["迷花","迷恋花木"],["高山安可仰","高山怎么能够仰望，语出《诗经》"],["挹清芬","汲取一点清雅的芳香"]],"think":["“迷花不事君”算不算李白对自己的投射？","有一部分是。李白也曾入朝又离开，也爱酒爱花；但把“不事君”全算成李白的自画像，容易过度。更稳妥的读法是：李白欣赏孟浩然，是因为孟浩然做到了他自己既向往又没能完全做到的事。这种“借赞人而照见己”的读法是推断，不是定论。"],"quiz":[["“红颜弃轩冕，白首卧松云”的写法是？",["以时间对照和价值对照写孟浩然的一生","记叙孟浩然的具体经历","讽刺孟浩然不求上进","说明孟浩然年少老成"],"“红颜”对“白首”，“轩冕”对“松云”，两组对比概括出弃官归隐的一生。"],["尾联“高山安可仰”用的是？",["以高山比人格，表达仰慕","描写眼前的景物","说明孟浩然住在山上","表示自己想隐居"],"高山是人格崇高的比喻，说“安可仰”是说难以企及，反衬出敬意。"]],"cards":[["“吾爱孟夫子”的下一句？","风流天下闻。"],["《赠孟浩然》为什么直白却不浅？","开头直说，后面用事实和对比撑住，落到仰慕上。"]],"line":["高山安可仰，徒此挹清芬","读完一位老前辈的访谈，只想说一句：高山安可仰，徒此挹清芬。"],"tags":["五律","赠答","李白"]},"tangjin_songyou":{"intro":"这首送别诗以工整闻名：首联对仗，颔联、颈联又各自对仗，几乎通篇是对句，却一点不板。它从“地”入手，到“人”结束，中间用浮云、落日做比，最后以马鸣收住，余音很长。读它要看对仗怎样不压住情感。","focus":["首联“青山横北郭，白水遶东城”不像一般律诗在第一联散开，而是直接对仗：青山对白水，北郭对东城，一横一遶，城外的景致像一幅画框，把送别的现场框住了。","颔联“此地一为别，孤蓬万里征”转入别情：一旦在这里分手，朋友就像孤独的飞蓬，被风吹向万里之外。“孤蓬”一词把漂泊感写得很具体。","颈联“浮云游子意，落日故人情”是公认的名对：游子像浮云，随风去留不定；故人像落日，缓缓下沉，不忍离去。以景喻情，却不说“如”，两个意象并排，让读者自己体会。尾联“挥手自兹去，萧萧班马鸣”只写动作和声音，不写表情，马的嘶鸣替人说出了不舍。"],"notes":[["北郭","城的北面外城"],["东城","城东"],["遶","环绕"],["孤蓬","孤零零的飞蓬，比漂泊的人"],["征","远行"],["游子","离家远行的人"],["故人","老朋友"],["兹","此，这里"],["萧萧","马嘶声"],["班马","离群的马"]],"think":["为什么送别诗常用“马鸣”收尾，而不是写人的话？","因为人的话容易俗，也容易说尽。马是通人性的，马鸣有声却无语，把不舍留给读者填。李白这里没写任何人说了什么，只写“挥手”“马鸣”，给了读者最大的想象空间。"],"quiz":[["“浮云游子意，落日故人情”的手法是？",["以景物比喻两方的心情","直接叙述两人经历","对比山水与城郭","描写傍晚的天色"],"浮云比游子意，落日比故人情，景物并列而不加解释。"],["尾联“萧萧班马鸣”的作用是？",["以声音代替言语，写不舍","交代朋友所骑的马","点明时间是早晨","说明路途遥远"],"诗人不写人说什么，只写离群的马长鸣，让不舍之情留在声音里。"]],"cards":[["“浮云游子意”的下一句？","落日故人情。"],["《送友人》的特点？","通篇对仗工整，情感却自然，以景喻情，以声收尾。"]],"line":["浮云游子意，落日故人情","机场送别，不想多说：浮云游子意，落日故人情。"],"tags":["五律","送别","李白"]},"tangjin_jingmen":{"intro":"这首诗一般认为是李白青年时出蜀远游，经荆门山一带所作。他生长在蜀地，这是第一次见到平原大江，视野一下子打开。读它要抓住两个方向：向前看是“大荒”“天镜”“海楼”，向后看是“故乡水”，一出一入，写出少年远行的心情。","focus":["颔联“山随平野尽，江入大荒流”是视角的转换：蜀地山多，出了荆门，山势逐渐消失在平原上，江水流入旷远的荒野。“随”“入”两字让山水似乎有了脚步，诗人是在船上看着地形一路变化。","颈联“月下飞天镜，云生结海楼”写奇景：月亮映在江面，像从天上飞下的镜子；云在天边堆叠，好像海市蜃楼。这是想象与实景合写，说明年轻的诗人对新的世界充满惊奇。","尾联“仍怜故乡水，万里送行舟”一转：我仍然爱怜故乡的水，它万里相送。远游的兴奋里收进一点依恋，使全诗不只是开阔，也有温度。对比杜甫《旅夜书怀》的“星垂平野阔，月涌大江流”，李白是少年出蜀的明朗，杜甫是晚年漂泊的沉郁，可对读。"],"notes":[["荆门","荆门山，在今湖北宜都一带"],["楚国","指古楚地，今湖北湖南一带"],["平野","平坦的原野"],["大荒","广阔荒远的旷野"],["天镜","天上的镜子，比月影"],["海楼","海市蜃楼"],["怜","爱怜，爱惜"],["故乡水","指从蜀地流来的长江水"],["送行舟","送着行船"],["渡远","远渡"]],"think":["“山随平野尽”和杜甫“星垂平野阔”各自强调什么？","李白强调“尽”：山到这里消失，视野由封闭到开阔，是一个转折点。杜甫强调“阔”：星低垂是因为野平阔，是静态的宽广。李白写的是行进中的变化，杜甫写的是定格后的辽远。两者可并读，但年代与心境不同，不必强分高低。"],"quiz":[["“山随平野尽”写出了什么？",["出蜀后山势渐消、地势变平","诗人登山的经过","平野上的山很多","山与野一样高"],"“随”字写出山顺着平原逐渐消失，也点出蜀地山多、荆门之外平原开阔的对比。"],["尾联“仍怜故乡水”的情感是？",["对故乡的依恋","对旅途的厌倦","对江水的畏惧","对家人的埋怨"],"“怜”是怜爱，故乡水万里相送，表达依恋，使开阔的诗里有一点温情。"]],"cards":[["“山随平野尽”的下一句？","江入大荒流。"],["《渡荆门送别》结尾的情感？","在新天地里仍怜故乡水，开阔里有依恋。"]],"line":["仍怜故乡水，万里送行舟","在海外读书的孩子发消息说想家，回他：仍怜故乡水，万里送行舟——水会送你，家人也会。"],"tags":["五律","远游","李白"]},"tangjin_yueshe":{"intro":"这首作于乾元二年（759）秋，杜甫流寓秦州，安史之乱还没平息，兄弟星散。它的好处是平静：没有激烈的控诉，全靠“戍鼓”“雁声”“白露”“明月”这些秋天的景象和几句家常话，把乱世里的思念写到骨子里。","focus":["首联“戍鼓断人行，秋边一雁声”：戍鼓一响，路上断了行人；塞边秋天只有一声雁叫。孤雁在古诗里是兄弟离散的象征，一个“一”字，把全诗的孤独定在这里。","颔联“露从今夜白，月是故乡明”是名句，写法有意思：露水从今夜开始白，是节气（白露）的提示，是真景；“月是故乡明”是主观感受，月亮其实一样，是人的心觉得故乡的明。前后一实一虚，不用解释就让人懂。","颈联“有弟皆分散，无家问死生”用最平的话说最重的事：弟弟们都分散了，家也没了，连生死都无处打听。尾联“寄书长不达，况乃未休兵”把一切推回战争：信常常送不到，何况兵还没停。"],"notes":[["戍鼓","边防驻军的鼓声"],["断人行","禁止行人，路断人稀"],["秋边","秋天的边地"],["露从今夜白","指白露节气，露水自今夜起显白"],["故乡明","故乡的月亮更明亮"],["有弟","指兄弟，诗里说弟弟们"],["分散","离散各处"],["问死生","打听生死"],["寄书","寄信"],["未休兵","战事没有停止"]],"think":["“月是故乡明”是错觉还是真理？","从物理上讲，月亮到哪里都一样；这句诗说的却是人心的真实。它的力量在于承认“主观”：不是月亮变了，是看月亮的人变了。这样的诗句不需要科学反驳，因为它本来就不是在陈述天文。"],"quiz":[["“露从今夜白”交代了什么？",["节气到了白露，天气转凉","这夜下了大雪","诗人头发变白","月光洒在露上"],"“白露”是节气名，“从今夜”说明节令转换，也含时间推移的感慨。"],["“月是故乡明”的特点是？",["把主观感受写成判断，不必论证","用科学事实证明故乡月亮更亮","描写故乡的夜景","批评他乡的月亮"],"这句是把心理感受直接写成断言，真正动人的恰是这种不讲理的深情。"]],"cards":[["“露从今夜白”的下一句？","月是故乡明。"],["《月夜忆舍弟》颈联写了什么？","兄弟离散、无家可问，生死不知。"]],"line":["露从今夜白，月是故乡明","白露那天在外地出差，随手发了个朋友圈：露从今夜白，月是故乡明。"],"tags":["五律","思乡","杜甫"]},"tangjin_tianmo":{"intro":"乾元二年（759）杜甫在秦州，听说李白因永王事件流放夜郎，却不知道李白已在途中遇赦。他写下这首诗，寄给远在江湖的朋友。它是杜甫“怀李白”系列中最深的一首：不止于想念，还看到了李白的命运。","focus":["首联“凉风起天末，君子意如何”以问起，问的是一个远在天边的人心情怎样。“天末”写出相隔的遥远，“君子”是尊称，语气克制却恳切。","颔联“鸿雁几时到，江湖秋水多”：问信什么时候到，又自己答了：江湖秋水太多，路太长。鸿雁是传书的使者，“秋水多”既是实景，又暗示世路艰险。","颈联“文章憎命达，魑魅喜人过”是全诗最重的一联：好文章不喜欢有好运的人，山鬼妖怪则喜欢人经过——前一句是对才命相妨的悲叹，后一句是对险恶世道的讽刺。尾联“应共冤魂语，投诗赠汨罗”设想李白会向屈原投诗，把李白与屈原并在一起，是杜甫对李白最郑重的定位。"],"notes":[["天末","天边"],["君子","指李白，尊称"],["鸿雁","传书的大雁"],["江湖","指李白流放之地一带"],["文章憎命达","好文章不容命运亨通的人"],["魑魅","山林中的妖怪，喻小人或险恶"],["喜人过","喜欢人经过，以便加害"],["冤魂","含冤而死的魂，这里指屈原"],["投诗","把诗投向水中"],["汨罗","汨罗江，屈原投江之处"]],"think":["“文章憎命达”是在说才华与命运必然冲突吗？","杜甫不是在讲规律，而是在对李白的遭遇发出判断。若把它当成普遍真理，就会得出“有才必穷”的荒谬结论。更合理的理解是：他看到了才华、性格与时代之间的错位，用“憎”这样的拟人字眼，给不可解的命运安上一个名字。"],"quiz":[["“鸿雁几时到”表达的是？",["盼望李白的消息","期盼春天来临","描写秋季的景色","说明诗人想去远方"],"鸿雁传书，问它几时到，是在盼李白的音信。"],["尾联把李白与谁并提？",["屈原","陶渊明","贾谊","宋玉"],"“汨罗”是屈原投江的地方，“投诗赠汨罗”把李白放进屈原式的冤屈者行列。"]],"cards":[["“文章憎命达”的下一句？","魑魅喜人过。"],["《天末怀李白》的结句寓意？","把李白比作屈原式的冤屈者，诗投汨罗以相慰。"]],"line":["文章憎命达，魑魅喜人过","看到一位才华横溢的同行被排挤，心里默念：文章憎命达，魑魅喜人过。"],"tags":["五律","怀人","杜甫"]},"tangjin_yueyang":{"intro":"大历三年（768）冬，杜甫出峡后来到岳阳，登楼望洞庭，写下这首诗。前四句写洞庭气象，后四句写身世，是杜甫晚年“大景与个人”并置的典范。五律在他手里，开阔到几乎要撑破格式。","focus":["首联“昔闻洞庭水，今上岳阳楼”平平道来：早听说，现在到。用语朴素，却把几十年的向往与眼前的实景放在一起，是登临诗常见的“起笔缓”。","颔联“吴楚东南坼，乾坤日夜浮”是写洞庭最大气的一联：吴地和楚地在东南被它隔开，天地仿佛日夜浮在水上。“坼”和“浮”都是动词，把静止的湖水写成有力量的存在，五字之内气吞天地。","颈联“亲朋无一字，老病有孤舟”突然收缩：朋友一封信也没有，老病缠身只有一叶孤舟。大与小的反差在这里发生。尾联“戎马关山北，凭轩涕泗流”：北方仍在打仗，凭栏流泪。到此，身世之悲与国家之忧合到一处，诗的格局由湖到天下。"],"notes":[["洞庭水","洞庭湖"],["岳阳楼","在湖南岳阳，临洞庭湖"],["吴楚","吴地和楚地"],["坼","裂开，分开"],["乾坤","天地"],["日夜浮","日夜漂浮在水上"],["亲朋","亲人朋友"],["孤舟","孤零零的一只船"],["戎马","战马，指战争"],["涕泗","眼泪鼻涕"]],"think":["颔联的“浮”到底是谁在浮？","字面是乾坤，但乾坤本来不动，写成“浮”是因为洞庭太大，让人觉得天地都漂在水上。这个“浮”也暗中呼应下文“孤舟”：诗人自己就在“浮”的世界里。读诗时可以注意：杜甫大处写景的字，往往又是后文自况的铺垫。"],"quiz":[["“吴楚东南坼”中“坼”的作用是？",["写出洞庭湖把吴楚分开的巨大气势","说明吴楚发生了地震","描写湖面结冰裂开","表示东南方向的山崩塌"],"“坼”是裂开、分开，写湖水广阔到像把吴楚两地劈开。"],["颈联与颔联的关系是？",["由大景转入个人孤弱，形成反差","继续描写湖景","转为欢乐","议论史事"],"颔联天地浮动，颈联亲朋无字、老病孤舟，大与小形成强烈对照。"]],"cards":[["“吴楚东南坼”的下一句？","乾坤日夜浮。"],["《登岳阳楼》的结构？","前四句写洞庭，后四句写身世与家国，最后合到一处。"]],"line":["亲朋无一字，老病有孤舟","连续加班后回家，群里没人说话，自嘲：亲朋无一字，老病有孤舟。"],"tags":["五律","登临","杜甫"]},"tangjin_zhongnan":{"intro":"王维写终南山，不写某一个景，而写整座山的格局：高、连绵、云遮、分野、阴晴不一。最后忽然转到一个具体的小场景：隔水问樵夫。读它要看大尺度写景怎样用一句话收成人间的一点温度。","focus":["首联“太乙近天都，连山接海隅”是夸张：山高到靠近天都（即京城上空的天），连绵到可以通到海边。这是用想象的尺度写山的雄阔，不求精确。","颔联“白云回望合，青霭入看无”写人在山中移动时的视觉变化：回头看，白云合拢；走进去，青色的雾气反而没有了。这是真实的登山体验，王维把它写成两个对称的动作。","颈联“分野中峰变，阴晴众壑殊”是以少总多：中间的峰顶分开了星宿对应的区域，众多山谷各自阴晴不同。“变”“殊”两个字，写出山体庞大到有自己的气候。尾联“欲投人处宿，隔水问樵夫”突然降落：天晚了，想找户人家借宿，隔着水问砍柴人。前面的宏大，一下被收进一个小小的问话。"],"notes":[["太乙","终南山主峰，也作终南山别称"],["天都","天帝所居之地，此处指高天"],["海隅","海边"],["青霭","青色的云气"],["分野","古代把天上星宿与地上区域对应的划分"],["中峰","山的中央峰顶"],["阴晴","阴天晴天"],["众壑","众多山谷"],["樵夫","砍柴的人"],["投人处宿","到有人家的地方投宿"]],"think":["为什么写完气势宏大的山，要用“问樵夫”收尾？","因为大景需要一个尺度参照。一问樵夫，立即让人感到山大到连找个人家都要隔水去问。同时，这样的结尾也让山水诗里有了人间气息，不会只剩下景物。"],"quiz":[["“白云回望合”写的是？",["回头看时云雾聚合","白云遮住了山","山上有白色的岩石","天空飘着白云"],"人在山中前行，回头看，原来走过的路被云合上，是动态的真实感受。"],["尾联的作用是？",["以具体小事收束宏大的景","总结全诗的主题","表示诗人要隐居","描写夜色"],"最后一问把壮阔的山水落回到人的日常，是大与小的对比。"]],"cards":[["“分野中峰变”的下一句？","阴晴众壑殊。"],["《终南山》的收束方式？","以隔水问樵夫的小场景收住大景。"]],"line":["欲投人处宿，隔水问樵夫","在陌生城市赶上暴雨，下车就问路：欲投人处宿，隔水问樵夫——结果问的是小区门口的保安。"],"tags":["五律","山水","王维"]},"tangjin_xiangji":{"intro":"香积寺在长安南面，具体位置存疑，本诗据说是王维在那一带寻寺所作。全诗没有写寺本身，只写走向它的路和周围的景物，最后用佛家“安禅制毒龙”收住。它是王维“以景写禅”的代表。","focus":["首联“不知香积寺，数里入云峰”是写寻访：不知道寺在哪里，走了几里，已经进入云里的山峰。“不知”是谦词，也是实情；“入云峰”把路越走越高的感觉讲了出来。","颔联“古木无人径，深山何处钟”写得极妙：古树丛中没有路，远处传来钟声，却不知钟在哪里。视觉与听觉交替出现，让整个山林显得幽深、没有边界。","颈联“泉声咽危石，日色冷青松”是公认的炼字佳句：泉水从高石上流下，声音像被石头噎住；日光穿过青松，显得清冷。“咽”“冷”两字，一字管声、一字管光，使本来应是温暖的阳光也带上寒意，山中的静深由此可感。尾联“薄暮空潭曲，安禅制毒龙”才点出禅意：傍晚潭边打坐，把心里的妄念像毒龙一样降伏。"],"notes":[["香积寺","寺名，在长安南郊一带"],["云峰","高入云端的山峰"],["古木","古老的树木"],["无人径","没有人走过的小路"],["咽","呜咽，声音受阻"],["危石","高耸的石头"],["日色","日光"],["薄暮","傍晚"],["空潭","空寂的深潭"],["安禅","安静坐禅"],["毒龙","佛经中比喻妄念烦恼"]],"think":["“日色冷青松”的“冷”是体感还是心感？","是两者叠加：深山树荫下确实凉，诗人心境清静，使阳光也显得清冷。把“冷”用在日色上，是王维的惯技：不写温度计的冷，写心觉得的冷。这与后面“空潭”“安禅”的心境形成呼应。"],"quiz":[["“泉声咽危石”中“咽”字的效果？",["写出泉水被石阻挡的呜咽声","说明泉水很小","说明泉水有毒","表示泉水干涸"],"“咽”把水声拟人化，像被高石卡住的呜咽，增添幽寂之感。"],["“安禅制毒龙”的意思是？",["通过坐禅降伏心中妄念","在潭边捉住一条龙","禅师降服了怪兽","比喻某种祭祀"],"毒龙在佛经里比喻烦恼、妄念，安禅是用修禅把它压住。"]],"cards":[["“泉声咽危石”的下一句？","日色冷青松。"],["《过香积寺》全篇的特点？","不写寺本身，只写寻寺途中的景物，结尾点出禅意。"]],"line":["泉声咽危石，日色冷青松","周末爬山，在半山腰停下来听了一会儿水声，发朋友圈：泉声咽危石，日色冷青松。"],"tags":["五律","山水","禅意"]},"tangjin_hanjiang":{"intro":"这首诗写站在汉江边远眺，视野里是楚地的水、荆门的山，最后以襄阳好风日收结。它的特点是“水墨”：不涂色，只勾轮廓，让江水与山色在远处融成一片。读它要看颔联如何把空间推到极远。","focus":["首联“楚塞三湘接，荆门九派通”先摆地理：楚地的关塞与三湘相连，荆门与长江各支流相通。这是大笔勾勒，不求具体，只求一个辽阔的舞台。","颔联“江流天地外，山色有无中”是全诗眼睛：江水流到天地之外，山色在若有若无之间。“外”和“有无中”把视线推出画面，不写看得到的边界，而写看不到的远处，留白之妙正在这里。","颈联“郡邑浮前浦，波澜动远空”：城邑像漂浮在前面的水边，波浪似乎摇动着远方的天空。“浮”“动”两字让整个画面都有了水的流动感。尾联“襄阳好风日，留醉与山翁”以人收束：襄阳风光好，愿留下来陪山翁一醉。山翁指的是晋代山简（镇守襄阳时常醉），以古人的酒兴收一幅山水。"],"notes":[["楚塞","楚地的关塞"],["三湘","湖南湘江流域一带的合称，具体所指说法不一"],["荆门","荆门山"],["九派","长江流经此段的多条支流"],["天地外","天地之外"],["有无中","若有若无之间"],["郡邑","郡县城邑"],["前浦","前方的水滨"],["波澜","波浪"],["山翁","指晋代山简，在襄阳常醉酒"]],"think":["“山色有无中”在写景上有什么特殊效果？","它写的是视觉的极限：山远到几乎看不见，又隐约还在。这样的描写不是精确，而是氛围。后人把它与水墨画里的“留白”联系起来，是因为它同样依靠不画满、让观者补全。"],"quiz":[["“江流天地外”的修辞效果？",["写出江水悠远，超出视线","说明江水流出国界","描写江水汹涌","说明诗人看不清江水"],"江流延伸到天地之外，是以夸张把视线推向无穷远。"],["尾联中“山翁”指？",["晋代山简","诗人的朋友","隐居的樵夫","襄阳太守"],"山简镇守襄阳，常在习家池饮酒大醉，后世以“山翁”代指襄阳的醉客。"]],"cards":[["“江流天地外”的下一句？","山色有无中。"],["《汉江临眺》的画面特点？","水墨式写意，轮廓大、色彩淡，山水融成一片。"]],"line":["江流天地外，山色有无中","站在海边看远处的船，一点点淡进雾里，轻声说：江流天地外，山色有无中。"],"tags":["五律","山水","王维"]},"tangjin_zhongnanbie":{"intro":"这首诗是王维晚年的心境自述：中年好道，晚年隐居终南山脚下。八句话里没有激烈的情感，只有一个人随兴而行、随遇而安的样子。读它要看“行到水穷处，坐看云起时”如何把哲理变成一个动作。","focus":["首联“中岁颇好道，晚家南山陲”交代人生阶段：中年起偏爱道（佛理），晚年在终南山边安家。语气平淡，像在说别人的事，这种平淡正是诗人想要的状态。","颔联“兴来每独往，胜事空自知”写自己独来独往：兴致来了就自己去，美景只有自己知道。“空自知”三字有一点寂寞，但也有自足：不需要有人分享。","颈联“行到水穷处，坐看云起时”是千古名句：走到水尽头，就坐下来看云升起。路走到尽头不是终点，而是换了一种看法。“行”与“坐”，“水穷”与“云起”，一动一静，一止一生，不说道理而有道理。尾联“偶然值林叟，谈笑无还期”：偶遇一位老人，聊得忘了回家。“偶然”与“无还期”，使整首诗都带着不预设的随性。"],"notes":[["中岁","中年"],["好道","喜好佛道之理"],["南山陲","终南山脚边"],["兴来","兴致来的时候"],["独往","独自前往"],["胜事","美好的事，美景"],["空自知","只有自己知道"],["水穷处","水流尽头"],["林叟","山林中的老人"],["无还期","没有回家的时间"]],"think":["“行到水穷处，坐看云起时”只是写景吗？","不止。表面是山行场景，内里是一种处事态度：路走到尽头，不必焦虑，换个方向就看见新的东西。但要小心不要把它神话成“人生哲理”的万能签文：它是诗里的具体动作，先是行，再是坐，再是看。"],"quiz":[["“行到水穷处，坐看云起时”的含意最接近？",["路尽处不必失望，换种方式仍有景可看","水流到尽头就是终点","云比水更重要","应该继续往前走"],"“水穷”是路的尽头，“云起”是新的景象，说明穷处也有转机，需要的是静下来看。"],["颔联“胜事空自知”透出的心境？",["自得而略带孤独","愤愤不平","夸耀自己的收获","希望他人参与"],"“空自知”既有只有自己知道的孤独，也有不求人知的自足。"]],"cards":[["“行到水穷处”的下一句？","坐看云起时。"],["《终南别业》的心境？","随兴自在，无所预设，偶遇即谈，不问归期。"]],"line":["行到水穷处，坐看云起时","项目走到死胡同，关掉电脑去散步，回来后想到一个新方案：行到水穷处，坐看云起时。"],"tags":["五律","隐居","王维"]},"tangjin_dongting":{"intro":"这是一首干谒诗：孟浩然写给一位“张丞相”，想借诗求引荐。一般认为指张九龄，也有说是张说，存疑。干谒诗最难写：既要表达愿望，又不能低三下四。孟浩然的办法是先写一幅磅礴的洞庭，再用一个“羡鱼”的典故轻轻托出来意。","focus":["首联“八月湖水平，涵虚混太清”：八月秋水涨满，湖面与天相接，水与天混在一起。“涵虚”是包含着空虚的天空，“混太清”是与天色不分。起笔写的是一种没有边界的景象。","颔联“气蒸云梦泽，波撼岳阳城”是全诗最强的一联：水气蒸腾弥漫云梦泽，波涛撼动岳阳城。“蒸”“撼”二字把水写成有力量的东西。这联对仗工整，气势却并不板滞，后世常以它比拟洞庭浩渺。","颈联“欲济无舟楫，端居耻圣明”转入干谒本意：想渡过去却没有船桨，闲居无事，在这样的盛世里觉得惭愧。“舟楫”暗指引荐的人，“圣明”是对当朝的称颂。尾联“坐观垂钓者，空有羡鱼情”：看别人钓鱼，自己只能羡慕。用《淮南子》里“临渊羡鱼，不如退而结网”的意思，婉转表示：我想有所作为，却无门路。"],"notes":[["涵虚","包含着虚空，指水面映天"],["太清","天空"],["云梦泽","古代楚地的大泽"],["撼","摇动"],["岳阳城","洞庭湖边的城"],["欲济","想要渡过"],["舟楫","船和桨，比喻引荐的人"],["端居","闲居，无所事事地居住"],["圣明","对君主或盛世的称颂"],["羡鱼情","临水羡慕别人得鱼的心情"]],"think":["干谒诗怎样做到“求而不卑”？","这首诗的做法是：先写大景，显示自己的眼界；再借“舟楫”“羡鱼”两个比喻，把请求包在典故里，不直说“请提拔我”。读者既能感受到诗人的渴望，又看不到乞求的姿态。这种分寸感就是干谒诗的艺术。"],"quiz":[["“欲济无舟楫”的比喻义是？",["想出仕却没有人引荐","想渡湖却没有船","想隐居却没有地方","想写诗却没有纸笔"],"“济”是渡，“舟楫”是借以渡河的工具，这里比喻仕进需要的引荐。"],["“空有羡鱼情”用的是什么含义？",["只能羡慕别人，自己无门路","打算去钓鱼","对食物的渴望","对朋友的怀念"],"取临渊羡鱼的意思，表示想有作为而无途径。"]],"cards":[["“气蒸云梦泽”的下一句？","波撼岳阳城。"],["《临洞庭上张丞相》的结构？","前四句写洞庭，后四句借典故婉转表达求荐之意。"]],"line":["欲济无舟楫，端居耻圣明","刚入行时一腔热情却没有项目，对自己说：欲济无舟楫，端居耻圣明。"],"tags":["五律","干谒","孟浩然"]},"tangjin_guren":{"intro":"孟浩然被朋友邀到乡下家中做客，写下这首田园小诗。它没有一个生僻词，没有一个典故，像在聊天，却被后人当作田园诗的标本。读它要看日常口吻怎样带出不动声色的情谊，以及最后一句如何把“下次再来”写成约定。","focus":["首联“故人具鸡黍，邀我至田家”开口就是实情：朋友备好鸡肉和黄米饭，请我到农家。鸡黍是家常待客的饭，不是大宴，也不夸张，一个“具”字，是认真准备过。","颔联“绿树村边合，青山郭外斜”写路上与到达所见：村边绿树合拢，城外青山斜斜地铺开。“合”“斜”两字很小，却让景物有了随视线移动的姿态。","颈联“开轩面场圃，把酒话桑麻”是全诗最日常的一句：推开窗，对着打谷场和菜园；端起酒，说的是桑麻庄稼。聊的是农事，没有谈官场，也没有感时伤世，这就是友情的默契。尾联“待到重阳日，还来就菊花”是把下一次相聚提前订好：等到重阳节，我还来赏菊。结尾不说“感谢”，直接说“再来”。"],"notes":[["故人","老朋友"],["具","备办、准备"],["鸡黍","鸡肉和黄米饭，家常待客的饭菜"],["田家","农家"],["郭外","城外"],["开轩","推开窗"],["场圃","打谷场和菜园"],["把酒","端着酒杯"],["桑麻","桑树和麻，泛指农事"],["就菊花","来赏菊花"]],"think":["为什么这首诗不用任何典故，仍被看作名篇？","它的好处在于“省”：每一句只写一件具体的事，并让事与事之间有流动。不用典，不是没有学问，而是学问被藏在选材里：写什么、不写什么，都经过取舍。这种“平”需要比华丽更高的控制力。"],"quiz":[["“把酒话桑麻”所透出的信息是？",["朋友间话题朴素，情谊自然","主人是个农学家","诗人想要购买田地","酒席上谈论朝廷政事"],"桑麻是农事，话桑麻说明谈的是日常生活，是熟人间无需客套的自在。"],["尾联“还来就菊花”的作用是？",["以再次相约收束，含蓄表达满意","说明重阳节要登高","描写满园菊花","暗示主人家贫"],"不说感谢，直接订下下次来访，是最自然的赞美。"]],"cards":[["“开轩面场圃”的下一句？","把酒话桑麻。"],["《过故人庄》的风格？","不用典，不渲染，以日常话语写友情，余味自在。"]],"line":["开轩面场圃，把酒话桑麻","难得的周末，在老朋友家里喝茶聊天，不聊工作：开轩面场圃，把酒话桑麻。"],"tags":["五律","田园","孟浩然"]},"tangjin_xinnian":{"intro":"刘长卿一生两次遭贬，这首写的是贬谪途中遇到新年的心境。一般认为作于被贬南巴一带，具体年份存疑。全诗围绕“老”与“客”：新岁带来的不是新气象，而是一年又一年的漂泊，结尾以贾谊自比，把个人命运放进历史的回声里。","focus":["首联“乡心新岁切，天畔独潸然”：新年到来，思乡之情更切；人在天边，独自落泪。“切”字用得准，节日越热闹，漂泊的人越想家。","颔联“老至居人下，春归在客先”是两个反着写的句子：人老了，位置还在别人之下；春天回来了，却比我这个远行客还早。后一句的“春”比人先到，是一种委屈：连季节都比人幸运。","颈联“岭猿同旦暮，江柳共风烟”写的是处境：早晚与岭上的猿啼同在，与江边的柳树共对风烟。诗人把自己放进了荒远的风景里，成了其中的一个。尾联“已似长沙傅，从今又几年”点明：我已经像贾谊（曾任长沙王太傅）一样被贬，从此又要多少年？没有答案，疑问本身就是答案。"],"notes":[["乡心","思乡之心"],["新岁","新年"],["天畔","天边"],["潸然","流泪的样子"],["老至","衰老到来"],["居人下","处于别人之下，地位低"],["春归","春天回来"],["岭猿","山岭上的猿声"],["旦暮","早晚"],["长沙傅","指贾谊，曾任长沙王太傅"]],"think":["“春归在客先”为什么让人心酸？","按常理，客人远行，春天后来才到；诗人说春天比自己更早回到故乡，这是羡慕，也是自怜。它不是描写节气，而是在说：连季节都比人自由。读到这里，要想到他的被贬处境，才能明白“先”字的重量。"],"quiz":[["“春归在客先”表达的是？",["春天比自己更早回到故乡，含羡慕与自怜","春天来得很早","客人先于春天离开","春天与客人同时到"],"“先”字把春的自由与客的不自由对照，是反衬的写法。"],["尾联用“长沙傅”的目的？",["以贾谊遭贬自比","说明诗人去过长沙","称赞贾谊的文才","介绍当地官职"],"贾谊曾被贬为长沙王太傅，诗人借他写自己的遭遇与前路未卜。"]],"cards":[["“乡心新岁切”的下一句？","天畔独潸然。"],["《新年作》结尾借谁自比？","贾谊（长沙傅）。"]],"line":["乡心新岁切，天畔独潸然","春节值班的那个晚上，给家里打完电话：乡心新岁切，天畔独潸然。"],"tags":["五律","贬谪","刘长卿"]},"tangjin_huaishang":{"intro":"韦应物在淮水边遇到一位旧友（梁川人），写下这首久别重逢的诗。梁川、淮上的具体地点存疑，但诗里的情绪是清楚的：十年一别，笑还是旧时的笑，鬓已不是旧时的鬓。结尾一问，把重逢后的惆怅留给了秋山。","focus":["首联“江汉曾为客，相逢每醉还”回忆过去：当年在江汉一带做客，每次相逢都喝醉了才归。两句把一段友情压成一个动作：醉。","颔联“浮云一别后，流水十年间”：一别如浮云聚散，十年如流水逝去。两个比喻并排放在一起，没有说“多么久”，但“十年”二字已让人觉出沉重。","颈联“欢笑情如旧，萧疏鬓已斑”是全诗最真的一联：笑起来仍然像从前，但头发已经斑白。“情如旧”与“鬓已斑”是不变与变的对撞，一句暖，一句凉。尾联“何因不归去，淮上对秋山”以问收尾：为什么不回去，还对着秋山？问的既是朋友，也是自己，答案留空。"],"notes":[["江汉","长江汉水一带"],["为客","做客，漂泊"],["每醉还","每次都醉后才回"],["浮云","比聚散不定"],["流水","比时光流逝"],["十年间","十年之间"],["情如旧","情谊像过去一样"],["萧疏","稀疏，这里指头发稀少"],["鬓已斑","鬓发已斑白"],["秋山","秋天的山"]],"think":["“何因不归去”到底是问谁？","字面上是问朋友，也可以是问自己，甚至是问没有说出口的处境。诗人没有给答案，是因为答案在前几句里：人到中年，路已经走了很远，没有一个简单的“因为”。这种问而不答的结尾，在韦应物手里常见。"],"quiz":[["“欢笑情如旧，萧疏鬓已斑”的关键是？",["不变的情谊与变老的容颜相对照","描写饮酒的快乐","形容朋友的相貌","说明诗人刚刚生病"],"“情如旧”是不变，“鬓已斑”是变，两者的反差突出了岁月。"],["结尾“淮上对秋山”给人的感觉是？",["淡淡的惆怅与孤独","对山水的赞美","豪迈","愤怒"],"诗以疑问收尾，景物是秋山，有一点寂寥，而不是激烈。"]],"cards":[["“浮云一别后”的下一句？","流水十年间。"],["《淮上喜会梁川故人》的情绪主线？","重逢之喜里夹着岁月之叹。"]],"line":["欢笑情如旧，萧疏鬓已斑","十年同学会，见面还是那些玩笑，头发却都稀了：欢笑情如旧，萧疏鬓已斑。"],"tags":["五律","重逢","韦应物"]},"tangjin_waidi":{"intro":"李益写表弟：十年战乱后，在异乡突然重逢，认不出对方，一说名字才想起旧日的模样，说完话又要分别。诗里几乎全是对话与动作，像一出微型戏剧。读它要看“问姓—称名—别来—明日”这几步的紧凑安排。","focus":["首联“十年离乱后，长大一相逢”：十年战乱，当年的孩子已经长大了。“长大”二字是惊喜，也是岁月的刻度，说明分别时对方还小。","颔联“问姓惊初见，称名忆旧容”是全诗最生动的一联：先是问姓氏，吃惊于是第一次见的样子；等他报了名字，才想起旧日容貌。一问一答，两个动作写出了十年的隔膜与忽然的接上。","颈联“别来沧海事，语罢暮天钟”：别后十年的“沧海桑田”之事，说完时已是傍晚钟声。“沧海事”概括了十年的变故，“暮天钟”是时间的流逝。尾联“明日巴陵道，秋山又几重”：明天又要走上巴陵的路，秋山重重。重逢刚刚发生，分别已在眼前，诗的结尾是一片山。"],"notes":[["离乱","战乱离散"],["长大","指表弟已长大成人"],["问姓","询问姓氏"],["惊初见","惊讶像是初次相见"],["称名","说出名字"],["旧容","往日的相貌"],["沧海事","沧海桑田般的变故"],["暮天钟","傍晚的钟声"],["巴陵","今湖南岳阳一带"],["秋山","秋天的山"]],"think":["“问姓惊初见”为什么写得真实？","因为久别后的人确实会认不出，要借助名字重新建立联系。诗里的“惊”是真实的心理反应，没有刻意煽情。很多重逢诗喜欢写泪流满面，这首却写了认不出，反而更动人。"],"quiz":[["“问姓惊初见，称名忆旧容”写出了？",["久别之后几乎认不出对方","双方是陌生人","诗人记忆力很差","对方改了名字"],"十年间对方已长大成人，面貌大变，必须问姓名才想起旧日模样。"],["结尾“秋山又几重”的情感？",["别后路远的怅然","对山景的欣赏","对战乱的愤恨","对重逢的庆幸"],"诗以景作结，重逢刚发生又要分别，路途的山重叠，是怅然。"]],"cards":[["“问姓惊初见”的下一句？","称名忆旧容。"],["《喜见外弟又言别》的写法特点？","以对话和动作为主，重逢与别离在一首诗里完成。"]],"line":["问姓惊初见，称名忆旧容","同学会上遇到一位当年的班长，认了半天：问姓惊初见，称名忆旧容。"],"tags":["五律","重逢","中唐"]},"tangjin_shuxian":{"intro":"刘禹锡咏蜀先主刘备，据说是在夔州（今重庆奉节一带）的先主庙作，具体年份存疑。咏史诗不是复述史实，而是做评价：这首诗开头赞英雄，中间叙功业，最后以刘禅降魏的一幕作冷笔，一褒一贬，显出史家的眼光。","focus":["首联“天地英雄气，千秋尚凛然”是先主庙的总体印象：天地间的英雄之气，千年之后仍然让人敬畏。“凛然”是一种令人肃然的感觉，不是描写庙宇的景物。","颔联“势分三足鼎，业复五铢钱”概括刘备的功业：使天下分成三足而立，又恢复了汉朝的五铢钱。两件事一大一小，一个是政治格局，一个是币制，用具体的“五铢钱”象征汉统的延续。","颈联“得相能开国，生儿不象贤”是评论：有了诸葛亮这样的宰相，才能开创蜀汉；生了儿子刘禅，却不像贤人。前句夸，后句讽，一联完成对蜀汉兴亡的因果分析。尾联“凄凉蜀故妓，来舞魏宫前”落到刘禅降魏之后，蜀地的旧日歌伎在魏的宫殿前舞蹈，场面凄凉。结尾不再评论，让场景自己说话。"],"notes":[["千秋","千年"],["英雄气","英雄的气概"],["凛然","令人敬畏的样子"],["三足鼎","三足而立，指三国鼎立"],["五铢钱","汉代通行的钱币，此处象征汉统"],["得相","得到宰相，指诸葛亮"],["开国","开创国家"],["不象贤","不像贤明的父辈"],["蜀故妓","蜀国旧日的歌伎"],["魏宫","曹魏的宫殿"]],"think":["咏史诗为什么常以“一幕场景”收尾？","因为评论说多了容易成了史论，而场景是诗的长处。刘禹锡前面完成了褒贬，最后用降魏之后歌伎起舞的画面，把兴亡之悲交给读者感受。这样既不失史家立场，又保留了诗味。"],"quiz":[["“业复五铢钱”的含义是？",["恢复汉朝统治与制度的象征","刘备铸造了新钱","蜀汉经济富裕","诗人收藏古钱"],"五铢钱是汉代货币，刘备以兴复汉室为号召，这里借钱币表示汉统的延续。"],["“生儿不象贤”所指？",["刘禅不如父亲","刘备没有儿子","诸葛亮的儿子","刘备家教不严"],"“儿”指刘备之子刘禅，批评他没能继承父辈的贤能。"]],"cards":[["“得相能开国”的下一句？","生儿不象贤。"],["《蜀先主庙》为什么以歌伎收尾？","借刘禅降魏的一幕场景收束兴亡，不再议论。"]],"line":["得相能开国，生儿不象贤","谈到家族企业的传承，同行摇头：得相能开国，生儿不象贤，这是常态。"],"tags":["五律","咏史","刘禹锡"]},"tangjin_cao":{"intro":"白居易这首是应试之作，全题为《赋得古原草送别》，这里的“送别”是命题要求。它的亮点是借草写生命，前四句最有名，后四句把草与送别接起来，使一首命题诗成为一个完整的作品。","focus":["首联“离离原上草，一岁一枯荣”是冷静的陈述：原野上的草茂盛，每年一次枯，一次荣。“离离”是繁盛，“枯荣”是循环，开头就带有一点历史感。","颔联“野火烧不尽，春风吹又生”是全诗最亮的句子。野火是毁灭，春风是复生，两件事对比，说明草的生命力不靠“不被烧”，而靠“烧不尽”。这句话在今天仍被当作韧性的象征，来源就在这里。","颈联“远芳侵古道，晴翠接荒城”转向送别题：远处草香蔓延到古道，阳光下绿色连着荒城。“侵”“接”两个动词，写草的势头。尾联“又送王孙去，萋萋满别情”扣题：又送一位王孙远行，萋萋芳草里都是别情。王孙句化用《楚辞》“王孙游兮不归，春草生兮萋萋”的意象。"],"notes":[["离离","草茂盛的样子"],["枯荣","枯萎与繁盛"],["野火","野外的火"],["烧不尽","烧不完"],["远芳","远处的芳草"],["侵","蔓延进入"],["古道","古老的道路"],["晴翠","晴日里的青翠"],["王孙","贵族子弟，这里指远行的人"],["萋萋","草茂盛的样子"]],"think":["“野火烧不尽，春风吹又生”是在赞美坚韧吗？","字面是。但要补一句：它写的是草的“自然属性”，不是人的“意志”。诗的力量恰恰在于：生命的恢复不需要意志，只需要春风。把这句拿来鼓励人时，可以说“要有韧性”，但也要承认：诗里没有说草在努力，它只是被春风唤醒。"],"quiz":[["“一岁一枯荣”的含义是？",["草每年枯萎又繁盛，循环往复","草只长一年","草在一年内枯死","草每年都变颜色"],"“枯荣”指枯萎与繁盛，“一岁一”说明每年一轮。"],["尾联“又送王孙去”与题目的关系是？",["由咏草转入送别，扣住题目","说明诗人要去远方","说明王孙是草的名字","与题目无关"],"原题为《赋得古原草送别》，这一联让草与别情相连，完成命题。"]],"cards":[["“野火烧不尽”的下一句？","春风吹又生。"],["《草》为什么是应试诗中的佳作？","前四句独立成篇，后四句扣题送别，既有气象又合要求。"]],"line":["野火烧不尽，春风吹又生","被行业寒冬裁员之后，给自己打气：野火烧不尽，春风吹又生。"],"tags":["五律","咏物","白居易"]},"tangjin_chan":{"intro":"李商隐的《蝉》与骆宾王《在狱咏蝉》可以并读。骆宾王写的是蝉的冤屈，李商隐写的是蝉的清贫与孤高：高处栖，吃得少，鸣得苦，却没人理。写蝉即写自己：官职微薄，故园荒芜，唯有“清”字守着。","focus":["首联“本以高难饱，徒劳恨费声”：蝉栖在高处，露水为食，难以吃饱；它不停地鸣叫，是徒劳地怨恨。“恨费声”的说法有意思：不是怨自己饿，而是怨叫了也没人理。","颔联“五更疏欲断，一树碧无情”：到了五更，蝉声稀疏，快要断了；满树的碧绿却丝毫不为所动。前一句写蝉的力竭，后一句写环境的冷漠，两句之间是同情与无情的对比。","颈联“薄宦梗犹泛，故园芜已平”转写人：官职卑微，像水里随流漂泊的断梗；故乡的园子，杂草已经长平。“梗犹泛”用桃梗的典故，说无根漂泊。尾联“烦君最相警，我亦举家清”以蝉作结：劳你最能警醒我，我也是全家清贫。蝉的高洁与自己的清贫相印，咏物归于自况。"],"notes":[["高难饱","栖在高处，难以吃饱"],["费声","白费声音"],["五更","天将亮的时候"],["疏欲断","稀疏到几乎断了"],["一树碧","满树的绿叶"],["薄宦","官职卑微"],["梗犹泛","像断了根的木偶漂浮不定"],["故园","故乡的园子"],["芜已平","杂草已长平"],["举家清","全家清贫"]],"think":["李商隐《蝉》与骆宾王《在狱咏蝉》的区别在哪？","骆宾王的主题是“冤”：露重、风多是外力压迫；李商隐的主题是“清”：高难饱、举家清是自守的选择与处境。前者重在不平，后者重在无奈。两首并读，能看到咏物诗怎样根据诗人的境遇而改变。"],"quiz":[["“一树碧无情”的作用是？",["以无情的碧树反衬蝉的哀鸣","形容树木很美","说明蝉的数量很多","表示春天来了"],"满树碧绿不为蝉声所动，是冷漠环境的象征。"],["尾联“我亦举家清”的含义？",["以全家清贫与蝉相呼应","全家都很有钱","全家都在隐居","全家都很安静"],"“清”既指清贫，也含清高，诗人把自己与蝉并在一起。"]],"cards":[["“本以高难饱”的下一句？","徒劳恨费声。"],["《蝉》的收束方式？","以“我亦举家清”把咏物落到自况。"]],"line":["烦君最相警，我亦举家清","读到一位清廉的老干部的故事，默默写下：烦君最相警，我亦举家清。"],"tags":["五律","咏物","李商隐"]},"tangjin_songren":{"intro":"温庭筠以词闻名，诗也有苍劲的一面。这首送人东游，场景在荒戍、汉阳渡、郢门山一带，起笔雄浑，结尾落到约再会的酒。读它要注意：温庭筠的“华丽”不在这里，这里是少见的疏朗。","focus":["首联“荒戍落黄叶，浩然离故关”：荒凉的戍楼，飘落的黄叶；一个“浩然”，写出离别的决然。这里没有儿女情态，是一种阔步的告别。","颔联“高风汉阳渡，初日郢门山”对仗工整：高风对初日，汉阳渡对郢门山。两句都是景，却有一个方向：风是向东的，日是新升的，使离别带上了前进的势头。","颈联“江上几人在，天涯孤棹还”：江上还有几个人（旧友）在？天涯孤舟何时回？这里的口气转为叹息。尾联“何当重相见，樽酒慰离颜”：何时能再相见，用一杯酒安慰别后的容颜。结尾朴素，收得很稳。"],"notes":[["荒戍","荒凉的戍楼"],["黄叶","落叶"],["浩然","豪放决然的样子"],["故关","旧时的关隘"],["高风","高处的风"],["汉阳渡","汉阳的渡口"],["初日","初升的太阳"],["郢门山","郢门，古楚都附近的山"],["孤棹","孤舟"],["离颜","离别时的面容"]],"think":["为什么说这首诗“不像”温庭筠？","通常人们对温庭筠的印象来自《花间集》的绮丽。这首诗没有脂粉气，用景物写别，用酒作结，风格偏刚健。这提醒我们：诗人的风格不是单一的，读一个人要多读体裁，别被标签代替判断。"],"quiz":[["“浩然离故关”的“浩然”是？",["离别时豪放决然的气概","浩浩荡荡的江水","指一个叫浩然的人","形容关隘的广大"],"“浩然”形容气势盛大，这里指行者离开故关时的豪放决然。"],["尾联“樽酒慰离颜”表达的是？",["期待重聚，以酒相慰","要喝醉","埋怨朋友","打算隐居"],"诗人希望将来再见，用一杯酒安慰别后的面容。"]],"cards":[["“荒戍落黄叶”的下一句？","浩然离故关。"],["《送人东游》的风格？","刚健疏朗，写景为主，不是温庭筠常见的绮丽。"]],"line":["何当重相见，樽酒慰离颜","给要出国的同事送行：何当重相见，樽酒慰离颜。"],"tags":["五律","送别","晚唐"]},"tangjin_huanglou":{"intro":"《黄鹤楼》是七律的名作，崔颢作。相传李白登楼见此诗而搁笔，说“眼前有景道不得，崔颢题诗在上头”，这类记载见于后人笔记，是否真有其事存疑。它的特别在于：前四句几乎不讲格律，却一气贯通；后四句才回到规矩，把怀乡落在烟波上。","focus":["首联与颔联“昔人已乘黄鹤去，此地空余黄鹤楼。黄鹤一去不复返，白云千载空悠悠”：同一个“黄鹤”反复出现，三次；“空”字也出现两次。这种重复在律诗里是犯忌的，但它形成了回环之感，把时间的流逝和人事的消失一下子推到极致。","颈联“晴川历历汉阳树，芳草萋萋鹦鹉洲”是回到眼前：晴天里江对岸汉阳的树历历可数，鹦鹉洲上芳草茂盛。这是严整的对仗，诗在这里由虚（传说）转实（风景）。","尾联“日暮乡关何处是，烟波江上使人愁”收于愁：天晚了，故乡在哪里？江上烟波让人发愁。前面的传说与风景，都为这一问铺垫。诗的最后一个字是“愁”，但这愁并不尖锐，而是笼在烟波里。"],"notes":[["昔人","古代的人，指传说中乘鹤的仙人"],["黄鹤","传说中仙人所乘的鹤"],["空余","只剩下"],["悠悠","遥远、飘荡的样子"],["晴川","晴日下的江水"],["历历","清晰可数"],["汉阳","武昌对岸的汉阳"],["萋萋","草茂盛的样子"],["鹦鹉洲","长江中的沙洲，在黄鹤楼附近"],["乡关","故乡"]],"think":["为什么前四句违反了律诗的惯例却被奉为名作？","因为它的节奏与内容一致：时间的流逝本来就不该被格律切碎。重复“黄鹤”“空”形成的回环，使读者陷入一种茫然的怅惘，这种效果是严格遵守格律的诗难以做到的。当然，它也只能是天才之作，不是模仿的模板。"],"quiz":[["首联与颔联的特点？",["重复“黄鹤”“空”等字，一气呵成","严格对仗","描写具体景物","叙述自己的经历"],"这几句重复字多，不讲对仗，却节奏连贯，营造出超然的怅惘。"],["尾联“烟波江上使人愁”的功能？",["把传说和风景收束为乡愁","说明江上有雾","转到议论","表达喜悦"],"前面写传说与景物，最后落在乡关何处，是全诗情感落点。"]],"cards":[["“昔人已乘黄鹤去”的下一句？","此地空余黄鹤楼。"],["《黄鹤楼》结句的情感？","日暮乡关何处是——烟波中的乡愁。"]],"line":["日暮乡关何处是，烟波江上使人愁","长途出差回不去的春节，在酒店窗前：日暮乡关何处是，烟波江上使人愁。"],"tags":["七律","登临","崔颢"]},"tangjin_jimen":{"intro":"祖咏这首写他到了边地蓟门（今北京一带的北方边关）所见所感。前六句写军营和边景，后两句突然转到个人的志向：我不是投笔从戎的书生，但也想请缨立功。这种“由景入志”的写法是盛唐边塞诗的典型。","focus":["首联“燕台一去客心惊，箫鼓喧喧汉将营”：到了燕台一带，一入军营，听到喧天的箫鼓，心中一惊。“客”字说明自己是外来者，“汉将营”借汉指唐。","颔联“万里寒光生积雪，三边曙色动危旌”：万里积雪反射出寒光，三边的晨曦摇动高高的旌旗。“生”“动”两字让静景有了流动，寒光与旗影一冷一动，气氛肃穆。","颈联“沙场烽火侵胡月，海畔云山拥蓟城”写远景：烽火的光侵入胡地的月色，海边云山环抱着蓟城。尾联“少小虽非投笔吏，论功还欲请长缨”：我年少时虽不是投笔从戎的班超式人物，但论功业我也想请缨杀敌。“请长缨”用终军的典故，表达投身报国的愿望。"],"notes":[["燕台","燕地的高台，指蓟门一带"],["客心惊","旅人心里一惊"],["喧喧","喧闹声"],["汉将营","汉代将军的军营，借指唐军营地"],["寒光","寒冷的光"],["三边","指幽、并、凉三州边地，泛指边境"],["曙色","清晨的光色"],["危旌","高高的旌旗"],["投笔吏","投笔从戎的人，指班超"],["请长缨","请求领命杀敌，典出终军"]],"think":["尾联的“虽非”是不是自谦？","是自谦也是自励。“虽非投笔吏”是承认自己是书生，不是投笔从戎的典型；“还欲请长缨”是说虽然如此，仍想建功。一退一进，既不夸大自己，又展现决心。这种谦与豪并存的口吻，是盛唐文人自我定位的常见方式。"],"quiz":[["“万里寒光生积雪”的写法特点？",["以冷色和光的运动写出军威与肃杀","写雪后宁静","描写农耕","表现节日热闹"],"积雪反光、晨光动旌旗，是冷与动的对照，渲染边塞气氛。"],["尾联“请长缨”的典故意思？",["请求领兵杀敌，报效国家","请求回家","请求辞官","请求退休"],"出自终军请缨缚南越王，表示愿为国立功。"]],"cards":[["“万里寒光生积雪”的下一句？","三边曙色动危旌。"],["《望蓟门》尾联表达了什么？","虽是书生，仍愿投身边事、建功立业。"]],"line":["少小虽非投笔吏，论功还欲请长缨","作为一直做研究的人，被临时抽调到前线项目组，说：少小虽非投笔吏，论功还欲请长缨。"],"tags":["七律","边塞","盛唐"]},"tangjin_fenghuang":{"intro":"李白登金陵凤凰台之作。凤凰台因传说有凤凰栖集而得名。这首诗向来被拿来与崔颢《黄鹤楼》比较，是不是有意较量，说法不一，无定论。它的看点是：同样以传说起，却把结尾由乡愁推到了对朝廷、对长安的忧思，格局更大。","focus":["首联“凤凰台上凤凰游，凤去台空江自流”：前一句凤凰游，后一句凤凰去，台空了，江水依旧。“空”与“自”把繁华的消逝与自然的不变写在一起。","颔联“吴宫花草埋幽径，晋代衣冠成古丘”是怀古：三国吴的宫殿如今只剩花草掩埋小径，晋朝的显贵已成荒冢。“埋”“成”两个字都有力：时间像一把土。","颈联“三山半落青山外，二水中分白鹭洲”写景：三山一半隐在青山之外，二水被白鹭洲分成两流。景色阔大。尾联“总为浮云能蔽日，长安不见使人愁”是转折：浮云遮住太阳，在长安看不见太阳（皇帝），所以愁。这里的“浮云蔽日”是比喻奸佞蒙蔽君主，诗人借怀古写政治的忧思。"],"notes":[["凤凰台","在金陵（今南京）的台，传说有凤凰来集"],["自流","自己流动，不因人事而变"],["吴宫","三国时吴国的宫殿"],["幽径","幽僻的小路"],["晋代衣冠","晋朝的士大夫贵族"],["古丘","古老的坟墓"],["三山","金陵西南江边的三座山"],["二水","指秦淮河分成两支"],["白鹭洲","江中的沙洲"],["浮云能蔽日","浮云遮住太阳，比喻奸臣蒙蔽君主"]],"think":["“长安不见使人愁”与《黄鹤楼》的“烟波江上使人愁”有什么不同？","崔颢的愁是个人的乡愁，落在烟波；李白的愁是政治的忧虑，落在长安。两首诗的结构相似，但落点不同：前者向内，后者向外。这也是李白想出新意的地方，是否是有意回应，不必定论。"],"quiz":[["“总为浮云能蔽日”的比喻义是？",["奸臣蒙蔽君主","天气不好","诗人视力差","比喻时间飞快"],"古诗中常以浮云蔽日喻奸佞遮蔽君主，李白借此表达对朝政的忧虑。"],["颔联“吴宫花草埋幽径”的写法？",["以今日之荒凉写昔日繁华的消逝","夸耀吴宫的美丽","描写春景","描写游人"],"宫殿已成幽径，花草埋没，是怀古诗惯用的今昔对比。"]],"cards":[["“凤去台空江自流”的上一句？","凤凰台上凤凰游。"],["《登金陵凤凰台》结尾的含意？","借“浮云蔽日”表达对朝政与长安的忧虑。"]],"line":["总为浮云能蔽日，长安不见使人愁","看到数据被层层美化之后，一线的真相上不来：总为浮云能蔽日，长安不见使人愁。"],"tags":["七律","怀古","李白"]},"tangjin_jiyu":{"intro":"王维晚年隐居辋川别墅，这首写连日雨后的夏日山居。它是七律里少见的田园诗：前四句写景，后四句写心境。读它要抓住那一联写白鹭、黄鹂的名对，以及结尾用两个典故说“我已不争”的意思。","focus":["首联“积雨空林烟火迟，蒸藜炊黍饷东菑”：连日的雨后，空旷的林间炊烟升得迟缓；人在烧藜菜、煮黄米，送饭到东边的田里。“迟”字是写炊烟，也是写雨后潮湿缓慢的节奏。","颔联“漠漠水田飞白鹭，阴阴夏木啭黄鹂”是名联：广阔的水田上白鹭飞，浓荫的夏树间黄鹂啼。一白一黄，一飞一啭，一视觉一听觉，对仗极精。“漠漠”“阴阴”两个叠词，把空间的阔与树的浓都写出来了。","颈联“山中习静观朝槿，松下清斋折露葵”写自己的日子：在山中静静观看朝开暮落的木槿花，在松下吃素，摘带露的葵菜。尾联“野老与人争席罢，海鸥何事更相疑”用两个典故：《庄子》写杨朱学道后与人同席不争，《列子》里的海鸥不再怀疑真心的人。意思是：我已经不与人争了，别再对我怀疑。"],"notes":[["积雨","连日的雨"],["空林","空旷的树林"],["烟火迟","炊烟升起缓慢"],["蒸藜炊黍","煮藜菜、蒸黄米"],["饷","送饭"],["东菑","东边的田地"],["漠漠","广阔而迷蒙"],["阴阴","树荫浓密的样子"],["啭","鸟婉转地鸣叫"],["习静","修习静心"],["朝槿","早晨开放的木槿花"],["野老","乡野老人，诗人自称"]],"think":["尾联两个典故究竟在说什么？","一是“与人争席罢”：我与人交往已经不争座位，意思是放下了名位；二是“海鸥何事更相疑”：既然我已无机心，海鸥也不必猜忌。合起来是对朝中或世人的一句话：我已远离是非，请别再疑我。这是王维表达自己心境的方式。"],"quiz":[["“漠漠水田飞白鹭”的特点？",["以叠词与色彩写出广阔与灵动","写夜晚的景色","写动物的习性","写农夫劳作"],"“漠漠”写田阔，“白鹭”写色，一飞一动，画面感强。"],["尾联“海鸥何事更相疑”表达？",["自己已无机心，不必被怀疑","要与海鸥做朋友","想去海边","对鸟类的研究"],"用《列子》海鸥典故，说明人无机心，鸥不疑，借此说自己已淡出世争。"]],"cards":[["“漠漠水田飞白鹭”的下一句？","阴阴夏木啭黄鹂。"],["《积雨辋川庄作》后四句主旨？","写隐居的清静，并表示不再与人争，求无猜忌。"]],"line":["山中习静观朝槿，松下清斋折露葵","休假关掉所有软件，在阳台坐了一个下午：山中习静观朝槿。"],"tags":["七律","田园","王维"]},"tangjin_kezhi":{"intro":"杜甫在成都草堂迎客，作此诗（原有题注说明是喜崔明府来访）。杜诗里少有的轻松之作：不忧国，不叹老，只写春水、鸥鸟、一壶旧酒，还有隔着篱笆喊邻居来同饮。读它要看贫寒怎样被写得有温度。","focus":["首联“舍南舍北皆春水，但见群鸥日日来”写环境：房前房后都是春水，天天只见鸥鸟飞来。“但见”二字透出平日的冷清，也暗示难得有人来访。","颔联“花径不曾缘客扫，蓬门今始为君开”是全诗核心：花径从来没有为客人打扫过，蓬门今天才为你而开。两句话是在说：你是特别的。不用客套，就把郑重表达了出来。","颈联“盘飧市远无兼味，樽酒家贫只旧醅”是实话实说：离集市远，盘中菜没有两样；家里穷，酒也只有陈酿。对客人说这些，不是诉苦，而是诚恳。尾联“肯与邻翁相对饮，隔篱呼取尽余杯”最有生活气：你若愿意，我隔着篱笆叫邻居过来，大家把余下的酒喝完。热闹一下子就来了。"],"notes":[["舍南舍北","房子南面北面"],["春水","春天涨起的水"],["群鸥","成群的鸥鸟"],["花径","长满花的小路"],["缘客扫","为客人而打扫"],["蓬门","用蓬草编的门，指贫寒之家"],["盘飧","盘中的饭菜"],["兼味","两样以上的菜肴"],["旧醅","陈年没过滤的酒"],["隔篱","隔着篱笆"]],"think":["“蓬门今始为君开”是客套吗？","若是客套，便不会先写“群鸥日日来”：平日只见鸥鸟，没有人来。这句话的重点是对比：平日不开，今天为你开，说明来客不寻常。这是以事实表达欢迎，比“欢迎光临”更重。"],"quiz":[["“花径不曾缘客扫”的作用？",["以平日不扫衬出今日待客的郑重","说明诗人不爱干净","说明路上没有花","描写春天景色"],"花径平日不为客人扫，今日为你而开，是对来客的特别礼敬。"],["尾联“隔篱呼取”体现了？",["邻里亲切与待客的热情","诗人性情急躁","邻居不请自来","酒不够喝"],"隔着篱笆叫邻居来同饮，是乡里的亲切热闹。"]],"cards":[["“花径不曾缘客扫”的下一句？","蓬门今始为君开。"],["《客至》的风格？","口语化、生活化，贫寒中见真诚与热情。"]],"line":["花径不曾缘客扫，蓬门今始为君开","邀请一位久仰的前辈来办公室参观，在邮件里写：花径不曾缘客扫，蓬门今始为君开。"],"tags":["七律","待客","杜甫"]},"tangjin_guanjun":{"intro":"广德元年（763）春，叛军将领史朝义败亡，官军收复河南河北，杜甫身在剑外（蜀地），听到消息，写下这首诗。后人称它是杜甫诗中最快乐的一首。读它要看节奏：全诗像一口气喘出来的，最后两句连用四个地名，从蜀地一路回到洛阳。","focus":["首联“剑外忽传收蓟北，初闻涕泪满衣裳”：“忽传”是突然听说，“初闻”是第一反应：不是笑，是满衣泪。喜到极点，先是泪，这种真实的反应使诗一开篇就有力量。","颔联“却看妻子愁何在，漫卷诗书喜欲狂”转到家人：回头看妻子，愁容已不见；随手卷起诗书，高兴得要发狂。“漫卷”“欲狂”是动作与情绪的直接呈现，没有任何修辞。","颈联“白日放歌须纵酒，青春作伴好还乡”：白天放声歌唱，一定要痛饮；青春般的春景作伴，正好回乡。这里的“青春”指春天，两句对仗，节奏轻快。尾联“即从巴峡穿巫峡，便下襄阳向洛阳”用“即”“便”两个字，把想象中的行程连成一气，一口气跑到洛阳。"],"notes":[["剑外","剑门关以南的蜀地"],["收蓟北","收复蓟北，指河北一带"],["涕泪","眼泪"],["却看","回头看"],["妻子","妻子和孩子"],["漫卷","随意卷起"],["放歌","放声歌唱"],["纵酒","尽情饮酒"],["青春","春天"],["巴峡","长江三峡之一，在今重庆一带"],["巫峡","三峡之一"],["襄阳","今湖北襄阳"]],"think":["为什么说最后两句有“速度感”？","一是句式：“即从……穿……，便下……向……”是两个动词连发，中间没有停顿；二是地名：巴峡、巫峡、襄阳、洛阳，四个地名跨越千里，连成一条线。声音与地理同时加速，使人读时有“顺流而下”的快感，而这是诗人想象中的归程，不是现实。"],"quiz":[["“初闻涕泪满衣裳”表现了？",["喜极而泣","悲伤","愤怒","疲惫"],"听到胜利消息，第一反应是涕泪满衣裳，喜到极处的泪。"],["尾联的特点？",["连用地名，节奏飞快，想象归程","描写旅途艰难","总结全诗","讽刺时事"],"“即”“便”二字使行程连成一气，四个地名从蜀到洛，一口气读完。"]],"cards":[["“漫卷诗书喜欲狂”的上一句？","却看妻子愁何在。"],["《闻官军收河南河北》的情绪？","突闻胜利，喜极而泣，想象中一路回乡。"]],"line":["漫卷诗书喜欲狂","项目终于通过验收的那天，把桌上的资料一收：漫卷诗书喜欲狂。"],"tags":["七律","纪事","杜甫"]},"tangjin_geye":{"intro":"大历元年（766）岁暮，杜甫在夔州的阁中过夜，听鼓角，望星河，念战乱，想古人，写成这首七律。读它要看一种“压”的力量：天地的大，加上世事的乱，最后收在一句“人事音书漫寂寥”的淡淡自宽里。","focus":["首联“岁暮阴阳催短景，天涯霜雪霁寒宵”：年终时日影越来越短，天涯的霜雪初晴，夜里寒气逼人。“催”字是主动的，像是时间在催人。","颔联“五更鼓角声悲壮，三峡星河影动摇”是名联：五更时鼓角声悲壮，三峡上方的星河影子在晃动。一听觉一视觉，一近一远。“动摇”把静止的星空写动了，有一种不安的气息，与战乱的世道暗合。","颈联“野哭几家闻战伐，夷歌数处起渔樵”：野外有几家人在哭，是因战争；夷人的歌声在渔樵间响起，是此地风俗。两句一悲一异，勾勒出夔州的乱世与边地。尾联“卧龙跃马终黄土，人事音书漫寂寥”：诸葛亮（卧龙）与公孙述（跃马）都归黄土，人间的音信是否寂寥，就随它去吧。以古人的归宿宽慰自己。"],"notes":[["阴阳","日月，指时光"],["短景","短短的日影"],["霁","雪或雨停止"],["寒宵","寒冷的夜"],["五更","天将亮的时刻"],["鼓角","军中的鼓和号角"],["三峡","长江三峡"],["星河","银河"],["野哭","旷野里的哭声"],["夷歌","少数民族的歌声"],["卧龙","诸葛亮"],["跃马","指公孙述，曾在蜀称帝"]],"think":["“卧龙跃马终黄土”是想说明什么？","诸葛亮是蜀汉的忠臣，公孙述是割据一方的称帝者，一正一反，结局都是黄土。杜甫借此说：无论功过，终归于尽，那么眼前的“音书寂寥”也不必执着。这是一种在悲凉中的自我宽解，但并非真正的超脱，所以才用“漫”字，是随便、不计较的意思。"],"quiz":[["“三峡星河影动摇”的妙处？",["以星影动写出不安，与战乱呼应","说明天气很冷","描写舟行","表示天快亮了"],"星河本静，写成“动摇”，暗示时局动荡，诗人心神不宁。"],["尾联提及“卧龙跃马”的作用？",["以古人归土自宽","称赞蜀地英雄","说明夔州的历史","表示要去拜谒"],"诸葛亮与公孙述皆归黄土，诗人以此宽慰个人寂寥。"]],"cards":[["“五更鼓角声悲壮”的下一句？","三峡星河影动摇。"],["《阁夜》的情感走向？","由岁暮寒夜、战乱哭声，到以古人归土自宽。"]],"line":["卧龙跃马终黄土，人事音书漫寂寥","凌晨复盘一场失败的谈判，合上电脑：卧龙跃马终黄土，人事音书漫寂寥。"],"tags":["七律","夔州","杜甫"]},"tangjin_huaigu3":{"intro":"《咏怀古迹》五首，第三首咏王昭君。昭君村在荆门一带（今湖北秭归），杜甫身在夔州，借昭君的出塞与魂归，写自己漂泊他乡的情怀。读它要看杜甫怎样同时写昭君与自己，以及最后一联如何用琵琶声把怨恨坐实。","focus":["首联“群山万壑赴荆门，生长明妃尚有村”：群山向荆门奔涌，明妃（昭君）出生的村子还在。起笔写山势，是为了引出故乡，山越壮阔，她的远嫁越显孤单。","颔联“一去紫台连朔漠，独留青冢向黄昏”：一去，是从汉宫紫台直通北方沙漠；留下的只有一座青冢，向着黄昏。“一去”与“独留”对立，生与死、汉与胡、始与终都在这一联里。","颈联“画图省识春风面，环珮空归月夜魂”写原因与结局：汉元帝只凭画像识人，没认出她的美貌；魂魄只能佩着环珮在月夜归来。尾联“千载琵琶作胡语，分明怨恨曲中论”：千年的琵琶曲用胡语弹奏，怨恨清楚地在曲中诉说。把怨恨交给音乐，而不是直接控诉。"],"notes":[["荆门","荆门山，昭君故里在附近"],["明妃","王昭君，避晋文帝司马昭讳称明君，后称明妃"],["紫台","紫宫，指汉宫"],["朔漠","北方沙漠"],["青冢","昭君墓，传说墓上草色常青"],["省识","略识，大致认出"],["春风面","美好的容颜"],["环珮","玉佩"],["空归","徒然归来"],["胡语","胡人的语言"]],"think":["杜甫为什么用“独留”“空归”来写昭君？","两个字都带“落空”的意味：墓独自留在北方，魂空自归来。昭君的结局是孤独，杜甫当时也在流寓，所以两者形成共鸣。但这属于解读，诗中没有直接说“我就是昭君”。"],"quiz":[["“画图省识春风面”指的是？",["皇帝凭画像识人，错过了昭君的美","画家把昭君画得太丑","昭君喜欢画画","诗人在欣赏画图"],"相传汉元帝依画像选人，昭君因不贿赂画工被画丑，因此遗恨。"],["结尾“怨恨曲中论”的含意？",["怨恨通过琵琶曲被千年诉说","琵琶曲很欢快","昭君不再怨恨","琵琶曲只在宫中演奏"],"借琵琶曲将怨恨留于后世，让音乐代言。"]],"cards":[["“一去紫台连朔漠”的下一句？","独留青冢向黄昏。"],["《咏怀古迹·其三》写什么？","借昭君的出塞与魂归，写离乡孤独与千古怨恨。"]],"line":["千载琵琶作胡语，分明怨恨曲中论","看一位歌手在舞台上唱起家乡的老歌，台下的人都红了眼睛：千载琵琶作胡语，分明怨恨曲中论。"],"tags":["七律","咏史","杜甫"]},"tangjin_huaigu5":{"intro":"《咏怀古迹》五首之五，咏诸葛亮。杜甫对诸葛亮有特别的推崇，这首与《蜀相》可以对读：《蜀相》重在“长使英雄泪满襟”的叹息，这首重在对诸葛亮功业的评价。读它要看前三联的评价，和尾联“志决身歼”的收束。","focus":["首联“诸葛大名垂宇宙，宗臣遗像肃清高”：诸葛亮的大名垂于天地，他的遗像（在夔州武侯祠）肃穆清高。“宗臣”是被宗仰的大臣，一开篇就定了调子：这是一个让人尊敬的人。","颔联“三分割据纡筹策，万古云霄一羽毛”：三分天下，他迂回地谋划策略；他像云霄中的一根羽毛，万古高飞。“一羽毛”比喻他的孤高与超越，是杜甫对诸葛亮人格的描绘，说的是气象而不是官职。","颈联“伯仲之间见伊吕，指挥若定失萧曹”：他与伊尹、吕尚不相上下，指挥若定时萧何、曹参都为之失色。这是比较，把诸葛亮放进古代名臣中去量。尾联“运移汉祚终难复，志决身歼军务劳”：时运转移，汉的国运终究难以恢复；他志向坚决，死于军务操劳。这一联是惋惜：不是智谋不够，是时运不济。"],"notes":[["宇宙","天地"],["宗臣","被人宗仰的大臣"],["遗像","留下的塑像或画像"],["肃","肃穆"],["纡筹策","迂回地谋划"],["云霄","高空"],["一羽毛","比喻其高飞孤绝"],["伯仲","不相上下"],["伊吕","伊尹和吕尚"],["萧曹","萧何和曹参"],["汉祚","汉朝的国运"],["身歼","死去"]],"think":["“万古云霄一羽毛”为什么常被说是精绝？","因为它不写官职、不写功绩，只写诸葛亮留给后世的感觉：一根羽毛飘在万古的天空。轻而高，使他的功业悲剧具有一种飘逸。这一句是对一个人最含蓄也最有力的评价。"],"quiz":[["“伯仲之间见伊吕”的意思？",["诸葛亮与伊尹、吕尚相比不相上下","诸葛亮与伊吕是兄弟","诸葛亮比伊吕强","诸葛亮不如伊吕"],"“伯仲”指不分高下，把诸葛亮和古代名臣放在同一档次。"],["尾联的主要情感是？",["对其壮志未酬的惋惜","对其战术的批评","对朝廷的不满","对战争的厌倦"],"“运移”“终难复”写时运不济，“志决身歼”写他鞠躬尽瘁，是惋惜之情。"]],"cards":[["“三分割据纡筹策”的下一句？","万古云霄一羽毛。"],["《咏怀古迹·其五》与《蜀相》的区别？","此首重评价功业与人格，《蜀相》重叹息与泪。"]],"line":["运移汉祚终难复，志决身歼军务劳","看到一位团队负责人积劳成疾，在群里发：运移汉祚终难复，志决身歼军务劳。"],"tags":["七律","咏史","杜甫"]},"tangjin_changsha":{"intro":"刘长卿路过长沙，到了贾谊的旧宅，写下这首怀古诗。贾谊是西汉的才子，被贬长沙三年，曾作赋吊屈原。刘长卿自己也是屡遭贬谪的人，所以这不是单纯的凭吊，而是借古人的遭遇说自己的不平。读它要看哪句写贾谊、哪句已经转到自己身上。","focus":["首联“三年谪宦此栖迟，万古惟留楚客悲”：贾谊在这里被贬三年，千古之下只留下一个楚客的悲。“楚客”既指贾谊，也含屈原，两位都是被放逐的才人。一个“惟”字，把千年岁月压成一个“悲”字。","颔联“秋草独寻人去后，寒林空见日斜时”写凭吊所见：只有秋草是来寻人的，只有寒林空对着夕阳。“独”“空”两字把空寂铺开，旧宅里没有人，只剩景物，诗人是在这一片空里站着。","颈联“汉文有道恩犹薄，湘水无情吊岂知”是全诗的锋芒：汉文帝是有道的明君，对贾谊的恩情尚且薄；贾谊投文吊屈原，湘水无情，哪里知道？前一句含有不平，后一句是自叹。尾联“寂寂江山摇落处，怜君何事到天涯”转向对话：在这寂寂的摇落之地，我怜惜你为什么要到天涯来。其实也是在怜惜自己。"],"notes":[["谪宦","被贬谪的官员"],["栖迟","滞留、停留"],["楚客","楚地的流寓之人，指贾谊"],["秋草","秋天的草"],["寒林","寒冷的树林"],["日斜","太阳西斜"],["汉文","汉文帝"],["有道","有道德，政治清明"],["湘水","湘江"],["摇落","草木凋零"],["怜君","怜惜你"],["天涯","天边，指遥远的贬所"]],"think":["“汉文有道恩犹薄”算不算对皇帝的批评？","表面是承认汉文帝有道，但紧接着说恩情仍薄。这是一种含蓄的写法：先承认，再翻出不满。因为诗人也是被贬之人，不敢明骂当朝，借古代明君说话，既不失体面，又表达了不平。"],"quiz":[["颈联“汉文有道恩犹薄”的语气是？",["先肯定后转折，含不平","纯粹颂扬","嘲讽","漠不关心"],"“有道”是承认，“恩犹薄”是转折，含蓄表达对贾谊遭遇的不平。"],["尾联“怜君何事到天涯”的实质是？",["同情贾谊，也是自怜","责备贾谊","询问路程","表示要去天涯"],"诗人也是被贬之人，怜君即怜己。"]],"cards":[["“三年谪宦此栖迟”的下一句？","万古惟留楚客悲。"],["《长沙过贾谊宅》的主旨？","借吊贾谊抒被贬的不平与自怜。"]],"line":["寂寂江山摇落处，怜君何事到天涯","路过一位被调到边远分公司的老领导的办公室，空了一半：寂寂江山摇落处，怜君何事到天涯。"],"tags":["七律","怀古","贬谪"]},"tangjin_liuzhou":{"intro":"柳宗元被贬柳州刺史后，登上城楼，想起同被贬在漳州、汀州、封州、连州的四位友人（一般认为是韩泰、韩晔、陈谏、刘禹锡），写下这首诗。它的前四句写景，后四句写愁，景与愁相通。读它要看“惊风”“密雨”怎样把一个眼前的天气写成人事的风雨。","focus":["首联“城上高楼接大荒，海天愁思正茫茫”：高楼连着荒远的野外，海天一色，愁思也茫茫。“接”和“茫茫”是同一个方向：空间向外无尽，愁也向外无尽。","颔联“惊风乱飐芙蓉水，密雨斜侵薜荔墙”是景，也是比：狂风乱吹荷花池，密雨斜打薜荔墙。芙蓉与薜荔本是美好、高洁的植物，却受风雨摧折，有人认为暗指诗人与同僚的遭遇，这是一种读法，诗里没有明说。","颈联“岭树重遮千里目，江流曲似九回肠”：岭上的树重重遮住视线，江水曲折像九回的愁肠。前句是不得见友人，后句是以江曲比肠曲，用具体的形状写看不见的愁。尾联“共来百越文身地，犹自音书滞一乡”：我们一同来到百越这个纹身的蛮荒之地，音信却仍被阻在各自的一乡。结语不责怪，只叙事实。"],"notes":[["大荒","旷远的荒野"],["愁思","忧愁的思绪"],["茫茫","广阔迷茫"],["惊风","突然的狂风"],["飐","风吹动"],["芙蓉","荷花"],["薜荔","一种攀缘植物"],["岭树","山岭上的树"],["九回肠","比喻愁绪曲折"],["百越","岭南古代越人地区"],["文身","在身上刺花纹的习俗"],["音书","书信"]],"think":["“芙蓉”“薜荔”被风雨打，是不是写他们自己？","可以这样读，但要小心：诗中没有说“我们就是芙蓉”。较稳妥的读法是：这两句写的是登楼所见，因为选了美好的草木而被风雨摧折，读者容易联想到人的遭遇。景与人之间留有空隙，这是好诗的写法。"],"quiz":[["“江流曲似九回肠”的修辞是？",["以江曲比愁肠","以江比朋友","夸张","对比"],"以江水曲折比喻愁肠九回，用具体的曲折写抽象的愁。"],["尾联“音书滞一乡”写的是？",["同被贬的朋友各在一方，书信不通","诗人故乡很远","书信丢失","邮政制度"],"几位被贬者分散各州，音信难通，说明相隔之远与处境之困。"]],"cards":[["“惊风乱飐芙蓉水”的下一句？","密雨斜侵薜荔墙。"],["《登柳州城楼》为什么是贬谪诗的代表？","以景写愁，景中见人，结尾点出同遭贬谪而音信难通。"]],"line":["岭树重遮千里目，江流曲似九回肠","隔着时差与朋友失联，长时间收不到回复：岭树重遮千里目，江流曲似九回肠。"],"tags":["七律","贬谪","柳宗元"]},"tangjin_xisai":{"intro":"刘禹锡的怀古诗以冷静著称。西塞山在今湖北黄石一带的江边，是三国吴时的军事要地。诗里写的是西晋灭吴：王濬率船队从益州顺流而下，吴人在江中拦铁锁，终究被破。读它要看前四句的史事与后四句的议论：兴亡如何不由人，只由势。","focus":["首联“王濬楼船下益州，金陵王气黯然收”：王濬的楼船从益州出发，金陵的王气黯然收敛。起句用动词“下”，是自上而下的顺流之势；后句“黯然收”是一个朝代的光彩熄灭。","颔联“千寻铁锁沈江底，一片降旛出石头”：千寻长的铁锁沉入江底，一面降旗从石头城里出来。铁锁是吴人的防线，降旛是结局，前一句写防守的徒劳，后一句写结局的轻。一个“沈”和一个“出”，把大事写成两个动作。","颈联“人世几回伤往事，山形依旧枕寒流”是议论：人世间多少次感伤往事，山的形状依然枕着寒流。以山不变对人事变，是怀古的常见笔法。尾联“从今四海为家日，故垒萧萧芦荻秋”：从今天起天下一家，旧日的营垒只剩芦荻在秋风里萧萧。结尾说天下统一，却是以废垒收束，使统一也带上一点苍凉。"],"notes":[["王濬","西晋将领，率水军伐吴"],["楼船","高大的战船"],["益州","今四川一带"],["王气","象征帝王运势的云气"],["黯然","暗淡无光"],["千寻","形容极长"],["铁锁","吴人在江中设置的拦江铁链"],["降旛","投降的旗"],["石头","石头城，吴的都城防地"],["往事","过去的事"],["寒流","寒冷的江水"],["故垒","旧时的营垒"],["芦荻","芦苇一类的水草"]],"think":["尾联“四海为家”是在庆祝统一吗？","字面是，但紧接着“故垒萧萧芦荻秋”把画面压到一个废墟上。这里有一种冷静：统一是事实，旧垒的荒凉也是事实。刘禹锡不站在胜利者或失败者任何一边，只是陈述，这正是这首诗“冷”的地方。"],"quiz":[["“山形依旧枕寒流”的作用是？",["以自然的不变对照人事的更替","描写山势险要","说明山很高","表示山中有寺"],"山形不变，朝代更替，是怀古诗常用的对照。"],["尾联的画面意义是？",["以废垒芦荻收束，使统一带有苍凉","庆祝统一","描写秋收","讽刺晋朝"],"统一之后，旧日营垒荒废，是兴亡的冷静收束。"]],"cards":[["“千寻铁锁沈江底”的下一句？","一片降旛出石头。"],["《西塞山怀古》的立场？","冷静叙述兴亡，以山不变对人事变。"]],"line":["人世几回伤往事，山形依旧枕寒流","翻看一家老品牌的历史展，感慨：人世几回伤往事，山形依旧枕寒流。"],"tags":["七律","怀古","刘禹锡"]},"tangjin_qianbei2":{"intro":"元稹《遣悲怀》三首，是悼念亡妻韦氏的名作。第二首写的是妻子去世后，生活中留下的小物件与旧日的戏言。悼亡诗最难写，因为最痛的往往是琐事。读它要看：衣裳、针线、婢仆、梦里送钱，诗人怎样把哀痛放进这些具体的东西里。","focus":["首联“昔日戏言身后事，今朝都到眼前来”：从前当玩笑说起的身后之事，如今一件件都到了眼前。“戏言”二字很重：当时的轻松，与今日的沉重对照，使人读到悔恨。","颔联“衣裳已施行看尽，针线犹存未忍开”是全诗最动人的一联：衣服已经送给别人，快要送完了；针线盒还在，却不忍心打开。一个“已”，一个“未”，一边是处理，一边是不忍。不写哭，写手的停顿。","颈联“尚想旧情怜婢仆，也曾因梦送钱财”：因怀念旧情，连妻子生前的婢仆也怜惜；也曾因梦见她，烧钱送钱财。前句是爱屋及乌，后句是真实的民俗动作。尾联“诚知此恨人人有，贫贱夫妻百事哀”是收束：我明知这种遗憾人人都会有，可贫贱夫妻，件件事都让人哀。最后一句把个人的哀扩成普遍的人情，又回到“贫贱”二字，是点睛。"],"notes":[["戏言","开玩笑说的话"],["身后事","死后的事"],["眼前来","来到眼前"],["衣裳","衣服"],["施","施舍，送人"],["行看尽","快要看到送完"],["针线","缝衣用的针与线"],["未忍开","不忍心打开"],["婢仆","奴婢仆人"],["送钱财","指梦后焚化钱财祭奠"],["此恨","这种遗恨"],["贫贱夫妻","共过贫贱日子的夫妻"]],"think":["为什么“针线犹存未忍开”比直接写哭更感人？","因为它写的是一个“不做”的动作。哭是情绪的释放，不开针线盒是情绪的压抑，压抑更接近真实的哀痛：不敢触碰与死者有关的东西。诗没有说哀，哀却从动作里出来。"],"quiz":[["“衣裳已施行看尽”的含义是？",["把亡妻的衣服送人，几乎送完","衣服被偷了","衣服太旧","为了做新衣"],"“施”是施舍，把衣物送给别人，说明已在处理遗物。"],["尾联“贫贱夫妻百事哀”的作用？",["把个人哀痛扩展为普遍的人情","批评贫穷","说明妻子身体不好","结束全诗的叙事"],"前一句承认人人都有此恨，后一句落到共贫贱的夫妻，普遍与个别合在一起。"]],"cards":[["“衣裳已施行看尽”的下一句？","针线犹存未忍开。"],["《遣悲怀》为什么感人？","以琐事和不忍的动作写悼亡，不靠直白哭诉。"]],"line":["衣裳已施行看尽，针线犹存未忍开","整理父亲的旧物时，在抽屉前停了很久：衣裳已施行看尽，针线犹存未忍开。"],"tags":["七律","悼亡","元稹"]},"tangjin_wuti1":{"intro":"李商隐的无题诗，往往以“无题”二字回避具体事件，使人猜解不止。这一首读起来相对清晰：前四句回忆昨夜宴会上遇见心仪之人，后四句转到今晨要去官府应卯，如蓬草飘转。写的是情，也是身不由己。具体所指是什么，历来有说法，存疑。","focus":["首联“昨夜星辰昨夜风，画楼西畔桂堂东”：重复“昨夜”，像一个人在反复回忆；星辰和风是当时的环境，画楼西、桂堂东是当时的地点。开头没有人物，却全是人物所在的空间感。","颔联“身无彩凤双飞翼，心有灵犀一点通”是千古名句：身上没有彩凤那样的双翼，不能飞到你身边；但心里像灵犀（犀角中有白纹贯通两端）一样，一点相通。上句写不能，下句写能，一退一进，恰是爱情中的真实。","颈联“隔座送钩春酒暖，分曹射复蜡灯红”写宴会：隔着座位玩送钩游戏，春酒暖；分组射覆，蜡灯红。“暖”和“红”两个色调，把热闹的宴会写得柔软。尾联“嗟余听鼓应官去，走马兰台类转蓬”一转：可叹我听到鼓声就得去应官，骑马到兰台（秘书省），像转蓬一样身不由己。宴席的暖与上班的冷，在这一句并置。"],"notes":[["星辰","星星"],["画楼","彩绘装饰的楼"],["桂堂","用桂木建的厅堂"],["彩凤","彩色的凤凰"],["双飞翼","一双能飞的翅膀"],["灵犀","传说犀角中有白纹，贯通两端"],["送钩","古代酒席上的游戏"],["春酒","春天酿的酒"],["射复","即射覆，猜物的游戏"],["蜡灯","蜡烛灯"],["听鼓","听更鼓，指赴官署点卯"],["转蓬","随风飘转的蓬草"]],"think":["为什么李商隐的无题诗常让人觉得“似懂非懂”？","因为他有意不交代具体的人、事、时间，只留下意象与情绪。这样既保护了自己，也让读者可以投射自己的经验。代价是难以确定作者当时具体写什么，所以“存疑”是对这类诗的诚实态度。"],"quiz":[["“心有灵犀一点通”的比喻是？",["犀角中的白纹贯通两端，比心意相通","犀牛的力量","一种珍贵药材","猎犀的技巧"],"传说犀角有纹理上下贯通，比喻两人心意相通。"],["尾联“走马兰台类转蓬”说明？",["身不由己，为公务奔忙","很自由","喜欢骑马","想去兰台读书"],"转蓬随风飘转，比喻为公务奔波，不能自主。"]],"cards":[["“身无彩凤双飞翼”的下一句？","心有灵犀一点通。"],["《无题·昨夜星辰》的结构？","前六句写宴会与相遇，尾联转到听鼓应官的无奈。"]],"line":["身无彩凤双飞翼，心有灵犀一点通","异地项目组的两个同事，不用多说就知道对方的意思：身无彩凤双飞翼，心有灵犀一点通。"],"tags":["七律","无题","李商隐"]},"tangjin_suigong":{"intro":"李商隐咏隋炀帝的名篇。隋炀帝要到江都（扬州）去享乐，并在那里终结。这首诗用假设与反问，写一个荒唐皇帝的结局。它的好处在于：不说教，用“若逢陈后主”这类设问，让炀帝自己尴尬。","focus":["首联“紫泉宫殿锁烟霞，欲取芜城作帝家”：长安的宫殿被烟霞锁着，炀帝却想取芜城（扬州）做帝家。“锁”字有意味：宫殿被丢下，君主的心已在别处。","颔联“玉玺不缘归日角，锦帆应是到天涯”是假设：若玉玺不是归于日角（相传指李渊的相貌），炀帝的锦帆可能要到天涯去。意思是：要不是唐取代了隋，他还会一路荒游下去。这一句带有嘲讽的假设。","颈联“于今腐草无萤火，终古垂杨有暮鸦”：如今腐草中再没有萤火虫，千古垂杨上只有暮鸦。史载炀帝曾征集萤火虫夜游，现在这类奢侈全都消失，留下的只有乌鸦。尾联“地下若逢陈后主，岂宜重问后庭花”：他在地下若遇到陈后主，难道还好意思再问《后庭花》？陈后主以《玉树后庭花》亡国，炀帝同样荒政而亡，两个亡国之君相见，只能无话。"],"notes":[["紫泉","指长安的水名，借指长安"],["烟霞","烟雾云霞"],["芜城","指扬州（广陵）"],["帝家","皇帝的居所"],["玉玺","皇帝的印"],["日角","额头隆起，相传是帝王之相"],["锦帆","隋炀帝游江都时的锦缎风帆"],["腐草无萤火","指炀帝曾搜集萤火虫的事已成过去"],["垂杨","垂柳"],["暮鸦","傍晚的乌鸦"],["陈后主","陈朝末代皇帝"],["后庭花","陈后主所作《玉树后庭花》"]],"think":["尾联为什么用“岂宜”这样的反问？","如果直接说“炀帝与陈后主都是亡国之君”，是议论；用反问就成了场景：地下相遇，两位皇帝面面相觑，哪里还敢再问当年的歌。反问把评论化为一个可以想象的画面，使讽刺变得生动而含蓄。"],"quiz":[["“玉玺不缘归日角”的意思是？",["如果国运不归于某位有帝王之相的人","玉玺被人偷了","玉玺有裂纹","指玉玺的制作"],"“日角”指帝王相，这里暗指李渊，意思是若非唐取代隋。"],["尾联运用的手法？",["设想相逢，以反问讽刺","直接批评","颂扬","夸张"],"通过“岂宜重问”的反问，讽刺炀帝与陈后主一样荒淫亡国。"]],"cards":[["“紫泉宫殿锁烟霞”的下一句？","欲取芜城作帝家。"],["《隋宫》尾联的讽刺方式？","设想两个亡国之君地下相逢，不好意思再提后庭花。"]],"line":["地下若逢陈后主，岂宜重问后庭花","看完一部关于财务造假的纪录片，说：地下若逢陈后主，岂宜重问后庭花。"],"tags":["七律","咏史","李商隐"]},"tangjin_wuti3":{"intro":"这首无题的前半写景，后半用典，最后落在“一寸相思一寸灰”。李商隐的无题常常如此：意象缠绕，情感却很分明。这一首写的是春夜里对一段无望感情的克制与自警，具体所指，历来说法很多，存疑。","focus":["首联“飒飒东风细雨来，芙蓉塘外有轻雷”：东风飒飒，细雨来了；荷塘外传来轻雷。“芙蓉塘”即荷塘，春雷又轻，营造出一种若有若无的躁动，是春心初动的背景。","颔联“金蟾啮锁烧香入，玉虎牵丝汲井回”写室内的器物：金蟾形的香炉锁着，烧的香一点点进入；玉虎形的辘轳牵着丝绳，汲井水回转。两件器物都有“进”“回”的动作，像是欲入而未入、欲回而未回，带有深闺的幽闭感。","颈联“贾氏窥帘韩掾少，宓妃留枕魏王才”用两个典故：贾充的女儿隔帘偷看韩寿，传说中甄后（宓妃）留下枕头给曹植（魏王才）。两个典故都与爱慕有关，一个是女慕男，一个是跨越生死的相知。尾联“春心莫共花争发，一寸相思一寸灰”：春心不要与花争着开放，每一寸相思都化作一寸灰。这句是对自己的警诫，也是最痛的句子。"],"notes":[["飒飒","风声"],["东风","春风"],["芙蓉塘","荷塘"],["轻雷","微弱的雷声"],["金蟾","金色蟾蜍形的香炉"],["啮锁","咬着锁，指香炉的锁扣"],["玉虎","玉虎形的辘轳"],["汲井","从井里打水"],["窥帘","隔着帘子偷看"],["宓妃","洛水女神，传说中指甄后"],["春心","春天里萌动的心思"],["一寸相思","一寸一寸的相思"]],"think":["“一寸相思一寸灰”为什么成为名句？","一是用“寸”量相思，把无形的感情变成可测的长度；二是“灰”字：相思不但增长，还同时在燃烧、化灰。一个量词，一个结果，把热烈与绝望压进七个字。这是李商隐把抽象感情变成物理过程的典型手法。"],"quiz":[["“春心莫共花争发”的意思是？",["不要让相思与春花一同盛开，要克制","要像花一样盛开","春天的花很美","不要种花"],"“莫”是劝诫，让春心不要像花一样绽放，是对自己的克制。"],["颈联用的典故主要涉及？",["男女之间的爱慕","朝廷政争","战争","隐居"],"贾氏窥帘、宓妃留枕，都是男女相悦的典故。"]],"cards":[["“春心莫共花争发”的下一句？","一寸相思一寸灰。"],["《无题·飒飒东风》的主旨？","写春夜里对无望感情的克制与自警。"]],"line":["春心莫共花争发，一寸相思一寸灰","发完那条冲动的长消息，又默默撤回：春心莫共花争发，一寸相思一寸灰。"],"tags":["七律","无题","李商隐"]},"tangjin_chouyi":{"intro":"筹笔驿在今四川广元北，传说是诸葛亮出师北伐时筹划军务的地方。李商隐经过此地，写下这首咏诸葛亮的七律。杜甫的《蜀相》《咏怀古迹》重在敬，李商隐这首重在悲：智谋、忠诚都在，却无法胜过天命。","focus":["首联“猿鸟犹疑畏简书，风云常为护储胥”：猿鸟还怀疑害怕他的军令，风云仿佛常常来保护他的营垒。把诸葛亮的威严写成自然界的反应，借此说明他的号令仍在，威势犹存。","颔联“徒令上将挥神笔，终见降王走传车”：白白让上将军挥动神笔筹划，终究看到降王乘传车被押走。“徒令”与“终见”是一对转折：你的筹划再神，终究看到后主投降。后一句指刘禅降魏。","颈联“管乐有才真不忝，关张无命欲何如”：管仲乐毅的才华，他确实当之无愧；可关羽、张飞已死，又能怎么办。把诸葛亮的才与无人可用并置。尾联“他年锦里经祠庙，梁父吟成恨有余”：以后经过成都的祠庙，他所吟的《梁父吟》里留下的遗恨无穷。以“恨”收束，是全诗基调。"],"notes":[["猿鸟","山中的猿与鸟"],["简书","军令文书"],["储胥","军营的栅栏"],["徒令","徒然使"],["上将","指诸葛亮"],["神笔","神机妙算的笔"],["降王","投降的君主，指刘禅"],["传车","驿站的车"],["管乐","管仲和乐毅"],["不忝","当之无愧"],["关张","关羽和张飞"],["梁父吟","诸葛亮喜欢吟的歌"]],"think":["为什么说李商隐的“恨”比杜甫的“泪”更冷？","杜甫的“长使英雄泪满襟”是情感的外溢；李商隐的“恨有余”是结论式的：智谋与时运的差距无法弥补，所以只剩恨。前者是人在哭，后者是历史在叹。两者不分高下，但读法不同。"],"quiz":[["“徒令上将挥神笔”中“徒令”的含义？",["白白地使","特别令","命令","徒步命令"],"“徒”是白白、徒然，与“终见”连用，写出筹划终成空的惋惜。"],["尾联“梁父吟成恨有余”的情感？",["遗恨无穷","喜悦","平静","讽刺"],"《梁父吟》是诸葛亮所吟之歌，“恨有余”写他壮志未酬的无尽遗憾。"]],"cards":[["“管乐有才真不忝”的下一句？","关张无命欲何如。"],["《筹笔驿》的基调？","对诸葛亮才高而运不济的惋惜与遗恨。"]],"line":["管乐有才真不忝，关张无命欲何如","评价一个优秀的项目经理，却遇到了没法克服的客观条件：管乐有才真不忝，关张无命欲何如。"],"tags":["七律","咏史","李商隐"]},"tangjin_lizhou":{"intro":"这首诗在文本里题作《利洲南渡》，一般认为是温庭筠在渡口等船时作（原题或作“利州南渡”，存疑）。它的风格接近王维、孟浩然：景色明净，末联用范蠡泛五湖的典，表达向往隐逸的心。读它要看前六句如何把渡口小景写得有层次。","focus":["首联“澹然空水对斜晖，曲岛苍茫接翠微”：澹然的水面对着斜晖，曲折的岛屿苍茫地连着青山。“澹”“空”是水的状态，“斜晖”是光，整幅画面以淡为主。","颔联“波上马嘶看棹去，柳边人歇待船归”：波上有马嘶，是在看船离岸；柳边的人休息，在等船回来。一去一归，两处人事，同在渡口，把渡口的生活气息写得很具体。","颈联“数丛沙草群鸥散，万顷江田一鹭飞”：数丛沙草旁群鸥散开，万顷江田上一只鹭鸶飞起。“数丛”与“群”，“万顷”与“一”，大小对照。尾联“谁解乘舟寻范蠡，五湖烟水独忘机”：谁懂得乘舟去找范蠡，在五湖烟水间独自忘掉机心。范蠡功成后泛舟五湖，是隐逸的象征，诗人借此说自己的向往。"],"notes":[["澹然","恬淡安静"],["空水","空明的水"],["斜晖","斜照的阳光"],["曲岛","弯曲的岛屿"],["翠微","青山"],["马嘶","马的叫声"],["棹","船桨，这里指船"],["歇","休息"],["沙草","沙地上的草"],["群鸥","成群的鸥鸟"],["范蠡","春秋时越国大夫，功成后泛舟五湖"],["忘机","忘掉机巧之心"]],"think":["这首诗为什么不像人们印象中的温庭筠？","温庭筠常被与“花间”的浓艳联系在一起。但这首诗用淡、空、疏的笔法，说明他诗的一面是接近王孟的清丽。这种差异提醒我们：读作者要读他的不同体裁，别用一个标签概括。"],"quiz":[["颈联“万顷江田一鹭飞”的写法是？",["以大衬小，万顷与一鹭对照","写农夫耕作","描写雪景","表示丰收"],"“万顷”极大，“一鹭”极小，大小对照，突出空阔。"],["尾联“谁解乘舟寻范蠡”表达的是？",["向往隐逸，忘掉机心","想做官","想经商","想报仇"],"范蠡功成后泛舟五湖，象征隐逸，“忘机”是放下机心。"]],"cards":[["“澹然空水对斜晖”的下一句？","曲岛苍茫接翠微。"],["《利洲南渡》结尾的向往？","如范蠡泛舟五湖，忘机隐居。"]],"line":["谁解乘舟寻范蠡，五湖烟水独忘机","在高铁上看窗外的湖，对同事说：谁解乘舟寻范蠡，五湖烟水独忘机。"],"tags":["七律","渡口","温庭筠"]},"tangjin_suwu":{"intro":"苏武出使匈奴被扣十九年，持节不屈，回到汉朝时汉武帝早已去世。温庭筠这首诗写的不是苏武的苦，而是他回来之后：宫室已非，故人已逝。读它要看时间怎样成为全诗的主角：去时壮年，归时白头。","focus":["首联“苏武魂销汉使前，古祠高树两茫然”：苏武见到汉使时魂销，如今古祠与高树相对茫然。“魂销”写重逢汉使的刹那，“两茫然”写千年后祠与树的空茫，时间一下子拉开。","颔联“云边雁断胡天月，陇上羊归塞草烟”是想象中的塞外生活：云边雁影断绝，胡地的月光；陇上羊群归来，塞草笼烟。“雁断”暗用鸿雁传书的典故，“羊归”则是他牧羊的日子。","颈联“回日楼台非甲帐，去时冠剑是丁年”是全诗最重的一联：回来时楼台已不是汉武帝时的甲帐，出去时戴冠佩剑是壮年。“非甲帐”与“是丁年”的“非”“是”，是物是人非的反向：人变老了，宫室也不是旧时。尾联“茂陵不见封侯印，空向秋波哭逝川”：茂陵（汉武帝陵）已不见封侯的恩赏，只能向秋水哭那逝去的岁月。"],"notes":[["魂销","魂魄消散，极度悲伤"],["汉使","汉朝使者"],["古祠","古老的祠庙"],["雁断","大雁断绝，指音信断"],["胡天","胡地的天空"],["陇上","陇山一带"],["塞草","边塞的草"],["甲帐","汉武帝以珠玉制作的华美帐幕"],["冠剑","戴冠佩剑，指使臣的装束"],["丁年","壮年"],["茂陵","汉武帝的陵墓"],["逝川","逝去的流水，喻时光"]],"think":["颈联“非甲帐”“是丁年”的对比为什么有力？","因为一个写物，一个写人；一个写回来，一个写出去。把“回日”与“去时”放在一起，十九年的光阴就被压成一对。更精妙的是：诗人没有写“白发”，只写“丁年”（壮年），让读者自己去补上衰老。"],"quiz":[["“去时冠剑是丁年”的“丁年”指？",["壮年","老年","童年","丁卯年"],"“丁”指成丁，壮年之意，与回国时的白发相对照。"],["尾联“空向秋波哭逝川”表达？",["对逝去岁月与故主的悲哀","对秋天的喜爱","对河流的赞美","旅行的快乐"],"逝川喻时光，空哭说明岁月已不可追回，故主已逝。"]],"cards":[["“回日楼台非甲帐”的下一句？","去时冠剑是丁年。"],["《苏武庙》的主题？","写苏武归来之后时间的虚空，忠节与岁月的代价。"]],"line":["回日楼台非甲帐，去时冠剑是丁年","外派十年回总部，办公楼、同事都变了：回日楼台非甲帐，去时冠剑是丁年。"],"tags":["七律","咏史","温庭筠"]},"tangjin_pinnv":{"intro":"秦韬玉的《贫女》写一位贫寒女子，一般被读成寒士的自况：有才有德，却不被赏识；技艺高超，却只为他人做衣裳。末句“为他人作嫁衣裳”后来成为成语。读它要看“自伤”这条情绪线，如何贯穿全诗。","focus":["首联“蓬门未识绮罗香，拟托良媒益自伤”：出身蓬门，不识绮罗的香气；想托个好媒人，却越发自伤。“未识”是出身，“益自伤”是处境，把贫寒与无助压在开头。","颔联“谁爱风流高格调，共怜时世俭梳妆”：谁喜欢高格调的风雅，大家只爱时髦的妆扮。前一句是自我期许，后一句是世风批评：世人只看外表的俭朴或华丽，不看格调。","颈联“敢将十指夸纤巧，不把双眉斗画长”：我敢夸十指的灵巧，却不愿与人比画眉的长短。这是自尊：以手艺立身，不以容貌取悦。尾联“苦恨年年压金线，为他人作嫁衣裳”：最苦恨的是年年压金线绣花，却是替别人做嫁衣。最后一句没有写“我”，却把全部委屈都收进去了。"],"notes":[["蓬门","用蓬草编的门，指贫家"],["绮罗","华美的丝织品"],["良媒","好的媒人"],["自伤","自己感伤"],["风流","风雅"],["格调","品格情调"],["时世","当时的世风"],["俭梳妆","朴素的妆扮"],["十指","十个手指"],["纤巧","精巧"],["金线","绣花用的金色线"],["嫁衣裳","出嫁时穿的衣服"]],"think":["“为他人作嫁衣裳”今天为什么仍常被引用？","因为它说出了一个常见处境：付出的劳动与收获的成果不属于同一个人。但要注意，原诗是贫女的苦恨，带有自尊与不甘；现代引用时若带上轻松的自嘲，意思就略有变化。引用前最好自问：我是在抱怨，还是在自嘲？"],"quiz":[["“不把双眉斗画长”的含意是？",["不愿靠容貌与人竞争","眉毛太短","不会化妆","喜欢画画"],"“斗画长”指在画眉上比长短，说的是不愿以外貌取悦。"],["“为他人作嫁衣裳”的原义是？",["自己贫苦，只能为别人的喜事劳作","自己出嫁","喜欢做衣服","慷慨捐赠"],"贫女年年为别人绣嫁衣，自己却无缘，是苦恨的收束。"]],"cards":[["“敢将十指夸纤巧”的下一句？","不把双眉斗画长。"],["《贫女》常被如何解读？","寒士自况，有才而不被赏识。"]],"line":["苦恨年年压金线，为他人作嫁衣裳","给上级起草了三年的发言稿，署名从来不是自己：苦恨年年压金线，为他人作嫁衣裳。"],"tags":["七律","自况","晚唐"]},"tangjin_xiangsi":{"intro":"王维的《相思》，全诗二十字，家喻户晓。红豆又名相思子，诗里问的是红豆，说的是人。别本的题目、字句略有出入，这里以《唐诗三百首》收录文字为准。读它要看一个很短的诗怎样用“问”和“劝”两个动作完成抒情。","focus":["首句“红豆生南国”是起笔，只写地：红豆生在南方。后人也把它当作“相思”的起点，因为红豆本来就是“相思子”的名字，诗里没有出现“相思”二字，意思却已经埋下。","第二句“春来发几枝”是一问：春天来了，红豆发了几枝？看起来是闲问，其实问的是有没有人、有没有想念。问的对象是红豆，实际是对远方的人。","后两句“愿君多采撷，此物最相思”：希望你多采一些，因为这东西最能寄相思。“愿”和“最”是全诗最直白的地方：前面都是含蓄，到最后才用一个“最”字，把情绪推满。短诗的力量就在于最后一句的突然直白。"],"notes":[["红豆","又名相思子，一种红色的豆"],["南国","南方"],["春来","春天来了"],["发几枝","长出几枝"],["愿君","希望你"],["采撷","采摘"],["此物","这东西，指红豆"],["最相思","最能引起相思"],["生","生长"],["多","多多"]],"think":["这首诗为什么不用一个“思”字就能让人懂？","因为红豆这个物象已经负载了“相思”的意义，只要出现，文化记忆就会补上。诗人要做的只是选对物象，不必多解释。这也说明，诗的意义不全由文字提供，而与共同的文化经验有关。"],"quiz":[["“春来发几枝”的作用是？",["以问的口吻表达惦念","询问农事","描写景物","表示季节"],"看似闲问春天红豆的生长，实则是对远方人的挂念。"],["“此物最相思”中“最”字的效果？",["把含蓄的情感推到顶点","说明红豆很贵","说明红豆很多","表示比较"],"前面含蓄，结尾用“最”字直接点明，使情感集中爆发。"]],"cards":[["“红豆生南国”的下一句？","春来发几枝。"],["《相思》的结构特点？","前两句含蓄起问，后两句直接劝采，由蓄到放。"]],"line":["愿君多采撷，此物最相思","给远方的朋友寄去一包家乡的特产，附一张纸条：愿君多采撷，此物最相思。"],"tags":["五绝","相思","王维"]},"tangjin_zashi":{"intro":"王维的《杂诗》其中一首：遇见从故乡来的人，不问家人，不问时事，只问窗前的寒梅开了没有。这是一个选择：一个人最想问的，往往不是最大的事，而是最细的事。读它要看“问”的内容为什么如此小。","focus":["首二句“君自故乡来，应知故乡事”是铺垫：你从故乡来，一定知道故乡的事。重复“故乡”二字，把思念先摆出来，口气像话家常，也像在积蓄一个大问题。","第三句“来日绮窗前”是转折点：你来的那天，我家雕花窗前……读者本期待一连串问题，诗人却把视线缩到一个地方：窗前。","末句“寒梅著花未”：寒梅开花了没有？问题小到只有一个，一株梅。它之所以动人，是因为一株梅承载了整个家：有人，有院子，有窗，有季节。“著花未”是唐代口语的问法，近于“开了没”，使这句问话更真实。"],"notes":[["故乡","家乡"],["应知","应当知道"],["来日","来的那天"],["绮窗","雕花的窗"],["寒梅","寒冬开放的梅花"],["著花","开花"],["未","疑问词，相当于“没有”"],["君","你"],["故乡事","故乡的事情"],["前","面前"]],"think":["为什么只问梅而不问人？","因为人的消息往往太重，问不出口；梅花是最安全的一个问题，又隐含了对家的全部想念。同时，“寒梅”在冬末春初开放，问它开没开，也是问时间过了多少。这类“绕开重的，问轻的”写法，是中国诗里很常见的深情方式。"],"quiz":[["“寒梅著花未”表达了什么？",["对家园的细微牵挂","对梅花的研究","对天气的关心","对故人的怨恨"],"问一株梅，其实是对整个家的牵挂，以小见大。"],["全诗结构的特点是？",["前三句铺垫，末句才落在小问题上","全篇议论","描写景色","叙事"],"前面一直在铺垫“故乡事”，最后问一件很小的事，形成落差。"]],"cards":[["“君自故乡来”的下一句？","应知故乡事。"],["《杂诗》最动人之处？","不问大事，只问窗前一株寒梅。"]],"line":["来日绮窗前，寒梅著花未","碰到刚从老家来的同事，别的没问，只问一句：老家那条街上的桂花开了没？"],"tags":["五绝","思乡","王维"]},"tangjin_zhongnanxue":{"intro":"祖咏参加科举考试，题目是《终南望余雪》，规定写六韵十二句，他只写了四句交卷，据说考官问起，他说“意尽”。这个故事的真实性存疑，但诗确实短而完整。读它要看一首咏雪诗怎样不出现“雪”以外的任何多余字。","focus":["首句“终南阴岭秀”：终南山的北面山岭秀美。“阴岭”是山的北坡，雪最容易留住的地方，诗人从站在长安城里望山开始。","第二句“积雪浮云端”：积雪好像浮在云的尽头。“浮”字把雪与云拉近，雪在山顶，云在山腰，雪像是被云托着。这一句是全诗的视觉高点。","后两句“林表明霁色，城中增暮寒”：林梢明亮起来，是雪后初晴的光；城里的傍晚反而更冷了。前一句写光，后一句写寒；雪融时更冷，是真实的体验。全诗没有直接说“余雪”，却处处是余雪。"],"notes":[["终南","终南山"],["阴岭","山的北面"],["秀","秀美"],["积雪","堆积的雪"],["浮","漂浮"],["云端","云的尽头"],["林表","树林的梢头"],["霁色","雪后初晴的光色"],["城中","长安城里"],["暮寒","傍晚的寒气"]],"think":["“城中增暮寒”为什么说是真实的体验？","因为雪消融会吸收热量，傍晚的气温确实会更低。诗人没有讲科学，只写感觉，却写对了。这也是好诗的特点：观察精确，不炫耀。"],"quiz":[["“积雪浮云端”中“浮”的作用是？",["使雪与云相接，画面轻盈","说明雪在水面","说明雪很轻","形容云很多"],"“浮”字让积雪像漂在云上，有一种轻而高的感觉。"],["结句“城中增暮寒”的含意？",["雪后天晴，傍晚更冷","城里很温暖","诗人有病","天快下雨"],"雪后初晴，化雪吸热，城中傍晚寒意更重。"]],"cards":[["“终南阴岭秀”的下一句？","积雪浮云端。"],["《终南望余雪》的特点？","只四句，写雪不说雪，以景与感觉完成。"]],"line":["林表明霁色，城中增暮寒","雨后傍晚下班，出了大楼才发现冷：林表明霁色，城中增暮寒。"],"tags":["五绝","咏雪","盛唐"]},"tangjin_jiande":{"intro":"孟浩然的《宿建德江》，建德江在今浙江，新安江流经建德的一段。夜晚泊舟，他看到旷野、天低、江清、月近，写成这短短二十字。读它要看“愁”字出现的位置：前面是景，最后一字之前，景与愁先分开了。","focus":["首二句“移舟泊烟渚，日暮客愁新”：把船移到烟雾笼罩的小洲边，傍晚时，客愁又新生。“新”字重要：客愁并非第一次，但每到日暮都像新的一样。","第三句“野旷天低树”：原野空阔，天空低得像压在树上。“旷”和“低”是错觉：因为空旷，天显得低，树显得小。这是视觉的真实。","末句“江清月近人”：江水清澈，月亮反而靠近人。月影在江中，所以显得近。“近人”二字有意思：在孤独的人身边，只有月亮肯靠近。前面铺开的是天地的阔，最后收在一个“人”字，景色把愁托了出来。"],"notes":[["移舟","把船移动"],["泊","停泊"],["烟渚","烟雾笼罩的小洲"],["日暮","傍晚"],["客愁","旅人的愁绪"],["新","新生"],["野旷","原野空阔"],["天低树","天空低垂到树梢"],["江清","江水清澈"],["月近人","月亮靠近人"]],"think":["“江清月近人”是景还是情？","既是景也是情。景的一面：江水清，月影映在水里，似乎在身边；情的一面：孤独的人觉得只有月亮陪伴。读诗时可以一边看景，一边听出情，但不必强分，这正是它的好处。"],"quiz":[["“野旷天低树”的写景特点是？",["因为原野空旷而显得天低","天空真的很低","树很高","天要下雨"],"空旷使天与树相接，视觉上天变低，是对空间感的精确描写。"],["全诗的情感线索是？",["日暮生客愁，景中见孤独","对美景的赞赏","离别","喜悦"],"首句点出客愁，后面以空旷与月近托出孤独。"]],"cards":[["“移舟泊烟渚”的下一句？","日暮客愁新。"],["《宿建德江》写“愁”的方式？","先点愁，再以旷野低天与近人之月来衬。"]],"line":["野旷天低树，江清月近人","夜里一个人在郊区加完班，看着空旷的停车场和月亮：野旷天低树，江清月近人。"],"tags":["五绝","羁旅","孟浩然"]},"tangjin_chunxiao":{"intro":"孟浩然的《春晓》，全诗几乎没有难字，也没有任何典故。它的好处在于：用四句话写出一个春天的早晨，同时留下一个问题：花落知多少？读它要看“听”的位置，不是看到的春，而是听到的春。","focus":["首句“春眠不觉晓”：春天睡得沉，不知不觉天亮了。“不觉”二字是舒适而不是遗憾，是春天特有的慵懒，也为后面的“闻”做铺垫。","第二句“处处闻啼鸟”：到处是鸟鸣。这是醒来后第一个感知：不是看见天亮，而是听见鸟声。“处处”写出鸟声无所不在。","后两句“夜来风雨声，花落知多少”：想起夜里的风雨声，不知花落了多少。前面是舒适，后面是淡淡的惜春。“知多少”不是真问，是一种轻轻的怅惘，也使全诗在明朗里带上一点留白。"],"notes":[["春眠","春天的睡眠"],["不觉晓","不知不觉天亮了"],["处处","到处"],["啼鸟","啼叫的鸟"],["夜来","昨夜"],["风雨声","风雨的声音"],["花落","花凋落"],["知多少","不知有多少"],["闻","听见"],["晓","天亮"]],"think":["为什么“花落知多少”不用回答？","因为它不是一个需要答案的问题，而是情绪的出口。春天本来就是美好中带着消逝的季节，这句话把这种感觉轻轻点出。如果直接说“可惜花落了”，就显得重；用问句，就保留了余味。"],"quiz":[["“夜来风雨声”在全诗中的作用是？",["引出对花落的联想","说明夜里很冷","描写下雨","表示天气不好"],"风雨声是晨起后回想的线索，由它联想到花落，转入惜春之情。"],["“处处闻啼鸟”写的是？",["听觉感受，晓醒的第一印象","视觉景色","嗅觉","味觉"],"诗人先听到鸟鸣，说明春晓是被声音唤醒的。"]],"cards":[["“春眠不觉晓”的下一句？","处处闻啼鸟。"],["《春晓》的结尾为什么好？","以问句收束，把惜春之情留成余味。"]],"line":["夜来风雨声，花落知多少","暴雨过后看到小区里满地的落花：夜来风雨声，花落知多少。"],"tags":["五绝","春","孟浩然"]},"tangjin_yesi":{"intro":"即家喻户晓的《静夜思》，在《唐诗三百首》里题作《夜思》。文字有版本差异，本书所用的本子在注里列出了“一作”。四句诗里没有一个典故，却是中文里最容易背的思乡诗。读它要看动作：看、疑、举头、低头。","focus":["首句“床前明月光”：写床前有明月的光。没有多余形容，只有三个名词：床、月、光。看似平凡，却把读者立刻放进夜晚的卧室里。","第二句“疑是地上霜”：以为是地上的霜。“疑”字写出诗人的半醒与迷离，也暗示了秋夜的寒意。月光像霜，是视觉相似，也是感觉相通：清冷。","后两句“举头望明月，低头思故乡”是两个动作的对仗：举头与低头。望月是实，思乡是虚，从“看”到“想”，这个转折完全靠动作完成。四句话里，诗人始终没有说一个“愁”字。"],"notes":[["床前","床边"],["明月光","明亮的月光"],["疑是","怀疑是，以为是"],["地上霜","地上的白霜"],["举头","抬头"],["望明月","望着明月"],["低头","垂下头"],["思故乡","想念故乡"],["地上","地面上"],["霜","秋冬的白色冰晶"]],"think":["为什么这首诗不用修辞，反而成为经典？","因为它的力量来自动作与场景的真实。半夜醒来，月光洒在地上，那种刹那间的失神与想家，是人人有过的经验。诗人没有发明新的比喻，只是诚实地记录，这种诚实就是修辞。"],"quiz":[["“疑是地上霜”的“疑”表现了？",["半梦半醒的错觉","诗人的怀疑精神","对天气的判断","对朋友的怀疑"],"“疑”是错觉，把月光当作霜，暗含夜深的迷离与寒意。"],["后两句的结构特点？",["用举头、低头两个动作完成转折","描写月亮的形状","描写故乡的景物","描写朋友"],"两个相对的动作，把眼前的月与心中的故乡连接起来。"]],"cards":[["“床前明月光”的下一句？","疑是地上霜。"],["《夜思》的核心写法？","以动作而不是形容完成思乡。"]],"line":["举头望明月，低头思故乡","中秋节在外地出差，抬头看见月亮，低头给家里发了条消息：举头望明月，低头思故乡。"],"tags":["五绝","思乡","李白"]},"tangjin_guanque":{"intro":"王之涣的《登鹳雀楼》，鹳雀楼在今山西永济一带的黄河边。四句诗，前两句写所见，后两句写所愿，是五绝里把景与理结合得最干净的一首。读它要看“尽”“入”“穷”“更上”这几个动词。","focus":["首句“白日依山尽”：太阳靠着山沉下去。“依”字让太阳有了依靠，“尽”字写出光的消失。这一句在写时间，也在写方向：西边。","第二句“黄河入海流”：黄河流入大海。实际上，鹳雀楼离海很远，这是想象与概括：看见河流东去，就像看见它入海。前两句一西一东，一落一流，把视野拉得非常大。","后两句“欲穷千里目，更上一层楼”：想看尽千里的远方，就再登一层楼。这是“议论”，却没有说教，因为它来自眼前的情景：站在楼上，已经看到了很远，还想更远。后人把它当作进取的格言，是由具体动作引出的。"],"notes":[["白日","太阳"],["依山","靠着山"],["尽","消失，落尽"],["入海流","流向大海"],["欲穷","想要看尽"],["千里目","千里远的视野"],["更上","再登上"],["一层楼","高一层的楼"],["黄河","黄河"],["依","依靠"]],"think":["“更上一层楼”算不算说教？","如果单独拿出来，是格言；放回诗里，它是登楼者的真实冲动：已经看到很远，还想再远一点。因此它不让人觉得在教训，而像是诗人自己说给自己听。好的哲理诗就是这样，让道理从场景里长出来。"],"quiz":[["“黄河入海流”写的是？",["想象与概括的远景","眼前真实看到黄河入海","黄河的源头","河水干涸"],"鹳雀楼离海很远，这是诗人以眼前河流想象其终点，是概括。"],["后两句的作用是？",["由景入理，表达进取","描写游人","指出方向","讽刺"],"从所见之景转到所愿之事，以动作写出进取之心。"]],"cards":[["“白日依山尽”的下一句？","黄河入海流。"],["《登鹳雀楼》由景入理的方式？","写完所见，再以“更上一层楼”引出愿望。"]],"line":["欲穷千里目，更上一层楼","给刚拿到证书的新人一句话：欲穷千里目，更上一层楼。"],"tags":["五绝","登临","王之涣"]},"tangjin_jiangxue":{"intro":"柳宗元被贬永州时写下的《江雪》。四句话，前两句极空，后两句极静，中间一个蓑笠翁。关于它的寓意，读者历来有“孤高”“愤世”“自适”等解读，没有定论。读它要看画面的减法：从千山到一舟，从万径到一人。","focus":["首二句“千山鸟飞绝，万径人踪灭”：千山没有一只鸟，万条路没有一个人。“千”与“万”是极大，“绝”与“灭”是极空。这是两个大数字与两个否定的叠加，空到无法再空。","第三句“孤舟蓑笠翁”：画面里出现了唯一的存在：一条孤舟，一位披蓑戴笠的老翁。前面的极空，使这一点非常醒目，也非常小。","末句“独钓寒江雪”：独自在寒冷的江雪中垂钓。“独”与“寒”再把孤寂推高。有人读为“钓的不是鱼”，是在钓雪、钓孤独；有人读为诗人自况。这种“钓什么”的疑问，正是诗留给读者的位置。"],"notes":[["千山","众多的山"],["鸟飞绝","鸟都不飞了"],["万径","千万条道路"],["人踪灭","人的足迹消失"],["孤舟","孤零零的船"],["蓑笠","蓑衣和斗笠"],["翁","老人"],["独钓","独自垂钓"],["寒江","寒冷的江"],["雪","雪"]],"think":["“独钓寒江雪”钓的是什么？","字面当然是鱼，但在冰天雪地里钓鱼本身不合常理，所以读者自然想到别的：钓的是孤独，或是一种气节，或是诗人不甘沉沦的姿态。要小心，这类解读都是推断，诗里没有任何一个字明说。承认这一点，读诗反而更自由。"],"quiz":[["前两句“千山鸟飞绝，万径人踪灭”的效果？",["以极大数字与否定词营造极空","描写热闹","描写山路","表现春景"],"“千”“万”与“绝”“灭”叠加，造出一个空无一物的世界，为末句的孤翁做铺垫。"],["“独钓寒江雪”留给读者的是？",["多种解读的空间","明确的结论","对渔业的描写","对天气的预报"],"诗没有说明钓什么，也没有说明为什么，所以可解读为孤寂、气节或自况。"]],"cards":[["“千山鸟飞绝”的下一句？","万径人踪灭。"],["《江雪》的画面特点？","从千山万径减到一舟一人，空与孤到极致。"]],"line":["孤舟蓑笠翁，独钓寒江雪","在一个没有任何人理解的岗位上坚持做完一件事：孤舟蓑笠翁，独钓寒江雪。"],"tags":["五绝","贬谪","柳宗元"]},"tangjin_xinggong":{"intro":"元稹的《行宫》，二十字写尽一座旧宫与几位老宫女。唐代行宫是皇帝出巡时居住的宫殿，平日冷落。诗里没有一个议论字，却读出了兴亡与时间。读它要看“寥落”“寂寞”“白头”“闲坐”这几个字，怎样一层层把悲写出来。","focus":["首句“寥落古行宫”：寥落是冷清，古是年深，行宫是平时无人居住的宫殿。三个词三层：冷、旧、空。这一句只写环境，却定下了全诗的基调。","第二句“宫花寂寞红”：宫里的花依然红着，却无人欣赏。红是热闹的颜色，寂寞是孤独的情绪，两者相反，对比出“红”的无用。花不管人，所以红得越艳，越显寂寞。","后两句“白头宫女在，闲坐说玄宗”是全诗的重心：白头的宫女还在，闲来无事谈论玄宗。“在”字沉重：她们是少数还活着的见证者；“闲坐”是日常，“说玄宗”是盛世的回响。一个“说”字，把一个时代的盛衰交给了几位老妇人的闲谈。"],"notes":[["寥落","冷落稀少"],["古行宫","年代久远的行宫"],["宫花","宫中的花"],["寂寞","孤独冷清"],["红","花开红艳"],["白头","头发白了，指年老"],["宫女","宫中女子"],["在","仍然活着"],["闲坐","闲来坐着"],["玄宗","唐玄宗"]],"think":["为什么这首诗不写“玄宗说了什么”，只写“说玄宗”？","因为内容并不重要，重要的是“还在说”。几位白头宫女把一个时代当作闲谈，这种日常化正是历史沉降后的样子：当年惊天动地的人和事，最终变成老人闲聊的话题。不写内容，反而给读者留了最大的联想空间。"],"quiz":[["“宫花寂寞红”的写法特点是？",["以花红衬人寂寞","描写春天","描写花的品种","赞美宫廷"],"红是热烈的颜色，用在无人观赏的宫里，反衬出寂寞。"],["“白头宫女在”中“在”字的含意是？",["仍然活着，是历史的见证","在场","住在宫里","站在那里"],"“在”强调她们依然存活，成为盛世的最后见证者。"]],"cards":[["“寥落古行宫”的下一句？","宫花寂寞红。"],["《行宫》写兴亡的方式？","以白头宫女闲谈玄宗，不议论而兴亡自现。"]],"line":["白头宫女在，闲坐说玄宗","行业老前辈聚在一起，开口还是当年的故事：白头宫女在，闲坐说玄宗。"],"tags":["五绝","宫怨","元稹"]},"tangjin_liushiju":{"intro":"白居易邀请一位姓刘、排行十九的朋友来喝酒。这是一封极短的请柬：绿色的新酒，红泥小火炉，天快下雪，来喝一杯吧。读它要看一首邀请诗怎样靠几样具体的东西，让人觉得不去就可惜。","focus":["首句“绿蚁新醅酒”：“绿蚁”指新酿的酒面浮起的绿色泡沫，像细小的蚂蚁；“新醅”是刚酿成还没过滤的酒。这一句写酒，却写成色与形，带着一点新鲜。","第二句“红泥小火炉”：红泥做的小炉子，用来温酒。绿对红，酒对炉，色彩上一冷一暖。小炉子是家常物，使邀请显得亲近，不是大宴。","后两句“晚来天欲雪，能饮一杯无”：傍晚天要下雪了，能不能来喝一杯？“天欲雪”是最关键的邀请理由：天气越冷，越想要有人陪。“无”是唐代口语的疑问语气，等于“吗”，使全句像面对面的问话。"],"notes":[["绿蚁","新酒面上浮起的绿色泡沫"],["新醅","新酿的未滤的酒"],["红泥","红色的陶土"],["小火炉","小的火炉，用来温酒"],["晚来","傍晚"],["天欲雪","天要下雪了"],["能饮","能否来喝"],["一杯","一杯酒"],["无","疑问语气词，相当于“吗”"],["酒","酒"]],"think":["这首诗为什么能成为“邀请”的经典？","它没有任何客套或劝说，只是摆出了几样东西：酒、炉、雪，然后问一句“能不能”。对方能想象出画面，自然想来。好的邀请不是理由充分，而是让对方看见邀请的场景。"],"quiz":[["“晚来天欲雪”的作用？",["说明天气寒冷，更需要相聚","描写下雪的场景","说明时间太晚","暗示不能出门"],"天欲雪，寒意将至，正是饮酒相聚的好时刻，是最含蓄的邀请理由。"],["“能饮一杯无”中“无”的意思？",["吗，疑问语气","没有","无聊","不要"],"唐代口语中，“无”放句末表示疑问，相当于“吗”。"]],"cards":[["“绿蚁新醅酒”的下一句？","红泥小火炉。"],["《问刘十九》的特点？","以酒、炉、雪三样东西发出邀请，口语化、亲近。"]],"line":["晚来天欲雪，能饮一杯无","冬天下班路上给老友发消息：晚来天欲雪，能饮一杯无。"],"tags":["五绝","邀饮","白居易"]},"tangjin_leyou":{"intro":"李商隐的《登乐游原》，乐游原在长安城南，是唐人登高览胜的去处。傍晚心情不好，驱车登上古原，看到夕阳，留下这句千古流传的话。读它要看前后两句的关系：一句赞美，一句叹息，一个“只是”转了全诗。","focus":["首二句“向晚意不适，驱车登古原”：傍晚时分心情不舒服，驱车登上古原。“意不适”三个字交代了登高的原因：不是游玩，是排遣。一个“驱车”显得有些急，有一种不想待在原处的心态。","第三句“夕阳无限好”：夕阳无比美好。这是全诗最明亮的一句，也是最直白的赞美。因为前面写了心情不适，这句的美好更像是一种解脱。","末句“只是近黄昏”：只可惜已近黄昏。“只是”是转折词，轻轻一转，把赞美变成了叹息。这句诗常被读成对时光、对盛世或对个人暮年的感慨，具体指什么，诗里没有说，是留白，也是争议所在。"],"notes":[["向晚","傍晚"],["意不适","心情不舒畅"],["驱车","赶着车"],["古原","古老的高原，指乐游原"],["夕阳","夕照的太阳"],["无限好","好到没有边际"],["只是","只可惜"],["近黄昏","接近黄昏"],["登","登上"],["原","高平的原野"]],"think":["“夕阳无限好，只是近黄昏”是惋惜还是赞美？","两者同在，缺一不可。去掉“无限好”，就只是衰败；去掉“近黄昏”，就只是风光。两者合起来才有一种“美因为将逝而更美”的意味。至于是否指向某个具体的时代或个人，诗里没有证据，不妨留白。"],"quiz":[["“只是近黄昏”中“只是”的作用？",["转折，把赞美转为叹息","强调","限定","比较"],"“只是”相当于“只可惜”，使前面的赞美带上一点遗憾。"],["首联交代了什么？",["登原的原因是心情不适","登原为了游玩","登原是为了会友","登原为了迎接客人"],"“意不适”是登高的直接原因。"]],"cards":[["“向晚意不适”的下一句？","驱车登古原。"],["《登乐游原》的核心？","夕阳之美与黄昏将近的惋惜并存。"]],"line":["夕阳无限好，只是近黄昏","看到一位老工匠在作坊里做最后一件作品，感叹：夕阳无限好，只是近黄昏。"],"tags":["五绝","登临","李商隐"]},"tangjin_xunyin":{"intro":"贾岛的《寻隐者不遇》，全诗是一问一答的对话：我去拜访隐者，遇到童子，问师父在哪里。读它要看三层回答：采药去，在这座山，云深找不到。每一层都比前一层更远。","focus":["首二句“松下问童子，言师采药去”：松树下问童子，童子说师父采药去了。场景极简：一棵松，一个童子，一问一答。“言”字把答话转述了出来，省去了引号。","第三句“只在此山中”：只在这座山里。这是第二层回答：不是远行，就在附近。读者本来觉得可以追了，希望出现。","末句“云深不知处”：云太深，不知道在哪儿。这是第三层，也是真正的回答：近在咫尺，却找不到。“不知处”没有说“不在”，而是“不知”，这给了隐者一种神秘感：他既在，又不可见。整首诗通过三次转折，写出了“不遇”之中的“遇”：遇见了隐者的境界。"],"notes":[["松下","松树下"],["童子","小男孩，指隐者的徒弟"],["言","说"],["师","师父，指隐者"],["采药","采集药材"],["去","去了"],["只在","只是在"],["此山","这座山"],["云深","云雾深重"],["不知处","不知道在哪里"]],"think":["“不遇”为什么反而成就了诗？","因为如果遇到，诗只能写“见面说了什么”，容易落入应酬；不遇，则把全部空间留给想象：隐者在哪、是什么样的人、山有多深。云深不知处，既是失望，也是敬意，因为越难找到，越说明他是真隐者。"],"quiz":[["全诗的结构是？",["三层回答，层层推远","描写景物","记叙游览","议论"],"采药去、只在此山、云深不知处，每一层都更远一步。"],["“云深不知处”的含意是？",["隐者近在山中却难以寻见","隐者已经去世","隐者搬家了","云很重"],"云雾缭绕，使人无从寻找，也暗示隐者的高远。"]],"cards":[["“松下问童子”的下一句？","言师采药去。"],["《寻隐者不遇》的写法？","一问一答，三层推远，以不遇写隐者的境界。"]],"line":["只在此山中，云深不知处","想拜访一位低调的前辈，对方行踪不定：只在此山中，云深不知处。"],"tags":["五绝","隐逸","贾岛"]},"tangjin_hanjiangdu":{"intro":"《渡汉江》，《唐诗三百首》署李频，也有说是宋之问所作，作者归属存疑。它写一个人久别家乡，终于要回去，快到家门时反而不敢问讯的心理。读它要看“绝”“怯”“不敢”三个词，怎样描写一个人的近乡心情。","focus":["首二句“岭外音书绝，经冬复历春”：岭南一带，家书断绝，经过冬天，又过了春天。“绝”是断了音信，“经冬复历春”是时间流转，一年又一年。这两句交代了“久别”的前提。","第三句“近乡情更怯”是全诗的核心：越接近故乡，心里越胆怯。按常理，近乡应该高兴，但这里反而“更怯”。这是对人性的精准观察：怕听到坏消息，怕面对变化。","末句“不敢问来人”：不敢向迎面走来的人打听家里的情况。前一句是心理，这一句是动作：越想知道，越不敢问。两句合起来，就是“怯”的完整画面。"],"notes":[["岭外","五岭以南，指岭南"],["音书","书信消息"],["绝","断绝"],["经冬","经过冬天"],["复","又，再"],["近乡","接近故乡"],["情更怯","心情更胆怯"],["不敢","没有勇气"],["问","打听"],["来人","迎面走来的人"]],"think":["“近乡情更怯”为什么能引起普遍共鸣？","因为它说出了一种矛盾：越想知道，越怕知道。久别回家的人，既有期待，也有对失去的恐惧。这种心理在今天的“春节返乡”“多年不见”等场景里仍然存在，所以这句话经久不衰。"],"quiz":[["“近乡情更怯”的心理基础是？",["害怕得知坏消息","不想回家","对路途陌生","身体不适"],"久别无音，越接近家越担心家中变故，所以胆怯。"],["末句“不敢问来人”是？",["以动作写心理","表示没有路人","说明路人很凶","描写道路"],"不敢打听，是“怯”的具体表现。"]],"cards":[["“岭外音书绝”的下一句？","经冬复历春。"],["《渡汉江》的名句及含意？","“近乡情更怯”，越近家越怕听到坏消息。"]],"line":["近乡情更怯，不敢问来人","临近老家的最后一段路，对着车窗里的自己：近乡情更怯，不敢问来人。"],"tags":["五绝","归乡","晚唐"]},"tangjin_chunyuan":{"intro":"《春怨》的作者金昌绪，生平不详。这首诗是四句一气的“口语诗”：打黄莺，因为黄莺啼惊了梦，梦里本是去辽西见丈夫。读它要看“因果链”：打起莺—莫教啼—惊妾梦—不得到辽西，每一句都是上一句的原因。","focus":["首二句“打起黄莺儿，莫教枝上啼”：把黄莺赶起来，别让它在枝头啼叫。语气是急的，像是日常里被惹恼的口气。黄莺本来是春天美好的鸟，这里却被当成敌人。","第三句“啼时惊妾梦”：它一啼，惊醒了我的梦。这句交代原因：不是讨厌鸟，是怕梦被惊醒。至此，前面两句的“急”才有了理由。","末句“不得到辽西”：梦里就快到辽西了，却没能到。辽西是丈夫戍边之地，梦是唯一可以去的地方。因此，一只黄莺打断的，不是睡眠，而是一次相见。四句诗用倒推的逻辑，把一个思妇的心事说得自然又深。"],"notes":[["打起","驱赶得飞起来"],["黄莺儿","黄莺鸟"],["莫教","不要让"],["枝上","枝头"],["啼","啼叫"],["时","时候"],["惊妾梦","惊醒我的梦"],["妾","女子自称"],["不得","不能"],["辽西","辽河以西，古代边地"]],"think":["这首诗为什么读起来像口语？","因为它基本是一个因果链：先说“打”，再说“为什么打”，最后说“打的后果”。这种逻辑倒推，是人日常说话的方式。诗人没有用华丽的词，用的是人在生气、着急时的语序，所以显得真。"],"quiz":[["“打起黄莺儿”的目的？",["不让黄莺惊醒自己的梦","惩罚黄莺","捕捉黄莺","驱赶春天"],"黄莺啼叫会惊醒梦，打起它是为了保住梦。"],["“不得到辽西”的含意？",["梦中不能与丈夫相会","没有去辽西","路途遥远","辽西没有人"],"辽西是丈夫戍边处，梦被惊醒，相见落空。"]],"cards":[["“打起黄莺儿”的下一句？","莫教枝上啼。"],["《春怨》的逻辑结构？","因果倒推：打莺—不让啼—惊梦—不到辽西。"]],"line":["啼时惊妾梦，不得到辽西","凌晨三点被一条推送吵醒，没来得及把那个梦做完：啼时惊妾梦，不得到辽西。"],"tags":["五绝","闺怨","金昌绪"]},"tangjin_yujie":{"intro":"李白的《玉阶怨》，题目是乐府旧题，写宫中女子等待的哀怨。全诗没有一个“怨”字，只写一个人在夜里的动作：站着、回屋、放下帘、望月。读它要看这些动作怎样替代了所有的话。","focus":["首二句“玉阶生白露，夜久侵罗袜”：玉石台阶上生出白露，夜深了，露水浸湿了罗袜。“夜久”说明她站了很久；“侵”写出露水慢慢渗入。她没有说话，也没有动，时间用袜子的湿度来计算。","第三句“却下水晶帘”：回到屋里，放下水晶帘。“却”是回转，说明她终于放弃等待；“水晶帘”是透明的，放下帘子却挡不住视线。这一句是一个小动作，包含了放弃与不甘。","末句“玲珑望秋月”：隔着晶莹的帘子，仍然望着秋月。“玲珑”可以形容帘，也可形容月，两可。她放下了帘，却放不下视线，月亮在，她等的人不在。全诗的哀怨，就在“放下”与“还望”之间。"],"notes":[["玉阶","玉石做的台阶"],["白露","白色的露水"],["夜久","夜深了"],["侵","浸入"],["罗袜","丝织的袜子"],["却下","退回屋内并放下"],["水晶帘","水晶般透明的帘子"],["玲珑","晶莹剔透"],["秋月","秋天的月亮"],["望","望着"]],"think":["为什么全诗没有“怨”字却能叫“玉阶怨”？","因为怨已经在动作里：站到露湿袜，退回屋里，隔着帘子仍望月。读者只要把这些动作连起来，就知道她在等待与失望。诗人选择让动作说话，是一种“藏”的功夫，也是宫怨诗的高处。"],"quiz":[["“夜久侵罗袜”的作用？",["以露湿袜写等待时间之长","描写衣着","说明天气潮湿","表现孤单"],"站得久了，露水浸湿袜子，是以物写时间。"],["“玲珑望秋月”表达了什么？",["放下帘仍放不下期盼","欣赏月色","月亮很小","对秋天的喜欢"],"帘子是透明的，仍然隔帘望月，是等待与不甘。"]],"cards":[["“玉阶生白露”的下一句？","夜久侵罗袜。"],["《玉阶怨》不写“怨”字的写法？","以站立、放帘、望月等动作表现哀怨。"]],"line":["却下水晶帘，玲珑望秋月","等了一晚没有等到那个电话，关了灯却还看着手机：却下水晶帘，玲珑望秋月。"],"tags":["五绝","宫怨","李白"]},"tangjin_huixiang":{"intro":"贺知章晚年告老还乡，回到越州一带的故里，写下这首《回乡偶书》。诗里没有宏大的感叹，只有一个很小的场景：孩子笑问“客从何处来”。读它要看前两句的自我描述与后两句的他人眼光，两个角度合成一幅画。","focus":["首句“少小离家老大回”：年少离家，年老归来。一个“少小”，一个“老大”，两个词把几十年压成一句。没有数字，但时间的长度一下子出来了。","第二句“乡音无改鬓毛衰”：乡音没有变，鬓毛已经稀疏。前半是不变，后半是变。人变老了，口音还是旧的。这两句是自我观察，带着一点自嘲。","后两句“儿童相见不相识，笑问客从何处来”：孩子们见到他，不认识，笑着问：客人从哪里来？一个“笑”字化解了悲伤，一个“客”字却包含了最深的酸楚：回到故乡，被当成了外乡人。全诗的力量就在“客”字上。"],"notes":[["少小","年少时"],["老大","年老"],["乡音","家乡的口音"],["无改","没有改变"],["鬓毛","两鬓的头发"],["衰","稀疏、衰减"],["儿童","孩子们"],["不相识","不认识"],["笑问","笑着问"],["客","外来的客人"]],"think":["“笑问客从何处来”为什么让人心酸？","因为孩子的笑是无辜的，他们只是按眼前所见发问。但在诗人听来，每个字都是针：我明明是这里长大的人，现在却被问“从哪来”。悲伤没有被说出，而是被孩子的笑托了出来。这是反衬的力量。"],"quiz":[["“乡音无改鬓毛衰”的对比是？",["口音不变，容貌已老","口音已变，容貌不变","口音和容貌都变","口音和容貌都不变"],"“无改”是口音，“衰”是鬓毛，一不变一变。"],["末句“客从何处来”的辛酸在于？",["故乡人把自己当成外来者","孩子们太调皮","诗人迷路","路程遥远"],"回到故乡，却被当作客人，是离乡太久的痛。"]],"cards":[["“少小离家老大回”的下一句？","乡音无改鬓毛衰。"],["《回乡偶书》的情感关键？","一个“客”字，写出久别的陌生。"]],"line":["乡音无改鬓毛衰","参加三十年后的同学会，一开口都是当年的口音：乡音无改鬓毛衰。"],"tags":["七绝","归乡","贺知章"]},"tangjin_taohua":{"intro":"张旭是有名的草书家，诗留下得不多，《桃花溪》是其中之一。它写的是一片桃花顺着溪水流去，让诗人想到陶渊明笔下的桃花源，于是问：洞在哪里？读它要看这首诗怎样把一个文学传统轻轻接上，又不说破。","focus":["首句“隐隐飞桥隔野烟”：隐约的高桥隔着野外的烟雾。“隐隐”“隔”两字把画面拉远、变朦胧。像一幅有雾的山水，人在桥外，进不去。","第二句“石矶西畔问渔船”：在石矶的西边，向渔船问路。“问”字是全诗的动作，也是一个伏笔：他在问什么，到后两句才知道。","后两句“桃花尽日随流水，洞在清谿何处边”：桃花整天随着流水漂走，那个洞口在清溪的哪一边？这里化用了陶渊明《桃花源记》里渔人沿溪见桃林的故事。诗人没有说“桃花源”，只说“洞”，让读者自己连起来。问渔船，实际是在问仙境。"],"notes":[["隐隐","隐约，模糊"],["飞桥","高架的桥"],["野烟","野外的烟雾"],["石矶","水边突出的岩石"],["西畔","西边"],["渔船","打鱼的船"],["桃花","桃花"],["尽日","整天"],["清谿","清澈的溪流"],["何处边","在哪一边"]],"think":["为什么诗里不提“桃花源”三个字？","因为一旦说出，诗就成了对典故的复述；不提，只用“桃花”“流水”“洞”这三样东西，读者会自己想起。典故用得好，是让读者以为是自己想到的。这也是中国诗歌里“用而不露”的一种功夫。"],"quiz":[["“洞在清谿何处边”暗用了？",["陶渊明《桃花源记》的故事","屈原《离骚》","《诗经》","李白的诗"],"桃花、溪流、洞口，都是《桃花源记》的要素，诗人借此暗问仙境所在。"],["首句“隐隐飞桥隔野烟”的作用是？",["营造朦胧神秘的氛围","描写桥的结构","描写路途","描写人物"],"“隐隐”“隔野烟”使画面模糊，为寻找仙境做铺垫。"]],"cards":[["“桃花尽日随流水”的下一句？","洞在清谿何处边。"],["《桃花溪》与陶渊明的关系？","暗用《桃花源记》，以问渔船写寻仙境。"]],"line":["桃花尽日随流水，洞在清谿何处边","想找一个能安静写作的小镇，翻了半天地图：桃花尽日随流水，洞在清谿何处边。"],"tags":["七绝","山水","张旭"]},"tangjin_jiuyue9":{"intro":"王维的《九月九日忆山东兄弟》，传为少年时作（一般说十七岁，存疑）。这里“山东”指华山以东的家乡一带，不是今天的山东省。重阳节登高、插茱萸是习俗。读它要看诗的视角翻转：前两句写自己，后两句写远方的兄弟。","focus":["首二句“独在异乡为异客，每逢佳节倍思亲”：一个人在异乡做异乡人，每逢佳节更加想念亲人。“异乡”“异客”重复“异”，强调陌生。“倍”字是量词，把思念放大一倍，这句话几乎成了独自在外之人的口头禅。","第三句“遥知兄弟登高处”：远远地知道，兄弟们正在登高。“遥知”是想象：我在这里想你们，你们此刻在做什么？这一步是诗的转折：由自己转向家人。","末句“遍插茱萸少一人”：大家都插上了茱萸，少了一个人。这个“少一人”是诗的亮点：诗人不写自己思念家人，而是想象家人在思念自己。这种翻进一层的写法，让思念变成相互的，也更有温度。"],"notes":[["异乡","他乡"],["异客","外乡的人"],["佳节","美好的节日"],["倍","加倍"],["思亲","想念亲人"],["遥知","远远地知道"],["登高","重阳节登高习俗"],["兄弟","兄弟们"],["遍插","都插上"],["茱萸","重阳节佩戴的香草，传说可避邪"]],"think":["“遍插茱萸少一人”为什么比“我很想你们”更动人？","因为它把我的缺席写成了对方的缺口。一个“少”字，让思念变得具体：不是我想念，而是他们之中少了一个。这样既说了想念，又说了自己对家人的重要，是翻进一层的写法。"],"quiz":[["“山东”在诗中指？",["华山以东的家乡一带","今山东省","泰山","长安"],"唐代“山东”常指崤山或华山以东，王维家乡在蒲州一带。"],["末句的转折是？",["从思念转到想象家人思念自己","结束登高","描写茱萸","批评节日"],"诗人想象兄弟登高插茱萸时发现少了自己，使思念变得相互。"]],"cards":[["“独在异乡为异客”的下一句？","每逢佳节倍思亲。"],["《九月九日忆山东兄弟》的翻进一层？","由自己思念转到想象家人思念自己。"]],"line":["遥知兄弟登高处，遍插茱萸少一人","春节值班在外，看家人视频里的团圆饭：遥知兄弟登高处，遍插茱萸少一人。"],"tags":["七绝","思亲","王维"]},"tangjin_furong":{"intro":"王昌龄送友人辛渐去洛阳，在润州（今江苏镇江）的芙蓉楼分别。送别诗里常写离愁，这首的末句却是一句自白：“一片冰心在玉壶”。读它要看送别场景怎样自然带出一个人的品格。","focus":["首句“寒雨连江夜入吴”：寒冷的雨连着江水，夜里进入吴地。“连江”是雨势与江面相连；“入吴”是随着夜色逼近的方向。气氛是冷的，带着一点萧瑟。","第二句“平明送客楚山孤”：天亮时送客人，楚山孤立。“平明”是天刚亮；“孤”字把山写成了孤独的存在，也像送行人自己。两句从夜到晨，雨到山，时间与景色都在推进。","后两句“洛阳亲友如相问，一片冰心在玉壶”：洛阳的亲友若问起我，就告诉他们，我的心像冰在玉壶里那样纯洁。前面都是景，到这里忽然转为自白。冰心、玉壶两个比喻，都是清澈的东西，表达的是自己经历挫折后仍保持操守。这一联常被读成对仕途遭遇的回应，具体背景存疑。"],"notes":[["寒雨","寒冷的雨"],["连江","雨与江水连成一片"],["入吴","进入吴地"],["平明","天刚亮"],["送客","送别客人"],["楚山","楚地的山"],["孤","孤零零"],["洛阳亲友","洛阳的亲人朋友"],["冰心","像冰一样纯洁的心"],["玉壶","玉制的壶，象征清白"]],"think":["为什么送别诗里要有“自白”？","因为送别时说的话，往往是托付：请替我向故人带话。王昌龄不托付别的，只托付“我还是我”。这在被贬谪的诗人那里很常见：外界怎么评价他，他不辩解，只用冰心玉壶表明态度。"],"quiz":[["“一片冰心在玉壶”表达的是？",["自己清白纯洁的操守","天气寒冷","喜欢收藏玉器","对朋友的惦念"],"冰与玉都是纯洁的象征，用来表明自己的心志。"],["“楚山孤”的“孤”字？",["写山孤立，也映衬送行者的孤独","说明山很高","说明天气不好","说明路难走"],"拟人的写法，使山带上人的情绪。"]],"cards":[["“寒雨连江夜入吴”的下一句？","平明送客楚山孤。"],["《芙蓉楼送辛渐》结句的含义？","借冰心玉壶表明自己仍然清白坚守。"]],"line":["洛阳亲友如相问，一片冰心在玉壶","外派前老领导叮嘱：有人问起你，我就说：洛阳亲友如相问，一片冰心在玉壶。"],"tags":["七绝","送别","王昌龄"]},"tangjin_guiyuan":{"intro":"王昌龄的《闺怨》，写一位少妇在春天登楼，忽然看见杨柳，想起丈夫，后悔让他去求功名。它用最少的笔墨写出了一个心理转折。读它要看“不知愁”与“悔”的落差，只隔一个“忽见”。","focus":["首二句“闺中少妇不知愁，春日凝妆上翠楼”：闺中的少妇不知道愁，春天里精心打扮，登上翠楼。“不知愁”是定位：她年轻、天真，以为春天只是美好。“凝妆”是认真的打扮，为的是登楼赏春。","第三句“忽见陌头杨柳色”：忽然看见路边的杨柳绿了。“忽”是关键：不是她想起，是眼前的景物突然提醒了她。杨柳在唐代是离别的象征，折柳送别是习俗。一个“忽”字，使情绪转折来得很自然。","末句“悔教夫婿觅封侯”：后悔让丈夫去追求功名。前面“不知愁”，这里“悔”，都是一刹那间的变化。她其实一直在期待丈夫立功，而这一刹那，对功名的向往被思念压倒了。一句“悔”字，是全诗的核心。"],"notes":[["闺中","女子居住的内室"],["少妇","年轻的妻子"],["不知愁","不知道忧愁"],["凝妆","精心打扮"],["翠楼","华美的楼"],["忽见","忽然看见"],["陌头","路边"],["杨柳色","杨柳的绿色"],["悔教","后悔让"],["觅封侯","追求封侯的功名"]],"think":["“悔教夫婿觅封侯”的“悔”是真悔吗？","是此刻真实的悔，却未必是长久的悔。诗只截取了一个瞬间：看见杨柳，一时心头一软。这种瞬间的情绪，恰恰是最真实的。如果理解为她根本不想要功名，就把一个瞬间读成了立场。"],"quiz":[["“忽见陌头杨柳色”中“忽”的作用？",["使情绪转折自然、突然","说明时间很快","表示偶然","说明少妇视力好"],"“忽”字是转折的触发：被景物突然触动，从不知愁转为悔。"],["杨柳在唐诗里常象征？",["离别","欢乐","富贵","隐居"],"折柳送别是唐代习俗，“柳”与“留”谐音。"]],"cards":[["“闺中少妇不知愁”的下一句？","春日凝妆上翠楼。"],["《闺怨》的心理转折点？","“忽见陌头杨柳色”，由无忧转为后悔。"]],"line":["忽见陌头杨柳色，悔教夫婿觅封侯","看着朋友圈里刚出差的家人，心里软了一下：忽见陌头杨柳色，悔教夫婿觅封侯。"],"tags":["七绝","闺怨","王昌龄"]},"tangjin_liangzhou":{"intro":"王翰的《凉州词》，写的是边塞将士的酒宴。葡萄美酒，夜光杯，琵琶催饮，却在醉卧沙场处转入苍凉。末句“古来征战几人回”读成豪放还是悲怆，历来有两种读法，没有定论。读它要看两种读法怎样同时成立。","focus":["首二句“葡萄美酒夜光杯，欲饮琵琶马上催”：葡萄酒盛在夜光杯里，刚要喝，琵琶声在马上催着。前一句写色彩与器物的华美，后一句写音乐的催促。节奏很快，像一场战前的宴饮，没有人想等。","第三句“醉卧沙场君莫笑”：醉倒在沙场上，请不要笑话。这是自嘲，也是辩解：不是不守军纪，是知道自己的处境。“君”字像对一个看客说话。","末句“古来征战几人回”：自古以来，出征的人有几个回来？有两种读法：一是豪放，生死看淡，所以尽情醉；二是悲怆，明知回不来，所以更要醉。诗没有解释，两种情绪同在，才让这一句有力。"],"notes":[["葡萄美酒","葡萄酿的酒"],["夜光杯","精美的玉杯"],["欲饮","将要饮"],["琵琶","弹拨乐器"],["马上","在马背上"],["催","催促"],["醉卧","醉倒躺下"],["沙场","战场"],["君","你"],["征战","出征作战"]],"think":["“古来征战几人回”究竟是豪还是悲？","两种读法都有依据：把重点放在“醉卧沙场君莫笑”的洒脱，就偏豪；放在“几人回”的数字，就偏悲。比较稳妥的读法是承认两者并存：因为明白生死，所以醉得更彻底，豪与悲在这里是同一件事的两面。"],"quiz":[["“欲饮琵琶马上催”的画面是？",["酒宴上琵琶声催促饮酒","骑马奏琵琶","酒宴被打断","琵琶声悲伤"],"琵琶在马上弹，声音催人尽快饮酒，带着边塞的急促。"],["末句“古来征战几人回”的特点？",["可读作豪放也可读作悲怆","明确表示反战","明确表示歌颂战争","描写战场地理"],"诗没有说明态度，两种解读都成立。"]],"cards":[["“葡萄美酒夜光杯”的下一句？","欲饮琵琶马上催。"],["《凉州词》结句为什么有争议？","可读作豪放，也可读作悲怆，两者并存。"]],"line":["醉卧沙场君莫笑，古来征战几人回","大项目交付前夜，团队喝了一场庆功酒，有人笑着说：醉卧沙场君莫笑。"],"tags":["七绝","边塞","王翰"]},"tangjin_guangling":{"intro":"李白送孟浩然去广陵（今扬州），在黄鹤楼边分别。四句诗，前两句交代时间地点，后两句只写一艘船消失的过程。读它要看诗人怎样用目光送行：孤帆变远影，远影入碧空，最后只有长江。","focus":["首二句“故人西辞黄鹤楼，烟花三月下扬州”：老朋友从黄鹤楼向西告辞，在烟花三月顺江而下扬州。“烟花三月”是春天的繁华，烟指烟雾，花指繁花，既是景，也是对朋友去处的祝福。","第三句“孤帆远影碧空尽”：孤独的帆影在碧空尽头消失。“孤”“远”“尽”三个字，写出目光的追随：先是帆，再是影，最后消失。这一句是视觉上的动态过程。","末句“惟见长江天际流”：只看见长江流向天边。人不见了，江还在。诗人没有写“我很舍不得”，却把全部情意放在“惟见”二字里：他一直站在那里，直到最后只剩下江水。"],"notes":[["故人","老朋友"],["西辞","向西告别"],["黄鹤楼","在武昌，临长江"],["烟花","指春日繁花如烟"],["三月","农历三月"],["下扬州","顺江而下去扬州"],["孤帆","孤独的船帆"],["远影","远去的影子"],["碧空尽","在碧空尽头消失"],["天际","天边"]],"think":["为什么说这首诗的送别是“看”出来的？","因为后两句完全是视线的移动：帆、影、空、江。诗人不说自己的心情，却让读者感到他站了很久，一直目送到看不见。感情被隐藏在“还在看”的动作里，这是含蓄的力量。"],"quiz":[["“惟见长江天际流”的“惟”字？",["表示只剩下江水，人已消失","表示唯一","表示思念","表示强调长江"],"“惟见”说明帆影已消失，只剩江水，写目送之久。"],["“烟花三月”的含意？",["春日繁华的景象","一种烟花表演","三月的节日","指某种花"],"“烟花”是春景如烟如花，也是对远行的朋友的美好祝愿。"]],"cards":[["“故人西辞黄鹤楼”的下一句？","烟花三月下扬州。"],["《送孟浩然之广陵》结尾的含蓄之处？","不写感情，只写目送到只剩江流。"]],"line":["孤帆远影碧空尽，惟见长江天际流","在机场看着朋友走进安检，直到看不见他：孤帆远影碧空尽，惟见长江天际流。"],"tags":["七绝","送别","李白"]},"tangjin_xiajiangling":{"intro":"李白的《下江陵》，一般认为是遇赦东归时作（具体年份存疑）。白帝城到江陵，长江顺流而下，千里一日。它的特点是“快”：句子快，节奏快，意象快。读它要看四句诗如何做到从彩云到万重山一气呵成。","focus":["首句“朝辞白帝彩云间”：早上告别白帝城，城在彩云之间。白帝城地势高，常在云雾间，“彩云”既是实景，也是心情：轻盈明亮。","第二句“千里江陵一日还”：千里之外的江陵，一天就能回到。“千里”与“一日”是数字的强烈对比：长度极大，时间极短，把速度写到极致。","后两句“两岸猿声啼不住，轻舟已过万重山”：两岸的猿声不停地叫，轻舟已经穿过了万重山。猿声本是悲声，这里被舟速甩在后面，来不及悲。“轻”字最妙：舟本不轻，因为心情轻，舟也显得轻。从“千里”“一日”到“万重山”，速度、距离、心情都在这四句中加速。"],"notes":[["白帝","白帝城，在今重庆奉节"],["彩云间","彩云之间"],["千里","极远的距离"],["江陵","今湖北荆州"],["一日还","一天就回到"],["两岸","江的两岸"],["猿声","猿猴的叫声"],["啼不住","啼叫不停"],["轻舟","轻快的小船"],["万重山","层层叠叠的山"]],"think":["“轻舟已过万重山”中“轻”是客观还是主观？","客观上，顺流而下的船确实快；主观上，诗人心情畅快，觉得舟也轻。这类“轻”字，是情绪在物上的投射。读这首诗，不妨把它当成一个人从压抑中被释放的瞬间。"],"quiz":[["“千里江陵一日还”的写法？",["以数字对比写速度","描写风景","描写路程","描写城市"],"千里与一日的对比，突出行舟的快。"],["“两岸猿声啼不住”的作用？",["以不停的猿声衬出舟速快","表现悲伤","描写自然","渲染孤寂"],"猿声本悲，这里却被舟速抛在身后，反衬出心情的轻快。"]],"cards":[["“朝辞白帝彩云间”的下一句？","千里江陵一日还。"],["《下江陵》的核心感觉？","快：速度、节奏与心情同时加速。"]],"line":["两岸猿声啼不住，轻舟已过万重山","一个压了几个月的项目终于结项，走出办公室：两岸猿声啼不住，轻舟已过万重山。"],"tags":["七绝","行旅","李白"]},"tangjin_rujing":{"intro":"岑参去西域途中，在马上遇见回京城的使者，没有纸笔，只能托口信。这首《逢入京使》以极日常的场景写出了行役者的思乡。读它要看“双袖龙钟泪不干”的动作，和“报平安”这三个字的重量。","focus":["首二句“故园东望路漫漫，双袖龙钟泪不干”：向东望故乡，路漫漫无边；两只衣袖被泪水沾湿，还没干。“龙钟”形容衣袖沾湿的样子。回望故乡的“东”是方向，诗人在西行，每走一步，离家更远。","第三句“马上相逢无纸笔”：马上相逢，没有纸笔。这是一个具体而尴尬的处境：想写封信，却手边什么都没有。这种“来不及”的感觉，比任何形容都真实。","末句“凭君传语报平安”：请你捎一句话，报个平安。“平安”是最小的愿望，也是最大的牵挂。他要说的话很多，却只能压缩成这两个字。诗人没写“思念”，却把思念放进了“凭”字里：只能托你。"],"notes":[["故园","故乡"],["东望","向东望"],["路漫漫","路途遥远"],["双袖","两只衣袖"],["龙钟","沾湿的样子"],["泪不干","眼泪没有干"],["马上","在马背上"],["无纸笔","没有纸和笔"],["凭君","托你"],["传语","带话"],["报平安","报告平安"]],"think":["为什么只说“报平安”，而不说其他话？","在紧急且条件有限的场合，人会把话压缩到最必要的那一条。“平安”对家人最重要，也是行役者最不能多说的：多说就是诉苦。这种简短，反而让人觉得话里有更多没说。"],"quiz":[["“双袖龙钟泪不干”的“龙钟”？",["形容衣袖沾湿","形容人老","形容钟声","形容路长"],"此处是沾湿的样子，写泪水沾湿衣袖。"],["“凭君传语报平安”的情感？",["把牵挂压缩成最简的口信","要求对方多说话","埋怨使者","谈论政事"],"因无纸笔，只能口头带话，平安二字承载全部牵挂。"]],"cards":[["“故园东望路漫漫”的下一句？","双袖龙钟泪不干。"],["《逢入京使》的特点？","以偶遇和口信写思乡，朴素真挚。"]],"line":["马上相逢无纸笔，凭君传语报平安","在机场匆匆遇到回国的同事，只来得及说：马上相逢无纸笔，凭君传语报平安。"],"tags":["七绝","思乡","岑参"]},"tangjin_jiangnan":{"intro":"杜甫晚年漂泊江南，遇到当年的著名乐师李龟年。这首诗只有四句，写的是一次重逢，却把开元盛世到安史之乱后的世变压在里面。读它要看前两句的“旧日”与后两句的“今时”，以及“落花时节”的双重含义。","focus":["首二句“岐王宅里寻常见，崔九堂前几度闻”：在岐王的宅子里常常见到，在崔九的厅堂前多次听过。岐王、崔九都是玄宗时期的权贵，诗人通过这些名字交代了当年的盛世场景，“寻常”“几度”是在说那时候常见，现在却成了难得。","第三句“正是江南好风景”：此时正是江南的好风景。表面是赞美，实际是反衬：好风景之下，是流落江湖的两个人。","末句“落花时节又逢君”：在落花时节又遇见你。“落花”既是暮春实景，又暗喻盛世的凋零与人的衰老。一个“又”字，把过去与现在连起来：当年在宫廷权贵之家，现在在江南的落花之中。诗不写感慨，却全是感慨。"],"notes":[["岐王","唐玄宗之弟李范"],["寻常见","常常见到"],["崔九","崔涤，唐玄宗时的宠臣"],["几度闻","多次听到"],["江南","长江以南一带"],["好风景","美好的景色"],["落花","凋落的花"],["时节","时令"],["又逢君","又遇见你"],["堂前","厅堂前"]],"think":["“落花时节又逢君”为什么被认为是千古名句？","因为它的字面很平，意思却很多：落花是实景，又喻盛世已逝，也喻两人暮年。“又”字更重要：两次相逢，隔了几十年。杜甫没有任何抱怨，只是把时间交给了一个季节，所以越读越觉得重。"],"quiz":[["首二句列出岐王、崔九的作用？",["交代当年的盛世与身份","批评权贵","描写住宅","说明李龟年住在哪里"],"岐王、崔九是玄宗时期的权贵，借此写出当年盛世的场景。"],["“落花时节”的双重含义是？",["暮春实景，也喻盛世与人生凋零","只是春天","只是花开","只是秋天"],"实指暮春，虚指一个时代和个人的衰落。"]],"cards":[["“岐王宅里寻常见”的下一句？","崔九堂前几度闻。"],["《江南逢李龟年》的主题？","借重逢写盛世的消逝与人生的沧桑。"]],"line":["正是江南好风景，落花时节又逢君","多年后在异地遇到当年的老领导，只说一句：正是江南好风景，落花时节又逢君。"],"tags":["七绝","重逢","杜甫"]},"tangjin_chuzhou":{"intro":"韦应物任滁州刺史时，作《滁州西涧》。写的是涧边的幽草、深树的黄鹂、晚来的春潮和无人的野渡。画面干净，意象清淡。但后人也常读出其中的寓意：谁在涧边，谁在高处，谁是无人乘的船？读它要看这些读法如何都只是读法。","focus":["首二句“独怜幽草涧边生，上有黄鹂深树鸣”：我独独怜爱涧边生长的幽草，上面深树里有黄鹂鸣叫。“独怜”是偏爱，对象是不起眼的草；“上有黄鹂”是对照：一低一高，一静一动。","第三句“春潮带雨晚来急”：春天的潮水带着雨，傍晚来得急。前两句是静的草与树，这一句忽然转为动：潮急，雨来，整个画面的氛围随之一变。","末句“野渡无人舟自横”：野外的渡口没有人，船自己横在水面。这是全诗的定格：空、静，还有一种自在。“自横”二字很妙：船本无人，却像自己选择了姿势。这一句有时被读成“怀才不遇”“闲适”或“无为”，诗里没有任何说明，所以都只是读者的解释。"],"notes":[["独怜","唯独喜爱"],["幽草","幽静处的草"],["涧边","山涧边"],["黄鹂","黄莺鸟"],["深树","茂密的树"],["春潮","春天上涨的潮水"],["带雨","带着雨"],["晚来急","傍晚来得急"],["野渡","野外的渡口"],["自横","自己横在水上"]],"think":["“野渡无人舟自横”是在写闲适还是失意？","两种读法都可以：把“自横”读成自在，是闲适；把“无人”读成没人用，是失意。真正有分量的是承认这个歧义：诗人没有告诉我们答案，才使这一句常读常新。读者可以选自己的读法，但要意识到那是选择。"],"quiz":[["“独怜幽草涧边生”的“独怜”表现？",["偏爱不起眼的小草","同情小草","怜悯涧水","怜悯黄鹂"],"“独”是唯独，“怜”是爱惜，诗人偏爱静处的幽草。"],["“野渡无人舟自横”的特点是？",["留白，可有多种解读","明确表示讽刺","描写热闹","写实"],"画面静止而有余味，没有给出结论。"]],"cards":[["“独怜幽草涧边生”的下一句？","上有黄鹂深树鸣。"],["《滁州西涧》为什么常读常新？","结尾画面留白，可读为闲适、失意或自在。"]],"line":["春潮带雨晚来急，野渡无人舟自横","下班后的空办公室只开着一盏灯：春潮带雨晚来急，野渡无人舟自横。"],"tags":["七绝","山水","韦应物"]},"tangjin_fengqiao":{"intro":"张继的《枫桥夜泊》，写的是一个落第或失意的夜晚（具体背景存疑），在苏州城外的枫桥边泊舟。诗里有月落、乌啼、霜、江枫、渔火、寒山寺的钟声，全是听觉与视觉的碎片，却拼成了一个失眠的夜。读它要看这些意象怎样被一个“愁”字串起来。","focus":["首句“月落乌啼霜满天”：月亮落了，乌鸦啼叫，霜气满天。三件事：月、乌、霜，是同一个深夜的三个信号。“霜满天”不是真有霜，是寒意弥漫的感觉。","第二句“江枫渔火对愁眠”：江边的枫树、渔船上的灯火，对着愁眠的人。“对”字是全诗的关键：景物与人相对，景是静，人是愁。有人对“愁眠”二字有不同断句，这一点无定论，不影响整体。","后两句“姑苏城外寒山寺，夜半钟声到客船”：苏州城外寒山寺，夜半的钟声传到客船。钟声是全诗最后的、最远的一个意象，由远到近：从城外到船上。北宋有人曾质疑夜半不撞钟，但诗不是在记录寺规，是在写一个失眠者所听到的声音。"],"notes":[["月落","月亮落下"],["乌啼","乌鸦啼叫"],["霜满天","霜气充满天空"],["江枫","江边的枫树"],["渔火","渔船上的灯火"],["愁眠","带着愁绪睡去或睡不着"],["姑苏","苏州的别称"],["寒山寺","苏州城外的寺庙"],["夜半","半夜"],["客船","旅人的船"]],"think":["“夜半钟声”是否合乎史实，会影响这首诗吗？","北宋曾有人质疑，后人也有不少考证，说法不一。但对读诗而言，重要的是：诗人是否真的听见这个声音。一个失眠的人，听到远处的钟声，就是真实。纠结“夜半钟”的存在，反而容易忘记诗在写什么。"],"quiz":[["“江枫渔火对愁眠”的“对”字？",["景物与愁人相对，营造孤寂","对仗","相对而坐","对比"],"景是静的，人是愁的，“对”字把二者放在一个画面里。"],["结句“夜半钟声到客船”的作用？",["以远声作收，加深寂静","描写寺庙","说明时间","赞美寺院"],"钟声越远越清晰，反衬夜之静与人之孤。"]],"cards":[["“月落乌啼霜满天”的下一句？","江枫渔火对愁眠。"],["《枫桥夜泊》的意象组合？","月、乌、霜、枫、火、钟，以愁字串起。"]],"line":["姑苏城外寒山寺，夜半钟声到客船","半夜在高铁站等车，听着广播：姑苏城外寒山寺，夜半钟声到客船。"],"tags":["七绝","羁旅","张继"]},"tangjin_hanshi":{"intro":"韩翃的《寒食》，写的是唐代寒食节：这一天民间禁火，官府却在傍晚把新火赐给权贵之家。诗里表面写的是长安的春景，实际暗含对权贵特权的冷淡讽刺。读它要看“汉宫”二字，如何成为借汉写唐的遮挡。","focus":["首二句“春城无处不飞花，寒食东风御柳斜”：春天的长安城到处飞花，寒食节的东风把宫苑里的柳枝吹斜。“无处不”是普遍的繁盛，“御柳”点明皇家之地。这两句写的是节日的美，没有任何议论。","第三句“日暮汉宫传蜡烛”：傍晚时，汉朝宫里传送蜡烛。唐代人常以“汉”指唐，用“汉宫”是避讳，也是借古喻今。寒食节本应禁火，宫中却传递新烛，这是一个小细节，也是特权。","末句“轻烟散入五侯家”：袅袅的轻烟飘散进了五侯的家。“五侯”原指汉成帝时同日封侯的五位外戚，这里泛指受宠的权贵。“轻烟”是一种看似无意的写法：蜡烛的烟飘进他们家，也是赐火的画面。全诗不骂一个字，却让人感到火只给了那些人。"],"notes":[["春城","春天的城，指长安"],["飞花","飘飞的花"],["寒食","寒食节，禁火的节日"],["东风","春风"],["御柳","皇家园林的柳"],["斜","倾斜"],["日暮","傍晚"],["汉宫","借指唐朝宫廷"],["传蜡烛","传送赐给的新火"],["五侯","汉代同时封侯的五位外戚，泛指权贵"]],"think":["这首诗是赞美还是讽刺？","表面是一幅节日的宫廷春景，读不出批评；但寒食本应禁火，宫中却传蜡烛并把火送入权贵家，这种“特权”被写得自然。讽刺的力量来自不说破。至于是否特指某个具体权贵，史料不足，存疑。"],"quiz":[["“汉宫”在诗中指？",["借汉指唐，既避讳又喻今","汉代的宫殿","一座寺庙","长安的某座楼"],"唐人常以汉写唐，既是避讳，也有借古讽今的效果。"],["“轻烟散入五侯家”的含意？",["只有权贵得到赐火","蜡烛很美","烟雾很轻","五侯在做饭"],"寒食禁火，赐火只给权贵，轻烟入五侯家暗含不平等。"]],"cards":[["“春城无处不飞花”的下一句？","寒食东风御柳斜。"],["《寒食》如何讽刺？","借汉喻唐，写权贵得赐新火，不直说批评。"]],"line":["日暮汉宫传蜡烛，轻烟散入五侯家","看到某些资源只流向特定圈子，不好直说，只念：日暮汉宫传蜡烛，轻烟散入五侯家。"],"tags":["七绝","讽喻","韩翃"]},"tangjin_shoujiang":{"intro":"李益的《夜上受降城闻笛》，写的是边塞的月夜，士兵听到不知何处传来的芦管声，一夜之间都在向着家乡的方向张望。读它要看视觉（沙如雪、月如霜）与听觉（芦管）怎样合写出一种集体的乡愁。","focus":["首二句“回乐峰前沙似雪，受降城外月如霜”：回乐峰前的沙像雪，受降城外的月像霜。两个比喻都用“冷”：沙是白的，像雪；月是清的，像霜。地点在边塞，但没有写风沙，写的是寒。","第三句“不知何处吹芦管”：不知道什么地方吹起了芦管。“不知何处”是关键：声音飘在空中，没有来源，像是整个夜晚在吹。","末句“一夜征人尽望乡”：一夜之间，所有的征人都在望着故乡。“一夜”“尽”两个词，把个人的乡愁扩展成集体；“望乡”是动作，没有写哭，也没有写说话，只是望。前面的冷，是为这个“望”做的铺垫。"],"notes":[["回乐峰","受降城附近的山峰"],["沙似雪","沙地像雪一样白"],["受降城","唐代为防御边塞所筑的城"],["月如霜","月光像霜一样清冷"],["不知何处","不知道在哪里"],["芦管","芦苇做的管乐器"],["一夜","整夜"],["征人","出征的士兵"],["尽","全都"],["望乡","眺望故乡"]],"think":["为什么不直接写“听到笛声思乡”？","因为那样是直接叙述；诗人先用冷的景物铺垫，再用无来源的声音，最后才让所有人望乡。顺序是：环境—声音—动作。感情不是被说出来的，是被环境逼出来的。"],"quiz":[["“沙似雪”“月如霜”的共同点？",["以冷色写边塞的寒清","写景物丰富","写雪景","写天气变化"],"沙与月本非雪霜，却以雪霜作比，都带着寒与白，营造出清冷的氛围。"],["“一夜征人尽望乡”的效果？",["把个人乡愁扩展为集体","说明士兵很多","描写夜色","表现军纪严明"],"“尽”字使全体征人都被笛声触动，情感集体化。"]],"cards":[["“回乐峰前沙似雪”的下一句？","受降城外月如霜。"],["《夜上受降城闻笛》的构成？","先景后声再人，环境铺垫出集体乡愁。"]],"line":["不知何处吹芦管，一夜征人尽望乡","春节前夜，整个出差团队都在酒店走廊望着窗外：不知何处吹芦管，一夜征人尽望乡。"],"tags":["七绝","边塞","李益"]},"tangjin_wuyi":{"intro":"刘禹锡的《乌衣巷》，乌衣巷在金陵（今南京）秦淮河边，东晋时王导、谢安两大世家的住地。诗人到的时候，已是唐代，巷子里是寻常百姓。读它要看四句话里没有一个字说“衰败”，却把兴亡写尽。","focus":["首二句“朱雀桥边野草花，乌衣巷口夕阳斜”：朱雀桥边长满野草野花，乌衣巷口夕阳斜照。朱雀桥是当年繁华的大道，现在野草丛生；乌衣巷是权贵所居，现在只有夕阳。一“野”一“斜”，已把今昔对比放进画面。","第三句“旧时王谢堂前燕”：从前王家、谢家厅堂前的燕子。燕子是候鸟，每年归来，是历史的见证者。诗人不写人，只写燕子，把人事转为自然。","末句“飞入寻常百姓家”：现在飞入普通人家。“寻常”二字点睛：王谢变成寻常。这一句是因果的反转：燕子没有变，变的是它落脚的地方。全诗没有一句议论，兴亡被藏在一只燕子的飞行轨迹里。"],"notes":[["朱雀桥","秦淮河上的桥"],["野草花","野草野花"],["乌衣巷","金陵地名，东晋王谢所居"],["夕阳斜","夕阳西斜"],["旧时","从前"],["王谢","东晋的王导、谢安两大世家"],["堂前","厅堂前"],["燕","燕子"],["寻常","普通的"],["百姓家","平民人家"]],"think":["“旧时王谢堂前燕”是不是说燕子认得老屋？","诗没有这么说。燕子是否“认得”是想象，诗人的做法是把燕子当作历史的线索：它每年回来，却发现主人换了。这种想象把抽象的兴亡变成了一个可视的画面，但诗里也没有证明“燕子是同一批”，这是诗的修辞。"],"quiz":[["“飞入寻常百姓家”表达的是？",["昔日贵族不再，平民取而代之","燕子找不到家","燕子喜欢百姓","百姓很富有"],"燕子飞入平民家，暗示王谢已衰，世事变迁。"],["诗中没有出现的是？",["直接的议论","夕阳","野草","燕子"],"全诗不发议论，通过景物写兴亡。"]],"cards":[["“朱雀桥边野草花”的下一句？","乌衣巷口夕阳斜。"],["《乌衣巷》以什么写兴亡？","以一只燕子的去向，不发议论。"]],"line":["旧时王谢堂前燕，飞入寻常百姓家","参观老牌企业的旧址已变成创业园：旧时王谢堂前燕，飞入寻常百姓家。"],"tags":["七绝","怀古","刘禹锡"]},"tangjin_jinling":{"intro":"张祜的《题金陵渡》，金陵渡一般指今镇江一带的渡口，说法不一。诗人夜宿渡口边的小山楼，看到潮落、斜月、江上星火，写成这首小诗。读它要看“自可愁”如何以一个“自”字，让愁带了点自嘲。","focus":["首二句“金陵津渡小山楼，一宿行人自可愁”：金陵的渡口，小山楼上，住宿一夜的旅人自然会愁。“自可愁”的“自”是自然，也有自我：旅人本该愁，不必有人来劝，也不必有理由。这是一种随遇而安的无奈。","第三句“潮落夜江斜月里”：夜里江潮退落，斜月照在江上。潮落、斜月，合成一幅静而淡的画面，带着一点凄清，也是旅人夜不能寐时所见。","末句“两三星火是瓜州”：江对岸闪着两三点星火，那就是瓜洲。远处是一两点灯，却被认出来是瓜洲，这是行人地理上的定位，也是心理上的一点慰藉：对岸有人家。“两三”“星火”的量词很小，却把距离感写得很准。"],"notes":[["津渡","渡口"],["小山楼","小山上的楼"],["一宿","住一夜"],["行人","旅人"],["自可愁","自然会愁"],["潮落","潮水退落"],["夜江","夜里的江"],["斜月","西斜的月亮"],["两三","两三个"],["星火","星星般的灯火"],["瓜州","瓜洲，在长江北岸"]],"think":["“两三星火是瓜州”为什么是好的结尾？","因为它不抒情，只做辨认：远处有灯，那是对岸。人在愁中，仍在辨认世界，这是一种倔强的清醒。也可以说，灯火给了旅人一点安慰：不是没有人，只是离得远。"],"quiz":[["“一宿行人自可愁”的“自”？",["自然，不需理由","自己","自从","自由"],"“自可愁”是理所当然会愁，带点无奈。"],["末句的作用？",["以远方灯火收束，给孤寂一点慰藉","点明时间","描写战争","描写江潮"],"星火是对岸的人家，写出了远与近、孤与不孤。"]],"cards":[["“金陵津渡小山楼”的下一句？","一宿行人自可愁。"],["《题金陵渡》的结尾特点？","以星火辨认瓜洲，愁中带慰藉。"]],"line":["潮落夜江斜月里，两三星火是瓜州","夜里在高速服务区看远处的灯火：潮落夜江斜月里，两三星火是瓜州。"],"tags":["七绝","羁旅","张祜"]},"tangjin_jinshi":{"intro":"朱庆馀的《近试上张水部》，是一首干谒诗。朱庆馀要参加科举，写给水部员外郎张籍，想问他自己的文章能否被主考官看中。诗里不说科举，写的是新娘早起、梳妆、问夫婿“画眉深浅入时无”。读它要看这个比喻怎样把求问变成一个温柔的画面。","focus":["首二句“洞房昨夜停红烛，待晓堂前拜舅姑”：洞房里昨夜的红烛烧到天亮，新娘等到天亮要到堂前拜见公婆。“停红烛”是新婚夜，“拜舅姑”是第二天的礼节，紧张、郑重，是新娘此刻的处境，也暗指考生即将面对考官。","第三句“妆罢低声问夫婿”：妆化好了，低声问丈夫。“低声”写出新娘的羞怯与在意，不是随便一问。“夫婿”暗指张籍：诗人把对方放在最信任的人的位置。","末句“画眉深浅入时无”：眉画得深浅，合不合时尚？“入时”既指妆扮合流行，也暗指文章合不合主考官的口味。一个简单的问句，把科举的焦虑变成日常的小事，这是比喻的巧处，也是一种得体的求教方式。"],"notes":[["洞房","新婚的房间"],["停红烛","红烛燃到天亮"],["待晓","等到天亮"],["堂前","厅堂前"],["拜","参拜"],["舅姑","公婆"],["妆罢","梳妆完毕"],["低声","声音放低"],["夫婿","丈夫"],["画眉","描眉"],["入时","合乎时尚"]],"think":["为什么干谒诗要用比喻，而不直接说“请看我的文章”？","直接说，显得急切；用比喻，既表达了求问之意，又给对方留了回应的空间。更重要的是，比喻把一次求助变成了一个有趣的场景，既体面，也有诗意。这类写法反映了唐代文人交往中的分寸。"],"quiz":[["“画眉深浅入时无”的比喻义？",["自己的文章是否合主考官的口味","化妆技巧","新娘的美丑","夫婿的喜好"],"“入时”暗指文章合不合时宜，是向张籍求教的委婉表达。"],["“待晓堂前拜舅姑”在全诗的作用？",["交代场景，暗示即将面对考官","描写婚礼","说明夫婿家境","表示新娘孝顺"],"拜见公婆是新娘的关口，对应考生即将面对主考官。"]],"cards":[["“洞房昨夜停红烛”的下一句？","待晓堂前拜舅姑。"],["《近试上张水部》的写法？","以新娘问夫婿喻考生求教，委婉得体。"]],"line":["妆罢低声问夫婿，画眉深浅入时无","发布前把方案草稿递给前辈，附一句：妆罢低声问夫婿，画眉深浅入时无。"],"tags":["七绝","干谒","朱庆馀"]},"tangjin_chibi":{"intro":"杜牧的《赤壁》是咏史诗中“翻案”的典型。他在赤壁古战场捡到一支断戟，磨洗之后认出是三国时的旧物，随之想到：若不是东风帮了周瑜，二乔早被曹操锁进铜雀台。读它要看这首诗怎样用一个假设，把大历史说成一个偶然。","focus":["首二句“折戟沈沙铁未销，自将磨洗认前朝”：断戟沉在沙里，铁还没有锈完；我自己拿来磨洗，认出是前朝的东西。“沈”“销”写出时间的长，“自将磨洗”是动作，是诗人亲自动手触摸历史，使怀古有了具体的实物。","第三句“东风不与周郎便”：东风若不给周瑜方便。这里省略了赤壁之战“借东风”火攻曹军的情节，把胜负归于东风，而不是人。这是翻案的开端。","末句“铜雀春深锁二乔”：那么铜雀台的春天深处，锁住的就是二乔。铜雀台是曹操所建，二乔是江东美女，诗人以女子的命运反衬战争的胜负。有人批评杜牧写得轻佻，把国运落在妇人身上；也有人认为这是以小见大的巧笔。这两种读法都有依据。"],"notes":[["折戟","断了的戟"],["沈沙","沉在沙里"],["铁未销","铁还没有销蚀"],["磨洗","磨擦洗涤"],["认前朝","认出是前朝之物"],["东风","指赤壁之战的东风"],["周郎","周瑜"],["便","方便，有利"],["铜雀","铜雀台，曹操所建"],["二乔","大乔与小乔"]],"think":["杜牧这种“翻案”写法有什么利弊？","好处是出人意料，把大事说成偶然，使人对历史产生新的思考；弊端是容易轻巧，把严肃的战争归为“假如”，缺少对史实的敬意。读这类诗，既要欣赏其巧，也要保持警惕：诗里的“假如”不是证据。"],"quiz":[["“东风不与周郎便”的意思是？",["如果东风不帮周瑜","东风很大","周瑜讨厌东风","东风很便利"],"“不与便”是不给方便，假设没有东风，周瑜无法火攻。"],["“铜雀春深锁二乔”的含意？",["假设曹操获胜，二乔会被锁入铜雀台","二乔住在铜雀台","铜雀台很美","春天来了"],"这是以假设的结局反衬赤壁之战胜负的偶然。"]],"cards":[["“折戟沈沙铁未销”的下一句？","自将磨洗认前朝。"],["《赤壁》的写法特点？","以假设翻案，把胜负归于东风，以二乔反衬。"]],"line":["东风不与周郎便，铜雀春深锁二乔","复盘一次差点失败的项目：东风不与周郎便，铜雀春深锁二乔——运气比计划重要。"],"tags":["七绝","咏史","杜牧"]},"tangjin_qinhuai":{"intro":"杜牧的《泊秦淮》，夜里在秦淮河边停泊，听到酒家的歌声，想起陈后主以《玉树后庭花》亡国的故事。诗里的讽刺不落在歌女，而落在听歌的人与时代。读它要看“商女”“亡国恨”“后庭花”三个词怎样串成一条线。","focus":["首二句“烟笼寒水月笼沙，夜泊秦淮近酒家”：烟雾笼着寒水，月光笼着沙洲；夜晚停泊在秦淮河边，靠近酒家。“笼”字用了两次，一个是烟，一个是月，使画面朦胧，也预示着后面的醉生梦死。","第三句“商女不知亡国恨”：歌女不知道亡国的遗恨。这句话常被误读为批评歌女，其实歌女只是唱歌的人，她们唱什么，是听众点的。真正“不知”的，是点歌的人。","末句“隔江犹唱后庭花”：隔着江还在唱《后庭花》。《玉树后庭花》是陈后主所作，后世视为亡国之音。“隔江”可以指对岸是北方，也可以指时间上的远。“犹”字是关键：亡国已久，歌仍在唱。诗人借此表达对晚唐时局的忧虑。"],"notes":[["烟笼","烟雾笼罩"],["寒水","寒冷的水"],["月笼沙","月光笼罩沙洲"],["秦淮","秦淮河"],["酒家","酒店"],["商女","歌女"],["亡国恨","亡国的遗恨"],["隔江","隔着江"],["犹唱","还在唱"],["后庭花","陈后主所作《玉树后庭花》"]],"think":["“商女不知亡国恨”是批评歌女吗？","字面是，但稍稍细想就知道：歌女靠唱曲为生，唱什么由客人决定。更合理的读法是：诗人借歌女之口，批评那些不知忧患、只图享乐的权贵与听众。把锋芒指向歌女，是对这句话的常见误读。"],"quiz":[["“商女不知亡国恨”的真正批评对象是？",["沉迷享乐的听众","歌女","陈后主","酒家主人"],"歌女是替听众唱曲，真正不知忧患的是点歌的人。"],["“烟笼寒水月笼沙”的作用？",["营造朦胧气氛，铺垫醉生梦死","描写战争","描写天气","描写船"],"重复的“笼”字使画面如梦，与后面的歌声构成对照。"]],"cards":[["“烟笼寒水月笼沙”的下一句？","夜泊秦淮近酒家。"],["《泊秦淮》的讽刺对象？","不是歌女，而是不知忧患的享乐者。"]],"line":["商女不知亡国恨，隔江犹唱后庭花","看到行业遇到寒冬，有人还在晒豪华办公室：商女不知亡国恨，隔江犹唱后庭花。"],"tags":["七绝","咏史","杜牧"]},"tangjin_yangzhou":{"intro":"杜牧的《寄扬州韩绰判官》，寄给在扬州做判官的朋友韩绰。他回忆扬州旧游，想象秋夜里的二十四桥、明月、吹箫的人。读它要看前两句的江南秋色与后两句的扬州夜景，怎样合成一封带着调侃的问候。","focus":["首二句“青山隐隐水迢迢，秋尽江南草未凋”：青山隐约，江水遥远；秋天快过去了，江南的草还没有凋谢。“隐隐”与“迢迢”是远景的叠加；“草未凋”是江南的特色，不同于北方的萧瑟。","第三句“二十四桥明月夜”：二十四桥在月夜。二十四桥一般指扬州的桥，也有说是一座桥，名称之争并无定论。重点是“明月夜”：这是杜牧心里的扬州，一个夜晚的扬州。","末句“玉人何处教吹箫”：美人在何处教人吹箫？“玉人”有两种读法：一指美女，一指友人韩绰（用“玉人”称男子也有先例）。这一问带有调侃，既是问朋友在做什么，也是怀念当年的旧游。诗里没有答案，这种问而不答的收尾，很有杜牧的风流。"],"notes":[["隐隐","隐约"],["水迢迢","江水遥远"],["秋尽","秋天将尽"],["草未凋","草还没有凋谢"],["二十四桥","扬州的桥名，一说二十四座桥"],["明月夜","明月之夜"],["玉人","美人，也可指友人"],["何处","在哪里"],["教","指导"],["吹箫","吹奏箫"]],"think":["“玉人”是女子还是韩绰？","两种读法都有依据，不能确定。若读为女子，这是对扬州风月的回忆；若读为韩绰，这是对朋友的调侃：你在做什么呢？诗人在这里故意不说清，使这句话带上一点玩笑的口气，这也是朋友之间寄诗的分寸。"],"quiz":[["“秋尽江南草未凋”写出了？",["江南气候温和的特色","秋天的萧瑟","草很稀少","秋天已经结束"],"江南秋末草未凋，与北方对比，也使诗带上暖意。"],["末句“玉人何处教吹箫”的特点？",["以问收尾，带调侃","直接陈述","描写景物","表示感谢"],"用问句结尾，既回忆又调侃，不求回答。"]],"cards":[["“青山隐隐水迢迢”的下一句？","秋尽江南草未凋。"],["《寄扬州韩绰判官》的语气？","带有调侃的怀念，以问收尾。"]],"line":["二十四桥明月夜，玉人何处教吹箫","给在外地的老友发消息：二十四桥明月夜，玉人何处教吹箫——今晚在哪儿喝酒呢。"],"tags":["七绝","寄友","杜牧"]},"tangjin_qianhuai":{"intro":"杜牧的《遣怀》，是一首对往事的回望。诗人回想自己在江湖间载酒而行、在扬州放浪的日子，最后说：十年一觉扬州梦，只落得个“青楼薄幸”的名声。读它要看自嘲里带着的悔与不悔。","focus":["首二句“落魄江湖载酒行，楚腰纤细掌中轻”：落魄时在江湖间载着酒行走，楚地美人的腰细得像可以掌中托起。“落魄”是处境，“载酒行”是态度，“掌中轻”是过往的风流。三者放在一起，是一种颓放的生活画面。","第三句“十年一觉扬州梦”：十年好像一场扬州的梦，醒来了。“一觉”是睡一觉，也是醒悟；“十年”是时间的长度，被“一觉”压缩成一瞬，这是对人生的轻轻一笑。","末句“赢得青楼薄幸名”：换得的只是青楼的薄情名声。“赢得”是反话：赢的其实是输。这个名声是对自己放浪生活的总结，带着自嘲，也带着无奈。有人读出悔意，有人读出自负，诗没有说明，是留白。"],"notes":[["落魄","失意潦倒"],["载酒行","带着酒游历"],["楚腰","指细腰的美女"],["纤细","细小"],["掌中轻","在掌中轻盈"],["十年","十年"],["一觉","一场睡梦"],["扬州梦","在扬州的风月之梦"],["赢得","博得"],["薄幸","薄情"]],"think":["“赢得青楼薄幸名”是悔恨还是自嘲？","更像自嘲。“赢得”二字本是得意的口吻，用来说自己得到的却是一个不好的名声，本身就带着反讽。是否真有悔意，读者可以有不同判断；比较稳妥的读法是：诗人对自己的放浪既不炫耀，也不完全否定。"],"quiz":[["“十年一觉扬州梦”的意思？",["十年扬州生活像一场梦","睡了十年","梦见扬州","在扬州住了一年"],"“一觉”是醒来的比喻，十年的放浪如梦初醒。"],["“赢得”在诗中的语气？",["反语，带自嘲","得意","感谢","平淡"],"赢到的是坏名声，用“赢得”是反讽。"]],"cards":[["“落魄江湖载酒行”的下一句？","楚腰纤细掌中轻。"],["《遣怀》的情感？","对放浪岁月的自嘲与淡淡悔意。"]],"line":["十年一觉扬州梦，赢得青楼薄幸名","回望自己年轻时的创业：十年一觉扬州梦，赢得青楼薄幸名——只剩下一堆账单。"],"tags":["七绝","自嘲","杜牧"]},"tangjin_qiuxi":{"intro":"杜牧的《秋夕》，也有版本归为王建所作，作者归属存疑，本书以《唐诗三百首》所署为准。诗里写的是秋夜里一位宫女：银烛、画屏、轻罗小扇、流萤，最后望着牵牛织女星。读它要看一首宫怨诗怎样不用一个“怨”字。","focus":["首句“银烛秋光冷画屏”：银色烛光，在秋夜里冷冷地照着画屏。“秋光”是烛光，也是秋色，一个“冷”字，让烛光、秋夜、画屏都冷了，是整首诗的底色。","第二句“轻罗小扇扑流萤”：用轻罗小扇扑流萤。宫女用团扇扑萤火虫，是一个孤独的动作，说明她无事可做，也说明她的寂寞。“扑”字是动作，也是消遣，是被迫的无聊。","后两句“天阶夜色凉如水，坐看牵牛织女星”：台阶上的夜色凉如水，她坐着看牵牛织女星。牛郎织女是一年一会的恋人，她看着，不言语。“坐看”是静，“凉如水”是感觉，结尾没有一个情字，情全在“看”里。"],"notes":[["银烛","银色的蜡烛"],["秋光","秋夜的光色"],["冷","清冷"],["画屏","绘有图画的屏风"],["轻罗","轻薄的丝织品"],["小扇","小团扇"],["扑流萤","扑打飞舞的萤火虫"],["天阶","宫中的台阶"],["凉如水","像水一样凉"],["牵牛织女星","牛郎星与织女星"]],"think":["为什么说这首宫怨诗“不用怨字”也怨？","因为每一个动作都是孤独的信号：独自对着烛、独自扑萤、独自坐看星。读者读到最后，自然会补上“怨”。直接说“怨”是告诉，不说“怨”是让读者自己发现，后者更有力量。"],"quiz":[["“轻罗小扇扑流萤”写的是？",["宫女无事可做的孤独","夏天的游戏","捕捉萤火虫","喜悦"],"扑萤是消遣，表明宫女寂寞无事。"],["结句“坐看牵牛织女星”的作用？",["以牛郎织女暗衬自己的孤独","描写星空","指示时间","表示欣赏"],"牛郎织女一年一会，与宫女长期孤守形成对比。"]],"cards":[["“银烛秋光冷画屏”的下一句？","轻罗小扇扑流萤。"],["《秋夕》的“怨”表现在哪里？","以独自扑萤、独自坐看星的孤独动作表现，不用言辞。"]],"line":["天阶夜色凉如水，坐看牵牛织女星","深夜阳台上没有开灯，一个人看天：天阶夜色凉如水，坐看牵牛织女星。"],"tags":["七绝","宫怨","杜牧"]},"tangjin_zengbie2":{"intro":"杜牧的《赠别》二首，是写给一位歌女的离别诗。第二首写的是分别的宴席：本来多情，却似无情，笑不出来，连蜡烛都替人流泪。读它要看“多情却似总无情”这句话的矛盾，以及“蜡烛有心”的拟人。","focus":["首句“多情却似总无情”：越是多情，反而显得无情。因为情太重，无法用平常的方式表达，只能沉默。这句话违背常理，却符合真实的离别心理。","第二句“唯觉樽前笑不成”：只觉得酒杯前，笑也笑不出来。想强颜欢笑，却做不到，这是“似无情”的具体表现。“笑不成”三字，把离别的沉默写得很真。","后两句“蜡烛有心还惜别，替人垂泪到天明”：蜡烛有“心”（烛芯）也舍不得离别，替人流泪到天亮。这里一语双关：“心”是烛芯，也是人心；“泪”是烛泪，也是人泪。人无法哭，让蜡烛替人哭，是含蓄而有力的转移。"],"notes":[["多情","感情深厚"],["总无情","处处显得无情"],["唯觉","只觉得"],["樽前","酒杯前"],["笑不成","笑不出来"],["蜡烛","蜡烛"],["有心","有烛芯，也有人心"],["惜别","舍不得分别"],["垂泪","流泪，指烛泪"],["天明","天亮"]],"think":["“多情却似总无情”为什么成立？","因为情的深浅与表达的强烈不一定成正比。情越深，越难找到合适的话；越想控制，越显得克制甚至冷淡。这句话说的是情感的悖论：真正动情的人，往往不知怎么表现。"],"quiz":[["“蜡烛有心还惜别”中“有心”的双关？",["烛芯与人心","蜡烛很大","蜡烛有感情","蜡烛是红色的"],"“心”既是烛芯，也是心意，双关使烛与人合一。"],["“唯觉樽前笑不成”的意思？",["离别时勉强也笑不出来","酒杯很美","大家都在笑","酒很好喝"],"“笑不成”是强颜欢笑也无法做到，是离别的沉重。"]],"cards":[["“多情却似总无情”的下一句？","唯觉樽前笑不成。"],["《赠别·其二》的修辞核心？","以蜡烛垂泪双关，代人哭泣。"]],"line":["蜡烛有心还惜别，替人垂泪到天明","公司的送别晚宴，没有人开口，只有桌上的蜡烛一滴滴往下流：蜡烛有心还惜别，替人垂泪到天明。"],"tags":["七绝","赠别","杜牧"]},"tangjin_change":{"intro":"李商隐的《嫦娥》，写的是一个人在深夜里想到嫦娥：偷了灵药，奔入月宫，从此夜夜面对碧海青天。诗里写嫦娥，也像写一个孤独的人。读它要看前两句的室内静景与后两句的天上孤心，怎样用“悔”字相连。","focus":["首二句“云母屏风烛影深，长河渐落晓星沈”：云母屏风前，烛影渐深；银河渐渐落下，晓星也沉没。时间从夜深到将晓，是整夜未眠的人所见。云母屏风是华美而冷的东西，与孤独的心情相配。","第三句“嫦娥应悔偷灵药”：嫦娥应当后悔偷了灵药。“应”字是推测，是诗人替嫦娥说的，也是对自己的心声的投射：人在孤独中，常想“当初”。","末句“碧海青天夜夜心”：面对碧海青天，夜夜都是这颗心。“夜夜心”是全诗最重的三个字：不是一夜，是夜夜；不是想法，是“心”。永生换来的是永远的孤独。这一句是否暗指李商隐自己的处境，存疑，各家说法不一。"],"notes":[["云母","一种透明的矿物，用来装饰屏风"],["屏风","室内的挡风或隔断的家具"],["烛影深","烛光暗淡"],["长河","银河"],["晓星","拂晓的星"],["沈","沉没"],["嫦娥","传说中奔月的仙女"],["灵药","长生不死之药"],["碧海","碧蓝的海，这里指夜空"],["夜夜心","夜夜如此的心情"]],"think":["为什么嫦娥的孤独被读成“人”的孤独？","因为诗里只写了一个人在夜里，没有任何仙界的热闹。读者很容易代入：为了某个目标放弃了日常，现在得到了，却更孤单。至于李商隐是否在写自己，诗里没有直接证据，这是读者常用的联想。"],"quiz":[["“嫦娥应悔偷灵药”中“应”字的含义？",["推测，是诗人的设想","必须","应该","应当"],"“应”是揣测之词，是诗人替嫦娥代言。"],["“碧海青天夜夜心”的重点在？",["“夜夜”，长久的孤独","碧海","青天","心"],"“夜夜”二字强调孤独持续不断。"]],"cards":[["“云母屏风烛影深”的下一句？","长河渐落晓星沈。"],["《嫦娥》的核心情感？","永生换来的孤独，夜夜面对碧海青天。"]],"line":["嫦娥应悔偷灵药，碧海青天夜夜心","深夜里一个人在总部大楼加班，想到当年放弃的选择：嫦娥应悔偷灵药，碧海青天夜夜心。"],"tags":["七绝","咏神话","李商隐"]},"tangjin_jiasheng":{"intro":"李商隐的《贾生》，咏的是汉文帝召见贾谊的故事。《史记》记载文帝在宣室召见贾谊，谈到深夜，问的是鬼神之事。李商隐借这个典故，写一个君王对人才的态度。读它要看“虚前席”三个字的讽刺。","focus":["首二句“宣室求贤访逐臣，贾生才调更无伦”：在宣室召见被放逐的臣子，贾生的才华更是无人能比。“求贤”“访逐臣”看起来是美事，“更无伦”是对贾谊的极高评价。前两句铺垫得很高，是为了让后两句摔下来。","第三句“可怜夜半虚前席”：可惜深夜里，文帝把座席向前挪近，却是白费。“虚前席”是关键：前席是君王听得入神，座位不由自主向前移。“虚”是落空：这样一个动作，最后成了空。","末句“不问苍生问鬼神”：不问百姓，问的是鬼神。这句话是全诗的重点：本该问治国安民，却问了不着边际的事。讽刺的对象不只是汉文帝，也指向诗人所处时代那些迷信神仙的皇帝，具体所指，学者看法不一，存疑。"],"notes":[["宣室","汉代未央宫前殿的正室"],["求贤","寻求贤人"],["访","询问"],["逐臣","被放逐的臣子"],["贾生","贾谊"],["才调","才华与风度"],["更无伦","无人可比"],["夜半","半夜"],["虚前席","徒然把座席向前移"],["苍生","百姓"],["鬼神","鬼与神"]],"think":["“不问苍生问鬼神”的讽刺有什么特点？","它用的是反差：对象的行为极其投入（夜半前席），内容却极其空泛（问鬼神）。讽刺不靠谩骂，只靠一个前后落差：认真的姿态，错位的内容。这种写法让评价显得克制而尖锐。"],"quiz":[["“夜半虚前席”的含义是？",["君王前移座席认真听，结果落空","夜里很冷","座席很虚弱","皇帝睡了"],"“前席”是靠近听，“虚”是落空，指听了半天听的是鬼神。"],["末句的讽刺对象是？",["不关心百姓而迷信鬼神的君主","贾谊","百姓","鬼神"],"“不问苍生问鬼神”批评的是不务正事的执政者。"]],"cards":[["“宣室求贤访逐臣”的下一句？","贾生才调更无伦。"],["《贾生》的讽刺艺术？","以前三句铺垫，末句以“不问苍生”一语翻转。"]],"line":["可怜夜半虚前席，不问苍生问鬼神","参加一个听了三小时却没谈到核心问题的会议：可怜夜半虚前席，不问苍生问鬼神。"],"tags":["七绝","咏史","李商隐"]},"tangjin_changxin":{"intro":"王昌龄的《长信怨》，长信宫是汉成帝时班婕妤失宠后居住的地方，诗里写的是一位在长信宫里的宫女：每天清晨扫地，拿着团扇徘徊，把自己与寒鸦相比。读它要看“玉颜不及寒鸦色”这一句，为什么是全诗最痛的地方。","focus":["首二句“奉帚平明金殿开，且将团扇共徘徊”：天一亮，金殿开了，她拿着扫帚去打扫；暂且拿着团扇徘徊。“奉帚”是做杂役，“团扇”是班婕妤《怨歌行》中以秋扇自比弃置的典故。她本该是被宠爱的人，现在做着扫地的活。","第三句“玉颜不及寒鸦色”：美丽的容颜比不上寒鸦。寒鸦是黑色的、寒冷的乌鸦，却“犹带昭阳日影来”。美貌与乌鸦对比，是荒唐的，也是真实的：失宠的人，连乌鸦都比不上。","末句“犹带昭阳日影来”：乌鸦还带着昭阳殿的日光飞来。昭阳殿是赵飞燕姐妹得宠时居住的宫殿，是皇帝宠爱的地方。乌鸦从那里飞来，身上还带着阳光，而她没有。这句话把“恩宠”写成一种光：有的人沐浴其中，有的人只能在远处看。"],"notes":[["奉帚","手持扫帚，指做洒扫之事"],["平明","天亮时"],["金殿","华丽的宫殿"],["团扇","圆形的扇子，象征被弃的女子"],["徘徊","来回走动"],["玉颜","美丽的容颜"],["寒鸦","寒天的乌鸦"],["犹带","还带着"],["昭阳","昭阳殿，得宠妃嫔的居所"],["日影","日光的影子"]],"think":["“玉颜不及寒鸦色”为什么是荒诞又真实？","美貌与乌鸦本没有可比性，诗人故意比，是想说：失去恩宠，美貌也不值钱。乌鸦能飞到昭阳，她却不能；乌鸦能带来阳光，她只有阴影。把比较的荒谬推到极致，才使这个怨更痛。"],"quiz":[["“昭阳日影”象征什么？",["皇帝的恩宠","宫殿的位置","太阳的光","时间"],"昭阳殿是得宠者所居，日影代指恩宠。"],["“且将团扇共徘徊”的含意？",["以团扇暗喻被弃的命运","拿着扇子乘凉","练习舞蹈","寻找东西"],"团扇是秋天被弃的象征，暗用班婕妤的典故。"]],"cards":[["“奉帚平明金殿开”的下一句？","且将团扇共徘徊。"],["《长信怨》最痛的一句？","“玉颜不及寒鸦色”，以乌鸦衬失宠。"]],"line":["玉颜不及寒鸦色，犹带昭阳日影来","被调离核心项目的前辈，看着年轻人走进总裁办公室：玉颜不及寒鸦色，犹带昭阳日影来。"],"tags":["七绝","宫怨","王昌龄"]},"tangjin_chusai1":{"intro":"王昌龄的《出塞》，被很多人称为七绝压卷之作。它先把时间放大到秦汉，再把空间放大到万里，最后用“但使龙城飞将在”做一个假设。读它要看开头七个字怎样把月与关合成一个历史意象。","focus":["首句“秦时明月汉时关”：月是秦时的月，关是汉时的关。明月与关本是眼前所见，诗人却加上了时间的前缀：秦、汉。这是“互文”的写法，意思是秦汉时的明月与关隘，这样的月和关从古到今一直在那里。","第二句“万里长征人未还”：万里远征的人，至今未回。“未还”与“秦时明月汉时关”连起来，说明这种战争已持续千年，人也一代一代没有回来。时间与空间同时拉开。","后两句“但使龙城飞将在，不教胡马渡阴山”：只要龙城飞将还在，就不让胡人的马越过阴山。“龙城飞将”一般指汉代名将李广（也有说卫青），具体存疑。这是对良将的怀念，也是对当时将领的不满：现在没有这样的人，才让战争无休止。"],"notes":[["秦时明月","秦代的明月"],["汉时关","汉代的关隘"],["万里","极远的距离"],["长征","远行出征"],["人未还","人还没有回来"],["但使","只要"],["龙城","匈奴祭天之地，这里指边塞"],["飞将","飞将军，一般指李广"],["胡马","胡人的战马"],["阴山","阴山山脉"]],"think":["“秦时明月汉时关”的互文是什么意思？","互文是前后句各省一半，合起来才完整：秦汉时的明月与关。这样写，月与关同时有了历史的深度。读的时候，不必分别去想“秦的月”“汉的关”，而是想：同一轮月，从秦到汉到唐，一直照着边关与远征的人。"],"quiz":[["“秦时明月汉时关”采用的是？",["互文","对偶","夸张","比喻"],"秦汉时的明月与关，互文合成一个意思。"],["“龙城飞将”一般指？",["汉代名将李广","秦始皇","唐太宗","匈奴将领"],"通常认为指李广，也有说卫青，存疑。"]],"cards":[["“秦时明月汉时关”的下一句？","万里长征人未还。"],["《出塞》的主题？","由千古征战怀念良将，表达对边防的忧思。"]],"line":["但使龙城飞将在，不教胡马渡阴山","谈到团队里缺少一个真正能扛事的人：但使龙城飞将在，不教胡马渡阴山。"],"tags":["七绝","边塞","王昌龄"]},"tangjin_qingping1":{"intro":"李白的《清平调》共三首，相传是玄宗与杨贵妃在宫中赏牡丹时，命李白作新词。这一类故事见于唐人笔记，具体情节存疑，但三首诗确实是以花喻人的应制之作。第一首读起来最轻灵：用云、花、露、群玉山、瑶台，把美人写成仙子。","focus":["首句“云想衣裳花想容”：看见云就想到她的衣裳，看见花就想到她的容貌。这是一个反向的比喻：不是以云比衣，而是云看着像衣，花看着像容。景物与人互相联想，产生一种轻盈。","第二句“春风拂槛露华浓”：春风吹过栏杆，露水浓厚。这是写花，也是写人：露华是光泽，既指牡丹上的露，也指美人的容光。","后两句“若非群玉山头见，会向瑶台月下逢”：若不是在群玉山头见到，那就是在瑶台月下相逢。群玉山、瑶台都是传说中西王母居住的仙境，意思是：这样的美，不是人间所有。全诗不写任何一个具体的动作，只用比喻，写出贵妃的光彩。"],"notes":[["云想衣裳","云让人想到衣裳"],["花想容","花让人想到容貌"],["拂槛","吹拂栏杆"],["露华","露水的光泽"],["浓","浓厚"],["群玉山","传说中西王母所居之山"],["山头","山顶"],["瑶台","神话中仙人的居所"],["月下","月光下"],["会","应当"]],"think":["应制诗为什么常被认为“难出好诗”？","因为内容与对象事先规定，诗人要在颂扬的框架内写出新意。李白这首的特点是：用轻灵的比喻代替颂词，没有一个“美”字，却让人感到美。这是应制诗里难得的成功，也说明天才往往在限制中找到出口。"],"quiz":[["“云想衣裳花想容”的特点？",["反向联想，景物让人想到人","直接比喻","对比","夸张"],"不是“人像花”，而是“花让人想到容”，把关系倒过来。"],["“群玉山头”“瑶台”指的是？",["神话中的仙境","唐代宫殿","隐居之所","李白的家乡"],"都是西王母相关的传说仙境。"]],"cards":[["“云想衣裳花想容”的下一句？","春风拂槛露华浓。"],["《清平调·其一》的写法？","以仙境和景物比喻美人，不用直接颂词。"]],"line":["云想衣裳花想容，春风拂槛露华浓","第一次见到一位气质出众的演讲嘉宾，心里默念：云想衣裳花想容，春风拂槛露华浓。"],"tags":["七绝","应制","李白"]},"tangjin_chusai2":{"intro":"王之涣的《出塞》，在不少版本里也题作《凉州词》。写的是黄河边的一座孤城，听到羌笛吹《折杨柳》。它的气象极大，感情极含蓄。读它要看前两句的壮阔如何托起后两句的哀怨。","focus":["首句“黄河远上白云间”：黄河远远地向上，直到白云之间。这是从下游向上游看，黄河像一条白色的带子伸向云端。一个“上”字，把平常的河流写成一个向天而去的形象。","第二句“一片孤城万仞山”：一座孤零零的城，在万仞高山之中。“一片”与“万仞”，小与大；“孤城”与“山”，近与远。城孤，山高，边塞的孤绝感被写到极致。","后两句“羌笛何须怨杨柳，春风不度玉门关”：羌笛何必再吹怨别的《杨柳》，春风本来就吹不到玉门关。《折杨柳》是离别之曲，“怨”是笛声的情感；“春风不度”是自然的事实，也含边地之寒和朝廷恩泽不至的暗示。后一层是否存在，读者可有不同看法。"],"notes":[["远上","向远处向上"],["白云间","白云之间"],["孤城","孤零零的城"],["万仞","极高，仞是古代长度单位"],["羌笛","羌族的笛子"],["何须","何必"],["怨杨柳","吹《折杨柳》的怨曲"],["春风","春天的风"],["不度","不能越过"],["玉门关","古代通西域的关隘"]],"think":["“春风不度玉门关”是自然现象还是政治暗示？","字面是边塞春迟，春风吹不到。因为前一句提到“怨杨柳”，有人读出朝廷恩泽不及边塞的含意。两种读法都成立，诗没有给出判断。读时可保留两层：写实的荒凉与可能的含蓄。"],"quiz":[["“一片孤城万仞山”的特点？",["以大小对比写孤绝","写城市繁华","写战争","写人物"],"“一片”与“万仞”对比，孤城显得极其渺小。"],["“羌笛何须怨杨柳”的含意？",["何必吹这怨别的曲子，春风本不到此","笛声很美","杨柳很多","想听杨柳曲"],"诗人劝慰：怨也没用，春风本来就吹不过玉门关。"]],"cards":[["“黄河远上白云间”的下一句？","一片孤城万仞山。"],["《出塞（黄河远上）》的情感？","壮阔之中含无声的哀怨。"]],"line":["羌笛何须怨杨柳，春风不度玉门关","对被派驻偏远地区的同事说：羌笛何须怨杨柳，春风不度玉门关——条件就是这样。"],"tags":["七绝","边塞","王之涣"]},"tangjin_jinlu":{"intro":"《金缕衣》，《唐诗三百首》署杜秋娘，一说作者无名氏，存疑。诗的口气像民歌，直接劝人：别爱惜华美的金缕衣，要珍惜少年时。读它要看重复的“劝君”与“花开堪折直须折”的比喻，怎样把一个道理说得像一句口令。","focus":["首二句“劝君莫惜金缕衣，劝君惜取少年时”：劝你别可惜金缕衣，劝你珍惜少年时。“劝君”重复两次，节奏像歌。金缕衣是贵重的东西，被拿来与少年时相比：贵重的衣服不值得珍惜，时间才值得。","第三句“花开堪折直须折”：花开了，可以折，就立即折。“堪”与“直须”是口语，没有任何委婉。把惜时写成折花，是具体的动作，不是抽象的口号。","末句“莫待无花空折枝”：不要等到没有花了，只能折空枝。前句是劝，这句是警告：错过的代价，是空枝。对“折花”的解读历来有分歧：有人读作劝人珍惜青春，有人读作劝人行乐，诗没有限制。"],"notes":[["劝君","劝你"],["莫惜","不要吝惜"],["金缕衣","用金线织成的华贵衣服"],["惜取","珍惜"],["少年时","年轻的时光"],["花开","花开放"],["堪折","可以折"],["直须","就应当"],["莫待","不要等到"],["空折枝","只折到空枝"]],"think":["“花开堪折直须折”是在劝人行乐吗？","字面上是，但也可以读成劝人把握机会：事业、感情、学业都有“花期”。诗没有限定“花”是什么，这种开放正是它流传至今的原因。只是引用时要明确自己取的是哪一层，避免把一句民歌口吻当成人生信条。"],"quiz":[["“劝君莫惜金缕衣”的含意？",["不要吝惜华贵之物，更重要的是时间","要珍惜衣服","要买衣服","要节俭"],"把金缕衣与少年时对比，说明时间比财物更贵重。"],["“莫待无花空折枝”表达的是？",["警告错过时机的后果","赞美折枝","描写冬景","劝人种花"],"“空折枝”是错过花期的下场，是警告。"]],"cards":[["“劝君莫惜金缕衣”的下一句？","劝君惜取少年时。"],["《金缕衣》的语言特点？","口语化、重复，像民歌。"]],"line":["花开堪折直须折，莫待无花空折枝","团队里有人犹豫要不要抓住一个新机会，说：花开堪折直须折，莫待无花空折枝。"],"tags":["七绝","惜时","民歌体"]}});
